class ResourceRepository:
    """项目内置资源库；不访问 ShadowBot 或影刀安装目录。"""

    def __init__(self, root: Path) -> None:
        self.root = root.expanduser().resolve()
        self.images = self._materialize_images()
        self.selectors = self._load_builtin_selectors()

    @staticmethod
    def _validate_png_bytes(filename: str, image_data: bytes) -> None:
        """在资源检查阶段验证 PNG 结构与每个数据块 CRC。"""

        if not image_data.startswith(b"\x89PNG\r\n\x1a\n"):
            raise AutomationError(f"内置图片不是有效 PNG：{filename}")
        offset = 8
        saw_header = False
        saw_end = False
        while offset + 12 <= len(image_data):
            length = int.from_bytes(image_data[offset : offset + 4], "big")
            chunk_end = offset + 12 + length
            if chunk_end > len(image_data):
                raise AutomationError(f"内置 PNG 数据块不完整：{filename}")
            chunk_type = image_data[offset + 4 : offset + 8]
            chunk_data = image_data[offset + 8 : offset + 8 + length]
            stored_crc = int.from_bytes(
                image_data[offset + 8 + length : chunk_end],
                "big",
            )
            actual_crc = zlib.crc32(chunk_type + chunk_data) & 0xFFFFFFFF
            if stored_crc != actual_crc:
                raise AutomationError(
                    f"内置 PNG 校验失败（{chunk_type.decode('ascii', errors='replace')}）：{filename}"
                )
            if chunk_type == b"IHDR":
                saw_header = length == 13
            if chunk_type == b"IEND":
                saw_end = True
                offset = chunk_end
                break
            offset = chunk_end
        if not saw_header or not saw_end or offset != len(image_data):
            raise AutomationError(f"内置 PNG 结构不完整：{filename}")

    def _materialize_images(self) -> dict[str, ImageSpec]:
        try:
            archive_bytes = base64.b64decode(
                BUILTIN_ASSET_ARCHIVE_BLOB.encode("ascii"), validate=True
            )
            archive = zipfile.ZipFile(BytesIO(archive_bytes))
            manifest = json.loads(archive.read("manifest.json").decode("utf-8"))
        except Exception as exc:
            raise AutomationError("内置图像资源损坏，无法解包") from exc

        image_dir = self.root / "images"
        try:
            image_dir.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            raise AutomationError(f"无法创建项目图片目录：{image_dir}") from exc

        images: dict[str, ImageSpec] = {}
        # 目标电脑的新客户端在 90% 显示缩放下重新抗锯齿，旧影刀模板的
        # 实测分数分别约为 0.764 和 0.704；这两个模板包含完整中文菜单文字，
        # 适度降低阈值仍能可靠区分，同时兼容新旧客户端。
        confidence_overrides = {
            "综合申报": 0.72,
            "正常工资所得": 0.65,
            "申报过": 0.64,
        }
        try:
            for name, values in manifest.items():
                filename, confidence, adaptive = values
                member = f"images/{filename}"
                image_data = archive.read(member)
                self._validate_png_bytes(filename, image_data)
                target = (image_dir / filename).resolve()
                if target.parent != image_dir.resolve():
                    raise AutomationError(f"内置图片路径非法：{filename}")
                if not target.exists() or target.read_bytes() != image_data:
                    temporary = target.with_suffix(target.suffix + ".tmp")
                    temporary.write_bytes(image_data)
                    os.replace(temporary, target)
                images[name] = ImageSpec(
                    name=name,
                    path=target,
                    confidence=float(confidence_overrides.get(name, confidence)),
                    adaptive=bool(adaptive),
                )
            for name, values in BUILTIN_STATE_IMAGE_BLOBS.items():
                filename, confidence, adaptive, encoded = values
                image_data = base64.b64decode(encoded.encode("ascii"), validate=True)
                self._validate_png_bytes(filename, image_data)
                target = (image_dir / filename).resolve()
                if target.parent != image_dir.resolve():
                    raise AutomationError(f"内置状态图片路径非法：{filename}")
                if not target.exists() or target.read_bytes() != image_data:
                    temporary = target.with_suffix(target.suffix + ".tmp")
                    temporary.write_bytes(image_data)
                    os.replace(temporary, target)
                images[name] = ImageSpec(
                    name=name,
                    path=target,
                    confidence=float(confidence),
                    adaptive=bool(adaptive),
                )
        except OSError as exc:
            raise AutomationError(f"无法释放项目内置图片到：{image_dir}") from exc
        finally:
            archive.close()

        if len(images) != 12:
            raise AutomationError(f"内置图像数量异常：期望 12，实际 {len(images)}")
        return images

    @staticmethod
    def _load_builtin_selectors() -> dict[str, SelectorSpec]:
        try:
            compressed = base64.b64decode(
                BUILTIN_SELECTOR_BLOB.encode("ascii"), validate=True
            )
            payload = json.loads(zlib.decompress(compressed).decode("utf-8"))
        except Exception as exc:
            raise AutomationError("内置控件定义损坏，无法读取") from exc

        selectors: dict[str, SelectorSpec] = {}
        for name, item in payload.items():
            steps = tuple(SelectorStep(*values) for values in item["s"])
            selectors[name] = SelectorSpec(
                name=name,
                process_name=item.get("p", "EPPortalITS"),
                steps=steps,
            )
        if len(selectors) != 32:
            raise AutomationError(
                f"内置控件数量异常：期望 32，实际 {len(selectors)}"
            )
        return selectors



_DPI_AWARENESS_INITIALIZED = False


class _BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [
        ("biSize", wintypes.DWORD),
        ("biWidth", wintypes.LONG),
        ("biHeight", wintypes.LONG),
        ("biPlanes", wintypes.WORD),
        ("biBitCount", wintypes.WORD),
        ("biCompression", wintypes.DWORD),
        ("biSizeImage", wintypes.DWORD),
        ("biXPelsPerMeter", wintypes.LONG),
        ("biYPelsPerMeter", wintypes.LONG),
        ("biClrUsed", wintypes.DWORD),
        ("biClrImportant", wintypes.DWORD),
    ]


class _RGBQUAD(ctypes.Structure):
    _fields_ = [
        ("rgbBlue", wintypes.BYTE),
        ("rgbGreen", wintypes.BYTE),
        ("rgbRed", wintypes.BYTE),
        ("rgbReserved", wintypes.BYTE),
    ]


class _BITMAPINFO(ctypes.Structure):
    _fields_ = [
        ("bmiHeader", _BITMAPINFOHEADER),
        ("bmiColors", _RGBQUAD * 1),
    ]


def _enable_dpi_awareness() -> None:
    """让截图坐标与鼠标/Win32 坐标在高 DPI 显示器上保持一致。"""

    global _DPI_AWARENESS_INITIALIZED
    if _DPI_AWARENESS_INITIALIZED:
        return
    _DPI_AWARENESS_INITIALIZED = True
    try:
        user32 = ctypes.WinDLL("user32", use_last_error=True)
        setter = getattr(user32, "SetProcessDpiAwarenessContext", None)
        if setter is not None:
            setter.argtypes = [wintypes.HANDLE]
            setter.restype = wintypes.BOOL
            if setter(ctypes.c_void_p(-4)):
                return
    except Exception:
        pass
    try:
        shcore = ctypes.WinDLL("shcore", use_last_error=True)
        shcore.SetProcessDpiAwareness.argtypes = [ctypes.c_int]
        shcore.SetProcessDpiAwareness.restype = ctypes.c_long
        shcore.SetProcessDpiAwareness(2)
        return
    except Exception:
        pass
    try:
        ctypes.windll.user32.SetProcessDPIAware()
    except Exception:
        pass


def _capture_screen_bgr(np_module: Any) -> tuple[Any, int, int]:
    """用 Windows GDI 截取虚拟桌面，避免依赖 Pillow/PyScreeze。"""

    _enable_dpi_awareness()
    user32 = ctypes.WinDLL("user32", use_last_error=True)
    gdi32 = ctypes.WinDLL("gdi32", use_last_error=True)

    user32.GetSystemMetrics.argtypes = [ctypes.c_int]
    user32.GetSystemMetrics.restype = ctypes.c_int
    user32.GetDC.argtypes = [wintypes.HWND]
    user32.GetDC.restype = wintypes.HDC
    user32.ReleaseDC.argtypes = [wintypes.HWND, wintypes.HDC]
    user32.ReleaseDC.restype = ctypes.c_int
    gdi32.CreateCompatibleDC.argtypes = [wintypes.HDC]
    gdi32.CreateCompatibleDC.restype = wintypes.HDC
    gdi32.CreateCompatibleBitmap.argtypes = [wintypes.HDC, ctypes.c_int, ctypes.c_int]
    gdi32.CreateCompatibleBitmap.restype = wintypes.HBITMAP
    gdi32.SelectObject.argtypes = [wintypes.HDC, wintypes.HGDIOBJ]
    gdi32.SelectObject.restype = wintypes.HGDIOBJ
    gdi32.BitBlt.argtypes = [
        wintypes.HDC,
        ctypes.c_int,
        ctypes.c_int,
        ctypes.c_int,
        ctypes.c_int,
        wintypes.HDC,
        ctypes.c_int,
        ctypes.c_int,
        wintypes.DWORD,
    ]
    gdi32.BitBlt.restype = wintypes.BOOL
    gdi32.GetDIBits.argtypes = [
        wintypes.HDC,
        wintypes.HBITMAP,
        wintypes.UINT,
        wintypes.UINT,
        wintypes.LPVOID,
        ctypes.POINTER(_BITMAPINFO),
        wintypes.UINT,
    ]
    gdi32.GetDIBits.restype = ctypes.c_int
    gdi32.DeleteObject.argtypes = [wintypes.HGDIOBJ]
    gdi32.DeleteObject.restype = wintypes.BOOL
    gdi32.DeleteDC.argtypes = [wintypes.HDC]
    gdi32.DeleteDC.restype = wintypes.BOOL

    # SM_X/Y/CX/CYVIRTUALSCREEN：兼容副屏位于主屏左侧时的负坐标。
    origin_x = user32.GetSystemMetrics(76)
    origin_y = user32.GetSystemMetrics(77)
    width = user32.GetSystemMetrics(78)
    height = user32.GetSystemMetrics(79)
    if width <= 0 or height <= 0:
        raise DependencyError(f"无法取得桌面尺寸：{width}x{height}")

    screen_dc = user32.GetDC(None)
    memory_dc = None
    bitmap = None
    old_object = None
    try:
        if not screen_dc:
            raise DependencyError(
                f"Windows GDI 获取桌面失败（错误码 {ctypes.get_last_error()}）"
            )
        memory_dc = gdi32.CreateCompatibleDC(screen_dc)
        if not memory_dc:
            raise DependencyError(
                f"Windows GDI 创建内存画布失败（错误码 {ctypes.get_last_error()}）"
            )
        bitmap = gdi32.CreateCompatibleBitmap(screen_dc, width, height)
        if not bitmap:
            raise DependencyError(
                f"Windows GDI 创建截图位图失败（错误码 {ctypes.get_last_error()}）"
            )
        old_object = gdi32.SelectObject(memory_dc, bitmap)
        if not old_object:
            raise DependencyError(
                f"Windows GDI 选择截图位图失败（错误码 {ctypes.get_last_error()}）"
            )

        srccopy = 0x00CC0020
        captureblt = 0x40000000
        if not gdi32.BitBlt(
            memory_dc,
            0,
            0,
            width,
            height,
            screen_dc,
            origin_x,
            origin_y,
            srccopy | captureblt,
        ):
            raise DependencyError(
                f"Windows GDI 复制桌面失败（错误码 {ctypes.get_last_error()}）"
            )

        # GetDIBits 要求目标位图不能仍被选入任何 DC。先恢复旧对象，
        # 否则部分显卡驱动会返回 0，哪怕同一代码在开发机上可以运行。
        restored_object = gdi32.SelectObject(memory_dc, old_object)
        if not restored_object:
            raise DependencyError(
                f"Windows GDI 取消选择截图位图失败（错误码 {ctypes.get_last_error()}）"
            )
        old_object = None

        info = _BITMAPINFO()
        info.bmiHeader.biSize = ctypes.sizeof(_BITMAPINFOHEADER)
        info.bmiHeader.biWidth = width
        info.bmiHeader.biHeight = -height  # 负值表示自上而下，免去垂直翻转。
        info.bmiHeader.biPlanes = 1
        info.bmiHeader.biBitCount = 32
        info.bmiHeader.biCompression = 0  # BI_RGB
        buffer = ctypes.create_string_buffer(width * height * 4)
        copied_lines = gdi32.GetDIBits(
            memory_dc,
            bitmap,
            0,
            height,
            buffer,
            ctypes.byref(info),
            0,
        )
        if copied_lines != height:
            raise DependencyError(
                "Windows GDI 读取截图失败："
                f"读取 {copied_lines}/{height} 行（错误码 {ctypes.get_last_error()}）"
            )
        # 32 位 DIB 的通道顺序为 BGRA；OpenCV 直接使用前三个 BGR 通道。
        frame = np_module.frombuffer(buffer, dtype=np_module.uint8)
        frame = frame.reshape((height, width, 4))[:, :, :3].copy()
        return frame, origin_x, origin_y
    finally:
        if memory_dc and old_object:
            gdi32.SelectObject(memory_dc, old_object)
        if bitmap:
            gdi32.DeleteObject(bitmap)
        if memory_dc:
            gdi32.DeleteDC(memory_dc)
        if screen_dc:
            user32.ReleaseDC(None, screen_dc)


def _write_bgr_png(path: Path, frame: Any, cv2_module: Any) -> None:
    ok, encoded = cv2_module.imencode(".png", frame)
    if not ok:
        raise AutomationError(f"OpenCV 无法编码截图：{path}")
    path.write_bytes(encoded.tobytes())


def _load_ui_dependencies() -> tuple[Any, Any, Any, Any, Any]:
    # PyAutoGUI 的 Windows 后端导入时会设置旧式 DPI awareness；必须在它
    # 之前启用 Per-Monitor V2，异缩放多屏下截图、控件和鼠标坐标才一致。
    _enable_dpi_awareness()
    try:
        import cv2  # type: ignore
        import numpy as np  # type: ignore
        import pyautogui  # type: ignore
        from pywinauto import Desktop  # type: ignore
        from pywinauto import keyboard  # type: ignore
    except ImportError as exc:
        raise DependencyError(
            "缺少桌面自动化依赖，请执行："
            "python -m pip install pywinauto pyautogui opencv-python numpy"
        ) from exc
    pyautogui.FAILSAFE = True
    pyautogui.PAUSE = 0.15
    return cv2, np, pyautogui, Desktop, keyboard


class ImageMatcher:
    """使用 OpenCV 在屏幕中定位影刀图像模板。"""

    def __init__(self, images: Mapping[str, ImageSpec]) -> None:
        self.images = dict(images)
        self.cv2, self.np, self.pyautogui, _, _ = _load_ui_dependencies()

    def _match_once(self, spec: ImageSpec) -> tuple[int, int, int, int, float] | None:
        screen, origin_x, origin_y = _capture_screen_bgr(self.np)
        # cv2.imread 在部分 Windows/OpenCV 组合下无法读取含中文的路径；
        # 先按字节读取再解码，可兼容自定义中文 resource-root。
        try:
            template_bytes = self.np.fromfile(spec.path, dtype=self.np.uint8)
            template = self.cv2.imdecode(template_bytes, self.cv2.IMREAD_COLOR)
        except OSError:
            template = None
        if template is None:
            raise AutomationError(f"无法读取图像模板：{spec.path}")

        scales = (
            (1.0, 0.90, 0.92, 1.10, 0.80, 1.25, 1.50)
            if spec.adaptive
            else (1.0,)
        )
        best: tuple[int, int, int, int, float] | None = None
        for scale in scales:
            if scale == 1.0:
                candidate = template
            else:
                candidate = self.cv2.resize(
                    template,
                    None,
                    fx=scale,
                    fy=scale,
                    interpolation=(
                        self.cv2.INTER_AREA if scale < 1 else self.cv2.INTER_CUBIC
                    ),
                )
            height, width = candidate.shape[:2]
            if height > screen.shape[0] or width > screen.shape[1] or min(height, width) < 2:
                continue
            result = self.cv2.matchTemplate(
                screen, candidate, self.cv2.TM_CCOEFF_NORMED
            )
            _, score, _, location = self.cv2.minMaxLoc(result)
            current = (
                origin_x + location[0],
                origin_y + location[1],
                width,
                height,
                float(score),
            )
            if best is None or current[4] > best[4]:
                best = current
        if best and best[4] >= spec.confidence:
            return best
        return None

    def locate(
        self,
        name: str,
        timeout: float = 5.0,
        required: bool = True,
    ) -> tuple[int, int, int, int, float] | None:
        if name not in self.images:
            raise KeyError(f"未知图像模板：{name}")
        spec = self.images[name]
        deadline = time.monotonic() + max(timeout, 0)
        while True:
            match = self._match_once(spec)
            if match:
                LOGGER.debug("找到图像 %s，相似度 %.3f", name, match[4])
                return match
            if time.monotonic() >= deadline:
                if required:
                    raise AutomationError(f"等待图像 {name!r} 超时（{timeout:g} 秒）")
                return None
            time.sleep(0.5)

    def exists(self, name: str, timeout: float = 0.0) -> bool:
        return self.locate(name, timeout=timeout, required=False) is not None

    def click(
        self,
        name: str,
        timeout: float = 5.0,
        clicks: int = 1,
    ) -> None:
        match = self.locate(name, timeout=timeout, required=True)
        assert match is not None
        self.click_match(match, clicks=clicks)

    def click_match(
        self,
        match: tuple[int, int, int, int, float],
        clicks: int = 1,
    ) -> None:
        """点击调用方已经完成宿主范围校验的同一次图片匹配结果。"""

        x, y, width, height, _ = match
        self.pyautogui.click(
            x + width // 2,
            y + height // 2,
            clicks=clicks,
            interval=0.15,
        )
        time.sleep(0.8)


def _wrapper_class_name(wrapper: Any) -> str:
    try:
        return str(wrapper.element_info.class_name or "")
    except Exception:
        return ""


def _wrapper_text(wrapper: Any) -> str:
    try:
        return str(wrapper.window_text() or "")
    except Exception:
        try:
            texts = wrapper.texts()
            return " ".join(str(value) for value in texts if value)
        except Exception:
            return ""


def _matches_step(
    wrapper: Any,
    step: SelectorStep,
    ignore_exact_title: bool = False,
) -> bool:
    if (
        step.class_name
        and _wrapper_class_name(wrapper).casefold() != step.class_name.casefold()
    ):
        return False
    text = _wrapper_text(wrapper)
    if step.title and not ignore_exact_title and text != step.title:
        return False
    if step.wildcard_title and not fnmatch.fnmatch(text, step.wildcard_title):
        return False
    if step.contains_text and step.contains_text not in text:
        return False
    if step.regex_text and re.search(step.regex_text, text) is None:
        return False
    return True


class Win32SelectorDriver:
    """按本文件内置的控件层级查找并操作 Win32 控件。"""

    def __init__(self, selectors: Mapping[str, SelectorSpec]) -> None:
        self.selectors = dict(selectors)
        _, _, _, self.Desktop, self.keyboard = _load_ui_dependencies()
        self._pid_cache_time = 0.0
        self._pid_cache: tuple[int, ...] = ()

    def _target_process_ids(self) -> tuple[int, ...]:
        now = time.monotonic()
        if now - self._pid_cache_time < 2:
            return self._pid_cache
        try:
            completed = subprocess.run(
                [
                    "tasklist",
                    "/FI",
                    f"IMAGENAME eq {PROCESS_IMAGE}",
                    "/FO",
                    "CSV",
                    "/NH",
                ],
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                check=False,
                timeout=5,
            )
            output = completed.stdout.decode("mbcs", errors="replace")
            process_ids: list[int] = []
            for row in csv.reader(StringIO(output)):
                if len(row) < 2 or row[0].casefold() != PROCESS_IMAGE.casefold():
                    continue
                try:
                    process_ids.append(int(row[1].replace(",", "")))
                except ValueError:
                    continue
            self._pid_cache = tuple(process_ids)
        except Exception:
            self._pid_cache = ()
        self._pid_cache_time = now
        return self._pid_cache

    def _desktop_candidates(self, step: SelectorStep, backend: str = "win32") -> list[Any]:
        desktop = self.Desktop(backend=backend)
        process_ids = self._target_process_ids()
        try:
            if process_ids:
                top_windows = []
                for process_id in process_ids:
                    top_windows.extend(list(desktop.windows(process=process_id)))
            else:
                top_windows = list(desktop.windows())
        except Exception:
            return []

        # 影刀记录的第一个节点有时并非真正的顶层窗口（例如
        # Tfrm_LoginViewer 位于主窗口内部），因此顶层未命中时继续查其后代。
        candidates = [item for item in top_windows if _matches_step(item, step)]
        # 只有确认目标进程后才扫描后代，避免 UIA 枚举整个桌面导致长时间卡住。
        if process_ids:
            for window in top_windows:
                try:
                    candidates.extend(
                        item for item in window.descendants() if _matches_step(item, step)
                    )
                except Exception:
                    continue
        if candidates:
            return self._unique_wrappers(candidates)

        # 不同客户端版本可能修改内部标题，但 Delphi 类名通常保持不变。
        if step.title and step.class_name:
            candidates = [
                item
                for item in top_windows
                if _matches_step(item, step, ignore_exact_title=True)
            ]
            if process_ids:
                for window in top_windows:
                    try:
                        candidates.extend(
                            item
                            for item in window.descendants()
                            if _matches_step(item, step, ignore_exact_title=True)
                        )
                    except Exception:
                        continue
        return self._unique_wrappers(candidates)

    @staticmethod
    def _unique_wrappers(values: Iterable[Any]) -> list[Any]:
        result: list[Any] = []
        seen: set[Any] = set()
        for wrapper in values:
            try:
                identity: Any = ("handle", int(wrapper.handle))
            except Exception:
                identity = ("object", id(wrapper))
            if identity not in seen:
                seen.add(identity)
                result.append(wrapper)
        return result

    @staticmethod
    def _wrapper_priority(wrapper: Any) -> tuple[int, int, int]:
        try:
            visible = int(bool(wrapper.is_visible()))
        except Exception:
            visible = 0
        try:
            enabled = int(bool(wrapper.is_enabled()))
        except Exception:
            enabled = 0
        try:
            rectangle = wrapper.rectangle()
            positive_area = int(rectangle.width() > 0 and rectangle.height() > 0)
        except Exception:
            positive_area = 0
        return visible, enabled, positive_area

    @staticmethod
    def _child_candidates(current: Any, step: SelectorStep) -> list[Any]:
        candidates: list[Any] = []
        for getter in (current.children, current.descendants):
            try:
                values = list(getter())
            except Exception:
                continue
            candidates.extend(value for value in values if _matches_step(value, step))
        candidates = Win32SelectorDriver._unique_wrappers(candidates)
        if not candidates and step.title and step.class_name:
            for getter in (current.children, current.descendants):
                try:
                    values = list(getter())
                except Exception:
                    continue
                candidates.extend(
                    value
                    for value in values
                    if _matches_step(value, step, ignore_exact_title=True)
                )
            candidates = Win32SelectorDriver._unique_wrappers(candidates)
        return candidates

    def _ordered_candidates(
        self,
        candidates: Sequence[Any],
        preferred_index: int | None,
    ) -> list[Any]:
        ordered = sorted(candidates, key=self._wrapper_priority, reverse=True)
        if preferred_index is not None and 0 <= preferred_index < len(candidates):
            preferred = candidates[preferred_index]
            ordered = [preferred] + [item for item in ordered if item is not preferred]
        return ordered[:20]

    def _walk_selector(
        self,
        current: Any,
        steps: Sequence[SelectorStep],
        position: int,
    ) -> Any | None:
        if position >= len(steps):
            return current
        step = steps[position]
        candidates = self._child_candidates(current, step)
        for candidate in self._ordered_candidates(candidates, step.index):
            resolved = self._walk_selector(candidate, steps, position + 1)
            if resolved is not None:
                return resolved
        return None

    def _resolve_once_backend(self, spec: SelectorSpec, backend: str) -> Any | None:
        first = spec.steps[0]
        roots = self._desktop_candidates(first, backend=backend)
        for root in self._ordered_candidates(roots, first.index):
            resolved = self._walk_selector(root, spec.steps, 1)
            if resolved is not None:
                return resolved
        return None

    def _resolve_unique_last_step(self, spec: SelectorSpec, backend: str) -> Any | None:
        """中间容器版本变化时，从根窗体内寻找唯一的最终控件。"""

        roots = self._desktop_candidates(spec.steps[0], backend=backend)
        if not roots:
            return None
        last = spec.steps[-1]
        candidates: list[Any] = []
        for root in roots:
            try:
                descendants = list(root.descendants())
            except Exception:
                continue
            exact = [item for item in descendants if _matches_step(item, last)]
            if exact:
                candidates.extend(exact)
            elif last.class_name:
                candidates.extend(
                    item
                    for item in descendants
                    if _matches_step(item, last, ignore_exact_title=True)
                )
        # 只在唯一命中时使用，避免在多个同类按钮中误点。
        return candidates[0] if len(candidates) == 1 else None

    def _resolve_once(self, spec: SelectorSpec) -> Any | None:
        for backend in ("win32", "uia"):
            try:
                wrapper = self._resolve_once_backend(spec, backend)
            except Exception:
                continue
            if wrapper is not None:
                return wrapper
        for backend in ("win32", "uia"):
            try:
                wrapper = self._resolve_unique_last_step(spec, backend)
            except Exception:
                continue
            if wrapper is not None:
                LOGGER.debug("选择器 %s 使用唯一末级控件兜底", spec.name)
                return wrapper
        return None

    def resolve_fast(self, name: str) -> Any | None:
        """仅使用目标进程的 Win32 控件树完成一次快速定位。"""

        if name not in self.selectors:
            raise KeyError(f"未知控件选择器：{name}")
        spec = self.selectors[name]
        wrapper = self._resolve_once_backend(spec, "win32")
        if wrapper is not None:
            return wrapper
        return self._resolve_unique_last_step(spec, "win32")

    def resolve_strict_fast(self, name: str) -> Any | None:
        """仅按完整 Win32 选择器链定位，不使用“唯一末级控件”兜底。"""

        if name not in self.selectors:
            raise KeyError(f"未知控件选择器：{name}")
        return self._resolve_once_backend(self.selectors[name], "win32")

    def resolve(self, name: str, timeout: float = 20.0, required: bool = True) -> Any | None:
        if name not in self.selectors:
            raise KeyError(f"未知控件选择器：{name}")
        spec = self.selectors[name]
        deadline = time.monotonic() + max(timeout, 0)
        last_error: Exception | None = None
        while True:
            try:
                wrapper = self._resolve_once(spec)
                if wrapper is not None:
                    return wrapper
            except Exception as exc:
                last_error = exc
            if time.monotonic() >= deadline:
                if required:
                    suffix = f"；最后错误：{last_error}" if last_error else ""
                    raise AutomationError(
                        f"等待控件 {name!r} 超时（{timeout:g} 秒）{suffix}"
                    )
                return None
            time.sleep(0.4)

    def exists(self, name: str, timeout: float = 0.0) -> bool:
        return self.resolve(name, timeout=timeout, required=False) is not None

    @staticmethod
    def _native_window_handles_by_class(
        class_name: str,
        process_ids: Sequence[int],
        include_children: bool,
        require_enabled: bool = True,
    ) -> list[int]:
        """用 Win32 原生枚举按 PID/类名定位窗口，不扫描 UIA 控件树。"""

        if not process_ids:
            return []
        target_process_ids = set(process_ids)
        user32 = ctypes.WinDLL("user32", use_last_error=True)
        enum_callback_type = ctypes.WINFUNCTYPE(
            wintypes.BOOL,
            wintypes.HWND,
            wintypes.LPARAM,
        )
        user32.EnumWindows.argtypes = [enum_callback_type, wintypes.LPARAM]
        user32.EnumWindows.restype = wintypes.BOOL
        user32.EnumChildWindows.argtypes = [
            wintypes.HWND,
            enum_callback_type,
            wintypes.LPARAM,
        ]
        user32.EnumChildWindows.restype = wintypes.BOOL
        user32.GetWindowThreadProcessId.argtypes = [
            wintypes.HWND,
            ctypes.POINTER(wintypes.DWORD),
        ]
        user32.GetWindowThreadProcessId.restype = wintypes.DWORD
        user32.GetClassNameW.argtypes = [
            wintypes.HWND,
            wintypes.LPWSTR,
            ctypes.c_int,
        ]
        user32.GetClassNameW.restype = ctypes.c_int
        user32.IsWindowVisible.argtypes = [wintypes.HWND]
        user32.IsWindowVisible.restype = wintypes.BOOL
        user32.IsWindowEnabled.argtypes = [wintypes.HWND]
        user32.IsWindowEnabled.restype = wintypes.BOOL
        user32.GetWindowRect.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.RECT)]
        user32.GetWindowRect.restype = wintypes.BOOL

        top_windows: list[int] = []

        def collect_top(hwnd: int, _lparam: int) -> bool:
            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(process_id))
            if process_id.value in target_process_ids:
                top_windows.append(int(hwnd))
            return True

        top_callback = enum_callback_type(collect_top)
        user32.EnumWindows(top_callback, 0)

        candidates: list[int] = []
        seen: set[int] = set()

        def consider(hwnd: int) -> None:
            handle = int(hwnd)
            if handle in seen:
                return
            seen.add(handle)
            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(handle, ctypes.byref(process_id))
            if process_id.value not in target_process_ids:
                return
            buffer = ctypes.create_unicode_buffer(256)
            if user32.GetClassNameW(handle, buffer, len(buffer)) <= 0:
                return
            if buffer.value.casefold() != class_name.casefold():
                return
            rectangle = wintypes.RECT()
            if not user32.GetWindowRect(handle, ctypes.byref(rectangle)):
                return
            if rectangle.right <= rectangle.left or rectangle.bottom <= rectangle.top:
                return
            if not user32.IsWindowVisible(handle):
                return
            if require_enabled and not user32.IsWindowEnabled(handle):
                return
            candidates.append(handle)

        for top_window in top_windows:
            consider(top_window)
        if include_children and not candidates:
            for top_window in top_windows:
                child_callback = enum_callback_type(
                    lambda hwnd, _lparam: (consider(hwnd), True)[1]
                )
                user32.EnumChildWindows(top_window, child_callback, 0)
        return candidates

    def find_by_class(
        self,
        class_name: str,
        timeout: float = 0.0,
        include_children: bool = False,
        require_enabled: bool = True,
    ) -> Any | None:
        """按目标进程的原生窗口类名快速查找控件。"""

        deadline = time.monotonic() + max(timeout, 0)
        while True:
            process_ids = self._target_process_ids()
            if process_ids:
                try:
                    handles = self._native_window_handles_by_class(
                        class_name,
                        process_ids,
                        include_children,
                        require_enabled,
                    )
                    desktop = self.Desktop(backend="win32")
                    for handle in handles:
                        try:
                            return desktop.window(handle=handle).wrapper_object()
                        except Exception:
                            continue
                except Exception:
                    pass
            if time.monotonic() >= deadline:
                return None
            time.sleep(0.3)

    @staticmethod
    def _native_window_handles_by_text(
        texts: Sequence[str],
        process_ids: Sequence[int],
        contains: bool = False,
    ) -> list[int]:
        """按目标 PID 和可见控件文字快速查找原生 Win32 子窗口。"""

        expected = {
            re.sub(r"\s+", "", str(value)).casefold()
            for value in texts
            if str(value).strip()
        }
        if not process_ids or not expected:
            return []
        target_process_ids = set(process_ids)
        user32 = ctypes.WinDLL("user32", use_last_error=True)
        enum_callback_type = ctypes.WINFUNCTYPE(
            wintypes.BOOL,
            wintypes.HWND,
            wintypes.LPARAM,
        )
        user32.EnumWindows.argtypes = [enum_callback_type, wintypes.LPARAM]
        user32.EnumWindows.restype = wintypes.BOOL
        user32.EnumChildWindows.argtypes = [
            wintypes.HWND,
            enum_callback_type,
            wintypes.LPARAM,
        ]
        user32.EnumChildWindows.restype = wintypes.BOOL
        user32.GetWindowThreadProcessId.argtypes = [
            wintypes.HWND,
            ctypes.POINTER(wintypes.DWORD),
        ]
        user32.GetWindowThreadProcessId.restype = wintypes.DWORD
        user32.GetWindowTextLengthW.argtypes = [wintypes.HWND]
        user32.GetWindowTextLengthW.restype = ctypes.c_int
        user32.GetWindowTextW.argtypes = [
            wintypes.HWND,
            wintypes.LPWSTR,
            ctypes.c_int,
        ]
        user32.GetWindowTextW.restype = ctypes.c_int
        user32.IsWindowVisible.argtypes = [wintypes.HWND]
        user32.IsWindowVisible.restype = wintypes.BOOL
        user32.IsWindowEnabled.argtypes = [wintypes.HWND]
        user32.IsWindowEnabled.restype = wintypes.BOOL
        user32.GetWindowRect.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.RECT)]
        user32.GetWindowRect.restype = wintypes.BOOL

        top_windows: list[int] = []

        def collect_top(hwnd: int, _lparam: int) -> bool:
            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(process_id))
            if process_id.value in target_process_ids:
                top_windows.append(int(hwnd))
            return True

        top_callback = enum_callback_type(collect_top)
        user32.EnumWindows(top_callback, 0)
        matches: list[int] = []
        seen: set[int] = set()

        def consider(hwnd: int) -> None:
            handle = int(hwnd)
            if handle in seen:
                return
            seen.add(handle)
            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(handle, ctypes.byref(process_id))
            if process_id.value not in target_process_ids:
                return
            if not user32.IsWindowVisible(handle) or not user32.IsWindowEnabled(handle):
                return
            rectangle = wintypes.RECT()
            if not user32.GetWindowRect(handle, ctypes.byref(rectangle)):
                return
            if rectangle.right <= rectangle.left or rectangle.bottom <= rectangle.top:
                return
            length = user32.GetWindowTextLengthW(handle)
            if length <= 0:
                return
            buffer = ctypes.create_unicode_buffer(length + 1)
            if user32.GetWindowTextW(handle, buffer, len(buffer)) <= 0:
                return
            value = re.sub(r"\s+", "", buffer.value).casefold()
            if (contains and any(item in value for item in expected)) or (
                not contains and value in expected
            ):
                matches.append(handle)

        for top_window in top_windows:
            consider(top_window)
            child_callback = enum_callback_type(
                lambda hwnd, _lparam: (consider(hwnd), True)[1]
            )
            user32.EnumChildWindows(top_window, child_callback, 0)
        return matches

    @staticmethod
    def native_window_snapshot(
        process_ids: Sequence[int],
        max_items: int = 800,
    ) -> list[str]:
        """快速导出原生 HWND 清单，避免 UIA/descendants 在失败现场卡死。"""

        if not process_ids or max_items <= 0:
            return []
        target_process_ids = set(process_ids)
        user32 = ctypes.WinDLL("user32", use_last_error=True)
        enum_callback_type = ctypes.WINFUNCTYPE(
            wintypes.BOOL,
            wintypes.HWND,
            wintypes.LPARAM,
        )
        user32.EnumWindows.argtypes = [enum_callback_type, wintypes.LPARAM]
        user32.EnumWindows.restype = wintypes.BOOL
        user32.EnumChildWindows.argtypes = [
            wintypes.HWND,
            enum_callback_type,
            wintypes.LPARAM,
        ]
        user32.EnumChildWindows.restype = wintypes.BOOL
        user32.GetWindowThreadProcessId.argtypes = [
            wintypes.HWND,
            ctypes.POINTER(wintypes.DWORD),
        ]
        user32.GetWindowThreadProcessId.restype = wintypes.DWORD
        user32.GetClassNameW.argtypes = [
            wintypes.HWND,
            wintypes.LPWSTR,
            ctypes.c_int,
        ]
        user32.GetClassNameW.restype = ctypes.c_int
        user32.GetWindowTextLengthW.argtypes = [wintypes.HWND]
        user32.GetWindowTextLengthW.restype = ctypes.c_int
        user32.GetWindowTextW.argtypes = [
            wintypes.HWND,
            wintypes.LPWSTR,
            ctypes.c_int,
        ]
        user32.GetWindowTextW.restype = ctypes.c_int
        user32.GetWindowRect.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.RECT)]
        user32.GetWindowRect.restype = wintypes.BOOL
        user32.IsWindowVisible.argtypes = [wintypes.HWND]
        user32.IsWindowVisible.restype = wintypes.BOOL
        user32.IsWindowEnabled.argtypes = [wintypes.HWND]
        user32.IsWindowEnabled.restype = wintypes.BOOL

        top_windows: list[int] = []

        def collect_top(hwnd: int, _lparam: int) -> bool:
            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(process_id))
            if process_id.value in target_process_ids:
                top_windows.append(int(hwnd))
            return True

        user32.EnumWindows(enum_callback_type(collect_top), 0)
        handles: list[int] = []
        seen: set[int] = set()

        def append_handle(hwnd: int) -> bool:
            handle = int(hwnd)
            if handle in seen:
                return len(handles) < max_items
            seen.add(handle)
            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(handle, ctypes.byref(process_id))
            if process_id.value in target_process_ids:
                handles.append(handle)
            return len(handles) < max_items

        for top_window in top_windows:
            if not append_handle(top_window):
                break
            child_callback = enum_callback_type(
                lambda hwnd, _lparam: append_handle(hwnd)
            )
            user32.EnumChildWindows(top_window, child_callback, 0)
            if len(handles) >= max_items:
                break

        lines: list[str] = []
        for index, handle in enumerate(handles):
            process_id = wintypes.DWORD()
            user32.GetWindowThreadProcessId(handle, ctypes.byref(process_id))
            class_buffer = ctypes.create_unicode_buffer(256)
            user32.GetClassNameW(handle, class_buffer, len(class_buffer))
            class_name = class_buffer.value
            text = ""
            text_length = min(max(user32.GetWindowTextLengthW(handle), 0), 512)
            if text_length:
                text_buffer = ctypes.create_unicode_buffer(text_length + 1)
                user32.GetWindowTextW(handle, text_buffer, len(text_buffer))
                text = text_buffer.value.replace("\r", " ").replace("\n", " ")
            if "edit" in class_name.casefold():
                text = "<Edit text redacted>"
            elif len(text) > 160:
                text = text[:157] + "..."
            rectangle = wintypes.RECT()
            bounds: tuple[int, int, int, int] | str = "?"
            if user32.GetWindowRect(handle, ctypes.byref(rectangle)):
                bounds = (
                    rectangle.left,
                    rectangle.top,
                    rectangle.right,
                    rectangle.bottom,
                )
            lines.append(
                f"{index:03d} hwnd=0x{handle:X} pid={process_id.value} "
                f"visible={bool(user32.IsWindowVisible(handle))} "
                f"enabled={bool(user32.IsWindowEnabled(handle))} "
                f"class={class_name!r} text={text!r} rect={bounds}"
            )
        return lines

    def find_by_text(
        self,
        texts: str | Sequence[str],
        timeout: float = 0.0,
    ) -> Any | None:
        """按可见文字定位目标进程中的原生控件。"""

        values = (texts,) if isinstance(texts, str) else tuple(texts)
        deadline = time.monotonic() + max(timeout, 0)
        while True:
            try:
                handles = self._native_window_handles_by_text(
                    values,
                    self._target_process_ids(),
                )
                desktop = self.Desktop(backend="win32")
                for handle in handles:
                    try:
                        return desktop.window(handle=handle).wrapper_object()
                    except Exception:
                        continue
            except Exception:
                pass
            if time.monotonic() >= deadline:
                return None
            time.sleep(0.3)

    def find_by_text_contains(
        self,
        texts: str | Sequence[str],
        timeout: float = 0.0,
    ) -> Any | None:
        """按可见文字片段定位目标进程中的原生控件。"""

        values = (texts,) if isinstance(texts, str) else tuple(texts)
        deadline = time.monotonic() + max(timeout, 0)
        while True:
            try:
                handles = self._native_window_handles_by_text(
                    values,
                    self._target_process_ids(),
                    contains=True,
                )
                desktop = self.Desktop(backend="win32")
                for handle in handles:
                    try:
                        return desktop.window(handle=handle).wrapper_object()
                    except Exception:
                        continue
            except Exception:
                pass
            if time.monotonic() >= deadline:
                return None
            time.sleep(0.3)

    def click(
        self,
        name: str,
        timeout: float = 20.0,
        anchor: str = "center",
        offset: tuple[int, int] = (0, 0),
    ) -> None:
        wrapper = self.resolve(name, timeout=timeout, required=True)
        assert wrapper is not None
        if anchor == "middle_right":
            rectangle = wrapper.rectangle()
            coords = (
                max(1, rectangle.width() - 1 + offset[0]),
                max(1, rectangle.height() // 2 + offset[1]),
            )
            wrapper.click_input(coords=coords)
        else:
            wrapper.click_input()
        time.sleep(0.8)

    def input_text(self, name: str, value: str, timeout: float = 20.0) -> None:
        wrapper = self.resolve(name, timeout=timeout, required=True)
        assert wrapper is not None
        wrapper.click_input()
        try:
            wrapper.set_edit_text(value)
        except Exception:
            self.keyboard.send_keys("^a{BACKSPACE}")
            _paste_text(value)
        time.sleep(0.8)

    def read_text(self, name: str, timeout: float = 2.0) -> str:
        wrapper = self.resolve(name, timeout=timeout, required=False)
        return _wrapper_text(wrapper) if wrapper is not None else ""

    def select_company(self, company: str) -> bool:
        """在智能搜索弹窗中精确选择公司，避免误选第一项。"""

        self.input_text("输入公司", company)
        time.sleep(1.0)

        # Delphi 原生列表优先，能够直接读取 item_texts。
        for popup in self._desktop_candidates(
            SelectorStep("wnd", "Tfrm_IntelligentSearchPop", None, None)
        ):
            try:
                list_boxes = popup.descendants(class_name="TListBox.W")
            except Exception:
                list_boxes = []
            for list_box in list_boxes:
                try:
                    item_texts = [str(value).strip() for value in list_box.item_texts()]
                except Exception:
                    item_texts = []
                for index, item_text in enumerate(item_texts):
                    if item_text.casefold() == company.casefold():
                        try:
                            list_box.select(index)
                            self.keyboard.send_keys("{ENTER}")
                        except Exception:
                            list_box.click_input()
                            self.keyboard.send_keys("{HOME}" + "{DOWN}" * index + "{ENTER}")
                        time.sleep(0.8)
                        return True

        # 某些版本只通过 UIA 暴露 ListItem。
        try:
            desktop_uia = self.Desktop(backend="uia")
            for popup in desktop_uia.windows(class_name="Tfrm_IntelligentSearchPop"):
                for item in popup.descendants(control_type="ListItem"):
                    if _wrapper_text(item).strip().casefold() == company.casefold():
                        item.click_input()
                        time.sleep(0.8)
                        return True
        except Exception:
            pass
        return False


def _paste_text(text: str) -> None:
    """通过 Windows 剪贴板粘贴文本，密码中的 ``+{}^`` 不会被当成热键。"""

    _, _, pyautogui, _, _ = _load_ui_dependencies()
    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32
    global_moveable = 0x0002
    unicode_text = 13
    data = (text + "\0").encode("utf-16-le")

    kernel32.GlobalAlloc.argtypes = [wintypes.UINT, ctypes.c_size_t]
    kernel32.GlobalAlloc.restype = wintypes.HGLOBAL
    kernel32.GlobalLock.argtypes = [wintypes.HGLOBAL]
    kernel32.GlobalLock.restype = wintypes.LPVOID
    kernel32.GlobalUnlock.argtypes = [wintypes.HGLOBAL]
    kernel32.GlobalFree.argtypes = [wintypes.HGLOBAL]
    user32.SetClipboardData.argtypes = [wintypes.UINT, wintypes.HANDLE]
    user32.SetClipboardData.restype = wintypes.HANDLE
    handle = kernel32.GlobalAlloc(global_moveable, len(data))
    if not handle:
        raise AutomationError("无法分配 Windows 剪贴板内存")
    pointer = kernel32.GlobalLock(handle)
    ctypes.memmove(pointer, data, len(data))
    kernel32.GlobalUnlock(handle)

    if not user32.OpenClipboard(None):
        kernel32.GlobalFree(handle)
        raise AutomationError("无法打开 Windows 剪贴板")
    try:
        user32.EmptyClipboard()
        if not user32.SetClipboardData(unicode_text, handle):
            kernel32.GlobalFree(handle)
            raise AutomationError("无法写入 Windows 剪贴板")
        handle = None
    finally:
        user32.CloseClipboard()
    pyautogui.hotkey("ctrl", "v")


class TaxClientAutomation:
    def __init__(self, settings: Settings, repository: ResourceRepository) -> None:
        self.settings = settings
        self.repository = repository
        self.images = ImageMatcher(repository.images)
        self.controls = Win32SelectorDriver(repository.selectors)
        _, _, self.pyautogui, _, self.keyboard = _load_ui_dependencies()
        self.launch_process: subprocess.Popen[Any] | None = None
        self.submission_started = False
        # “生成零工资记录”会写入客户端数据。请求一旦发出，即使后续页面
        # 识别失败也不能自动重试生成，避免同一公司重复写入工资明细。
        self.salary_generation_started = False
        self.salary_generation_verified = False
        # 报送页在状态加载阶段可能暂时 disabled；保留进入时已经确认过的
        # wrapper 与矩形，状态识图不能因此重新被 enabled 门槛拦截。
        self.last_report_page: Any | None = None
        self.last_report_bounds: tuple[int, int, int, int] | None = None
        # “发送申报”必须由同一前台报送页、同一按钮连续两轮确认。保存当时
        # 的原生 HWND，最终点击前严格复核；句柄不可读时一律停止发送。
        self.last_send_page_handle: int | None = None
        self.last_send_button_handle: int | None = None
        self.last_send_requires_mouse_click = False
        self.last_send_visual_target: VisualSendTarget | None = None
        self.last_visual_send_note = "尚未执行视觉定位"
        self.last_diagnostic: Path | None = None

    def _export_nodes(self, owner: Any) -> list[Any]:
        """仅枚举已确认宿主的 Win32 子树，不跨进程查找同名按钮。"""
        queue = [(owner, 0)]
        seen: set[int] = set()
        result = []
        while queue and len(seen) < 700:
            node, depth = queue.pop(0)
            try:
                handle = int(node.handle)
            except Exception:
                continue
            if handle in seen:
                continue
            seen.add(handle)
            if depth:
                result.append(node)
            if depth < 12:
                try:
                    queue.extend((child, depth + 1) for child in node.children())
                except Exception:
                    continue
        if queue:
            raise AutomationError("申报记录导出：控件树超出安全枚举上限，拒绝用不完整候选定位")
        return result

    @staticmethod
    def _export_text(node: Any) -> str:
        try:
            return node.window_text().strip().replace("&", "")
        except Exception:
            return ""

    def _export_visual_point_owned(self, main: Any, x: int, y: int) -> bool:
        """图片命中点必须属于本次 MainFrame 子树，而非仅同进程的其他窗体。"""
        if not self._screen_point_belongs_to_target(x, y):
            return False
        try:
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            user32.WindowFromPoint.argtypes = [wintypes.POINT]
            user32.WindowFromPoint.restype = wintypes.HWND
            user32.IsChild.argtypes = [wintypes.HWND, wintypes.HWND]
            user32.IsChild.restype = wintypes.BOOL
            hit = int(user32.WindowFromPoint(wintypes.POINT(x, y)) or 0)
            return bool(hit and (hit == int(main.handle) or user32.IsChild(int(main.handle), hit)))
        except Exception:
            return False

    def _export_visual_capture(self, main: Any) -> tuple[Any, int, int, tuple[int, int, int, int]] | None:
        # 没有图像运行时的原生控件测试桩/旧入口，保持安全的“不匹配”。
        if not hasattr(self, "images"):
            self._export_capture_note = "图像识别运行时未初始化"
            return None
        try:
            bounds = self._wrapper_bounds(main)
            if bounds is None or not main.is_visible():
                self._export_capture_note = "主窗口不可见或矩形不可读"
                return None
            if not main.is_enabled():
                self._export_capture_note = "主窗口不可用，可能仍有提示窗口"
                return None
            if not self._is_page_exposed(main):
                self._export_capture_note = "主窗口被遮挡"
                return None
            frame, origin_x, origin_y = _capture_screen_bgr(self.images.np)
            self._export_capture_note = "截图成功"
            return frame, origin_x, origin_y, bounds
        except Exception as exc:
            self._export_capture_note = f"截图失败({type(exc).__name__})"
            return None

    def _export_visual_candidates(
        self, captured: tuple[Any, int, int, tuple[int, int, int, int]], name: str,
    ) -> list[tuple[tuple[int, int, int, int], float]]:
        """合并远程缩放图及原机字形的完整文字命中，不降低识别阈值。"""
        origins = {
            "查询统计": (82, 425), "单位申报记录查询": (111, 459),
            "记录查询面包屑": (326, 91), "记录税款所属期": (281, 136),
            "查询": (1503, 131), "导出": (1630, 131),
        }
        templates = []
        encoded = EXPORT_VISUAL_TEMPLATE_BLOBS.get(name)
        if encoded and name in origins:
            templates.append((encoded, origins[name], (1776, 956)))
        native = EXPORT_NATIVE_TEMPLATE_VARIANTS.get(name)
        if native:
            templates.append((native["blob"], native["origin"], native["reference_size"]))
        if name == "单位申报记录查询":
            templates.append((EXPORT_UNSELECTED_RECORDS_TEMPLATE, (48, 496), (1920, 1032)))
        if not hasattr(self, "_export_visual_notes"):
            self._export_visual_notes = {}
        self._export_visual_notes[name] = "未匹配完整文字"
        found = []
        best_score = 0.0
        for encoded, origin, size in templates:
            matches, score = self._export_match_template(captured, name, encoded, origin, size)
            best_score = max(best_score, score)
            for box, score in matches:
                same = next((i for i, (old, _) in enumerate(found)
                             if self._bbox_iou(old, box) >= .45), None)
                if same is None:
                    found.append((box, score))
                elif score > found[same][1]:
                    found[same] = (box, score)
        self._export_visual_notes[name] = (
            f"最佳分数={best_score:.3f}，阈值=0.940，候选={len(found)}"
        )
        return found

    def _export_match_template(
        self, captured: Any, name: str, encoded: str,
        source_origin: tuple[int, int], reference_size: tuple[int, int],
    ) -> tuple[list[tuple[tuple[int, int, int, int], float]], float]:
        """匹配一个已确认字形；返回所有候选及最高分用于诊断。"""
        regions = {
            "查询统计": (0.0, .12, .10, .85),
            "单位申报记录查询": (0.0, .12, .10, .85),
            "记录查询面包屑": (.10, .55, .07, .13),
            "记录税款所属期": (.10, .35, .11, .20),
            "查询": (.70, .99, .10, .22),
            "导出": (.70, .99, .10, .22),
        }
        if not encoded or name not in regions:
            return [], 0.0
        frame, origin_x, origin_y, (left, top, right, bottom) = captured
        cv2, np = self.images.cv2, self.images.np
        template = cv2.imdecode(np.frombuffer(base64.b64decode(encoded), dtype=np.uint8), cv2.IMREAD_COLOR)
        if template is None:
            raise AutomationError("申报记录导出：内嵌视觉模板损坏")
        x0, x1, y0, y1 = regions[name]
        roi_left = max(left + int((right-left)*x0), origin_x)
        roi_right = min(left + int((right-left)*x1), origin_x + frame.shape[1])
        roi_top = max(top + int((bottom-top)*y0), origin_y)
        roi_bottom = min(top + int((bottom-top)*y1), origin_y + frame.shape[0])
        if roi_right <= roi_left or roi_bottom <= roi_top:
            return [], 0.0
        crop = frame[roi_top-origin_y:roi_bottom-origin_y, roi_left-origin_x:roi_right-origin_x]
        if crop.size == 0:
            return [], 0.0
        found: list[tuple[tuple[int, int, int, int], float]] = []
        best_score = 0.0
        # @decision EXPORT-NATIVE-20261104 原机截图与远程缩放图不是同一字形；
        # 各自使用源窗口大小，不能把原机字体当成远程截图插值结果。
        scales = dict.fromkeys(round(value, 6) for value in (
            1.0, (right-left)/reference_size[0], (bottom-top)/reference_size[1],
            1.08, .90, .92, 1.10, .80, 1.25, 1.50,
        ) if .5 <= value <= 2.0)
        # 原图整体缩放时，裁片原点通常落在输出图的非整数像素位置。
        # 单独 resize 裁片会丢失该采样相位（例如导出图 x=1630 在 1.08
        # 倍时落在 1760.4），小字号因此会失配。保留同一完整文字的相位
        # 版本，不降低阈值，也不使用无文字的蓝色轮廓。
        for scale in scales:
            candidate = template if scale == 1 else cv2.resize(
                template, None, fx=scale, fy=scale,
                interpolation=cv2.INTER_AREA if scale < 1 else cv2.INTER_CUBIC,
            )
            height, width = candidate.shape[:2]
            if height > crop.shape[0] or width > crop.shape[1] or min(width, height) < 2:
                continue
            variants = [candidate]
            if scale != 1:
                source_x, source_y = source_origin
                phase_x, phase_y = (source_x*scale) % 1, (source_y*scale) % 1
                matrix = np.float32(((scale, 0, (scale-1)/2+phase_x),
                                     (0, scale, (scale-1)/2+phase_y)))
                variants.append(cv2.warpAffine(template, matrix, (width, height),
                                                flags=cv2.INTER_CUBIC, borderMode=cv2.BORDER_REPLICATE))
            for variant in variants:
                scores = cv2.matchTemplate(crop, variant, cv2.TM_CCOEFF_NORMED)
                _, maximum, _, _ = cv2.minMaxLoc(scores)
                if np.isfinite(maximum):
                    best_score = max(best_score, float(maximum))
                for _ in range(16):
                    _, score, _, position = cv2.minMaxLoc(scores)
                    if not np.isfinite(score) or score < .94:
                        break
                    x, y = position
                    box = (roi_left+x, roi_top+y, roi_left+x+width, roi_top+y+height)
                    same = next((index for index, (old, _) in enumerate(found)
                                 if self._bbox_iou(old, box) >= .45), None)
                    if same is None:
                        found.append((box, float(score)))
                    elif score > found[same][1]:
                        found[same] = (box, float(score))
                    scores[max(0, y-height//2):y+height//2+1,
                           max(0, x-width//2):x+width//2+1] = -1
        return found, best_score

    def _export_visual_locate(self, main: Any, name: str, captured: Any = None) -> ExportVisualTarget | None:
        captured = captured if captured is not None else self._export_visual_capture(main)
        if captured is None:
            return None
        candidates = self._export_visual_candidates(captured, name)
        if len(candidates) > 1:
            raise AutomationError(f"申报记录导出：视觉文字“{name}”候选不唯一")
        if not candidates:
            return None
        (left, top, right, bottom), score = candidates[0]
        points = (((left+right)//2, (top+bottom)//2), (left+1, top+1),
                  (right-2, top+1), (left+1, bottom-2), (right-2, bottom-2))
        if not all(self._export_visual_point_owned(main, x, y) for x, y in points):
            self._export_visual_notes[name] += "；文字命中但窗口归属检查失败"
            return None
        return ExportVisualTarget(name, int(main.handle), (left, top, right, bottom), score)

    def _export_usable(self, node: Any, owner: Any) -> bool:
        if isinstance(node, ExportVisualTarget):
            if node.main_handle != int(getattr(owner, "handle", 0)):
                return False
            current = self._export_visual_locate(owner, node.name)
            return bool(current and self._bbox_iou(node.bbox, current.bbox) >= .85)
        return self._wrapper_is_clickable(node) and self._is_control_exposed(
            node, owner=owner, allow_owner_surface=False
        )

    def _export_exact(
        self, owner: Any, text: str, *, content: bool = False, navigation: bool = False
    ) -> Any | None:
        bounds = self._wrapper_bounds(owner)
        if bounds is None:
            return None
        left, top, right, bottom = bounds
        candidates = []
        for node in self._export_nodes(owner):
            if self._export_text(node) != text or not self._export_usable(node, owner):
                continue
            box = self._wrapper_bounds(node)
            if box is None:
                continue
            x, y = (box[0] + box[2]) / 2, (box[1] + box[3]) / 2
            if navigation and not left <= x < left + (right - left) * .12:
                continue
            # 图示查询工具条位于主窗内容区顶部；排除左侧导航、底部旧页。
            if content and not (
                left + (right - left) * .10 < x < right
                and top + (bottom - top) * .08 < y < top + (bottom - top) * .30
            ):
                continue
            candidates.append(node)
        if len(candidates) > 1:
            raise AutomationError(f"申报记录导出：精确文字“{text}”候选不唯一")
        if candidates:
            return candidates[0]
        if (navigation and text in {"查询统计", "单位申报记录查询"}) or (
            content and text in {"查询", "导出"}
        ):
            return self._export_visual_locate(owner, text)
        return None

    def _export_records_page_ready(self, main: Any) -> bool:
        bounds = self._wrapper_bounds(main)
        if bounds is None or not self._is_page_exposed(main):
            return False
        left, top, right, bottom = bounds
        breadcrumb = period = False
        for node in self._export_nodes(main):
            box = self._wrapper_bounds(node)
            if box is None or not self._export_usable(node, main):
                continue
            x, y = (box[0] + box[2]) / 2, (box[1] + box[3]) / 2
            if not left + (right - left) * .10 < x < right:
                continue
            text = self._export_text(node)
            if top + (bottom - top) * .06 < y < top + (bottom - top) * .14:
                breadcrumb |= "单位申报记录查询" in text
            if top + (bottom - top) * .08 < y < top + (bottom - top) * .25:
                period |= text.strip(" *：:") == "税款所属期"
        if breadcrumb and period:
            return True
        captured = self._export_visual_capture(main)
        return bool(captured is not None
                    and self._export_visual_locate(main, "记录查询面包屑", captured)
                    and self._export_visual_locate(main, "记录税款所属期", captured))

    def _export_click(self, node: Any, owner: Any) -> None:
        if isinstance(node, ExportVisualTarget):
            if node.main_handle != int(getattr(owner, "handle", 0)):
                raise AutomationError("申报记录导出：视觉目标宿主已变化")
            current = self._export_visual_locate(owner, node.name)
            if current is None or self._bbox_iou(node.bbox, current.bbox) < .85:
                raise AutomationError("申报记录导出：点击前完整文字或位置发生变化，停止点击")
            self._export_visual_query_running = node.name == "查询"
            left, top, right, bottom = current.bbox
            self.pyautogui.click((left+right)//2, (top+bottom)//2)
            return
        if not self._export_usable(node, owner):
            raise AutomationError("申报记录导出：目标已被遮挡或不可用，停止点击")
        self._export_visual_query_running = self._export_text(node) == "查询"
        node.click_input()

    @staticmethod
    def _export_month_value(node: Any) -> str | None:
        if _wrapper_class_name(node).casefold() == "sysdatetimepick32":
            try:
                value = node.get_time()
                if 1900 <= value.wYear <= 9999 and 1 <= value.wMonth <= 12:
                    return f"{value.wYear:04d}-{value.wMonth:02d}"
            except Exception:
                return None
        text = TaxClientAutomation._export_text(node)
        match = re.fullmatch(r"(\d{4})\s*[年./-]\s*(\d{1,2})\s*月?", text)
        if match and 1 <= int(match[2]) <= 12:
            return f"{match[1]}-{int(match[2]):02d}"
        return None

    def _export_month_controls(self, main: Any) -> list[Any]:
        bounds = self._wrapper_bounds(main)
        if bounds is None:
            raise AutomationError("申报记录导出：无法确认主窗体范围")
        left, top, right, bottom = bounds
        candidates = []
        for node in self._export_nodes(main):
            kind = _wrapper_class_name(node).casefold()
            if "edit" not in kind and kind != "sysdatetimepick32":
                continue
            box = self._wrapper_bounds(node)
            if box is None or not self._export_usable(node, main):
                continue
            x, y = (box[0] + box[2]) / 2, (box[1] + box[3]) / 2
            if not (
                left + (right - left) * .10 < x < left + (right - left) * .55
                and top + (bottom - top) * .08 < y < top + (bottom - top) * .25
            ):
                continue
            if self._export_month_value(node) is not None:
                candidates.append(node)
        # 不选第一个/最后一个来掩盖未知版本的控件歧义。
        if len(candidates) != 2:
            raise AutomationError("申报记录导出：未识别到唯一的两个税款所属期年月控件")
        return sorted(candidates, key=lambda node: node.rectangle().left)

    def _export_set_month(self, node: Any, owner: Any, month: str) -> None:
        if not self._export_usable(node, owner):
            raise AutomationError("申报记录导出：年月控件不在前台")
        year, number = (int(part) for part in month.split("-"))
        if _wrapper_class_name(node).casefold() == "sysdatetimepick32":
            node.set_time(year=year, month=number, day=1)
        else:
            node.set_edit_text(f"{year}.{number}")
            node.type_keys("{TAB}")
        if self._export_month_value(node) != month:
            raise AutomationError(f"申报记录导出：年月回读不一致，期望 {month}")

    def _export_save_candidates(self, main: Any) -> list[Any]:
        """保存只搜索此次查询主窗的 PID，不接受另一客户端的保存窗口。"""
        try:
            process_id = int(main.process_id())
            if process_id <= 0:
                raise ValueError("invalid process")
            # Delphi 保存框可能挂在隐藏的应用窗口下，不能仅比较 root owner。
            # 同进程必须只有本次查询的一个可见主窗；模态框会禁用主窗，因此不要求 enabled。
            main_handles = self.controls._native_window_handles_by_class(
                "Tfrm_MainFrame", (process_id,), True, False
            )
            if set(main_handles) != {int(main.handle)}:
                raise ValueError("ambiguous or changed main window")
            handles = self.controls._native_window_handles_by_class(
                "#32770", (process_id,), False, True
            )
            desktop = self.controls.Desktop(backend="win32")
            return [desktop.window(handle=handle).wrapper_object() for handle in handles]
        except Exception as exc:
            raise AutomationError("申报记录导出：无法核验本次客户端的保存窗口归属") from exc

    def _export_save_dialog(self) -> Any | None:
        main = getattr(self, "_export_save_owner", None)
        if main is None:
            return None
        candidates = [dialog for dialog in self._export_save_candidates(main)
                      if self._export_text(dialog) in {
                          "单位申报记录保存", "另存为", "保存", "Save As", "Save"
                      } and (getattr(self, "_export_save_precheck", False)
                             or self._is_page_exposed(dialog))]
        if len(candidates) > 1:
            raise AutomationError("申报记录导出：同一客户端存在多个保存窗口，已停止保存")
        return candidates[0] if candidates else None

    @staticmethod
    def _export_cursor_point() -> tuple[int, int] | None:
        try:
            point = wintypes.POINT()
            if ctypes.WinDLL("user32", use_last_error=True).GetCursorPos(ctypes.byref(point)):
                return int(point.x), int(point.y)
        except Exception:
            pass
        return None

    def _export_visual_result_snapshot(self, main: Any) -> tuple[Any, Any] | None:
        captured = self._export_visual_capture(main)
        if captured is None:
            return None
        if not (self._export_visual_locate(main, "记录查询面包屑", captured)
                and self._export_visual_locate(main, "记录税款所属期", captured)):
            return None
        frame, origin_x, origin_y, (left, top, right, bottom) = captured
        # 只取表头以下的前几行结果，排除日期/工具条、右侧滚动条与底部汇总。
        x0, x1 = left + int((right-left)*.115), left + int((right-left)*.61)
        y0, y1 = top + int((bottom-top)*.218), top + int((bottom-top)*.81)
        if not (origin_x <= x0 < x1 <= origin_x+frame.shape[1]
                and origin_y <= y0 < y1 <= origin_y+frame.shape[0]):
            return None
        if not all(self._export_visual_point_owned(main, x, y) for x, y in (
            (x0, y0), (x1-1, y0), (x0, y1-1), (x1-1, y1-1), ((x0+x1)//2, (y0+y1)//2)
        )):
            return None
        pixels = frame[y0-origin_y:y1-origin_y, x0-origin_x:x1-origin_x].astype("int16")
        np = self.images.np
        blue = ((pixels[:, :, 0] > pixels[:, :, 2]+12)
                & (pixels[:, :, 1] > pixels[:, :, 2]+3)
                & (pixels[:, :, 0] > 180) & (pixels[:, :, 1] > 170))
        ignore = np.zeros(pixels.shape[:2], dtype=bool)
        for row in np.flatnonzero(blue.mean(axis=1) > .15):
            ignore[max(0, row-2):row+3, :] = True
        cursor = self._export_cursor_point()
        if cursor is not None:
            cx, cy = cursor[0]-x0, cursor[1]-y0
            ignore[max(0, cy-24):max(0, cy+48), max(0, cx-24):max(0, cx+48)] = True
        ink = (pixels.max(axis=2) < 160) & ((pixels.max(axis=2)-pixels.min(axis=2)) < 80)
        return ink, ignore

    def _export_visual_result_signature(self, main: Any) -> tuple[str, ...]:
        snapshot = self._export_visual_result_snapshot(main)
        if snapshot is None:
            return ()
        ink, ignore = snapshot
        base_token = ("visual_table_baseline", str(main.handle))
        if not getattr(self, "_export_visual_query_running", False):
            self._export_visual_table_baseline = (int(main.handle), ink.copy(), ignore.copy())
            return base_token
        baseline = getattr(self, "_export_visual_table_baseline", None)
        if baseline is None or baseline[0] != int(main.handle) or baseline[1].shape != ink.shape:
            return ()
        # 使用查询前/当前遮罩的并集。仅选择行变化或鼠标移动不能制造 fresh。
        np = self.images.np
        safe = ~(ignore | baseline[2])
        changed = (ink != baseline[1]) & safe
        changed_rows = sum(int(changed[row:row+12].sum()) > 30 for row in range(0, ink.shape[0], 12))
        if int(changed.sum()) < max(160, int(ink.size*.0008)) or changed_rows < 2:
            return base_token
        # 4px 结构化文字占据掩码对细微抗锯齿/压缩更稳，不比较整幅彩色画面。
        masked = ink & safe
        height, width = masked.shape
        blocks = masked[:height//4*4, :width//4*4].reshape(height//4, 4, width//4, 4).sum(axis=(1, 3)) > 1
        return ("visual_table_rows", hashlib.sha256(np.packbits(blocks).tobytes()).hexdigest())

    def _export_query_signature(self, main: Any) -> tuple[str, ...]:
        """只读取前台结果网格文本；输入框日期不算结果刷新证据。"""
        # 自绘网格有时只暴露固定的 pnl_body 标题，也要在点击查询前保存
        # 视觉基线；否则恒定原生标题会遮蔽真实结果刷新。
        visual = None
        if not getattr(self, "_export_visual_query_running", False):
            visual = self._export_visual_result_signature(main)
        values: list[str] = []
        for grid in self._export_nodes(main):
            kind = _wrapper_class_name(grid).casefold()
            if ("grid" not in kind and kind != "syslistview32") or not self._export_usable(grid, main):
                continue
            for node in [grid, *self._export_nodes(grid)]:
                if self._export_usable(node, main):
                    text = self._export_text(node)
                    if text:
                        values.append(text)
        if values:
            return tuple(values)
        return visual if visual is not None else self._export_visual_result_signature(main)

    def _export_wait_query(self, main: Any, before: tuple[str, ...]) -> Any:
        deadline = time.monotonic() + self.settings.page_timeout
        next_log = time.monotonic() + 5
        busy_seen = False
        previous = None
        stable_since = None
        while time.monotonic() < deadline:
            query = self._export_exact(main, "查询", content=True)
            export = self._export_exact(main, "导出", content=True)
            progress = self._progress_visible()
            busy = progress or not self._is_page_exposed(main) or query is None
            # 遮挡/找不到按钮只是暂停原因，不能证明本次查询已执行。
            busy_seen |= progress
            signature = self._export_query_signature(main) if not busy else ()
            fresh = busy_seen or bool(signature and signature != before)
            visual_signature = ()
            if not busy and not fresh and signature == before:
                visual_signature = self._export_visual_result_signature(main)
                fresh = bool(visual_signature and visual_signature[0] == "visual_table_rows")
            key = (signature, visual_signature, getattr(export, "handle", None))
            if not busy and fresh and export is not None:
                if stable_since is None or key != previous:
                    stable_since = time.monotonic()
                elif time.monotonic() - stable_since >= 1.5:
                    return export
            else:
                stable_since = None
            previous = key
            if time.monotonic() >= next_log:
                LOGGER.info("等待单位申报记录查询完成证据（查询进度或结果表刷新）……")
                next_log = time.monotonic() + 5
            time.sleep(.4)
        raise AutomationError("申报记录查询完成状态未能核验；未导出，避免保存旧查询结果")

    def _export_save_controls(self, dialog: Any) -> tuple[Any, Any]:
        filename_edits, save_buttons = [], []
        for node in self._export_nodes(dialog):
            if not self._export_usable(node, dialog):
                continue
            try:
                control_id = int(node.control_id())
                kind = _wrapper_class_name(node).casefold()
                parent = node.parent()
                parent_id = int(parent.control_id())
                parent_kind = _wrapper_class_name(parent).casefold()
                filename_combo = parent_id == 1148 and parent_kind in {"comboboxex32", "combobox"}
                if parent_kind == "combobox" and not filename_combo:
                    grandparent = parent.parent()
                    filename_combo = (
                        int(grandparent.control_id()) == 1148
                        and _wrapper_class_name(grandparent).casefold() == "comboboxex32"
                    )
            except Exception:
                continue
            if kind == "edit" and (
                control_id == 1152 or filename_combo
            ):
                filename_edits.append(node)
            if kind == "button" and control_id == 1 and self._export_text(node) in {
                "保存", "保存(S)", "Save", "Save(S)"
            }:
                save_buttons.append(node)
        if len(filename_edits) != 1 or len(save_buttons) != 1:
            raise AutomationError("申报记录导出：标准保存对话框的文件名/保存按钮未唯一识别")
        return filename_edits[0], save_buttons[0]

    def _export_save_suffix(self, dialog: Any, filename: Any) -> str:
        """从当前选中的保存类型取扩展名；不把公司名称中的点误当作文件类型。"""
        allowed = {".xls", ".xlsx", ".csv"}
        named_suffix = Path(filename.window_text().strip()).suffix.lower()
        selected_types = []
        for node in self._export_nodes(dialog):
            if _wrapper_class_name(node).casefold() != "combobox" or not self._export_usable(node, dialog):
                continue
            try:
                if int(node.control_id()) != 1136:  # 标准保存窗口 cmb1：保存类型。
                    continue
            except Exception:
                continue
            text = self._export_text(node)
            if not text and hasattr(node, "selected_text"):
                text = str(node.selected_text())
            extensions = set(re.findall(r"\*\.(xls[x]?|csv)\b", text, flags=re.IGNORECASE))
            if len(extensions) != 1:
                raise AutomationError("申报记录导出：当前保存类型无法唯一确定，未点击保存")
            selected_types.append("." + extensions.pop().lower())
        if len(selected_types) > 1:
            raise AutomationError("申报记录导出：保存类型控件不唯一，未点击保存")
        if selected_types:
            suffix = selected_types[0]
            if named_suffix in allowed and named_suffix != suffix:
                raise AutomationError("申报记录导出：默认扩展名与保存类型冲突，未点击保存")
            return suffix
        if named_suffix in allowed:
            return named_suffix
        raise AutomationError("申报记录导出：未读到 XLS/XLSX/CSV 保存类型或扩展名，未点击保存")

    def _export_wait_file(self, folder: Path, stem: str, suffix: str) -> Path:
        deadline = time.monotonic() + self.settings.page_timeout
        previous = None
        stable_since = None
        while time.monotonic() < deadline:
            files = [path for path in folder.iterdir() if path.is_file() and (
                (path.name == stem + suffix) if suffix else (path.stem == stem or path.name == stem)
            )]
            if len(files) > 1:
                raise AutomationError("申报记录导出：出现多个同名前缀文件，无法确定导出结果")
            if files:
                info = files[0].stat()
                current = (files[0], info.st_size, info.st_mtime_ns)
                if info.st_size > 0 and current == previous and self._export_save_dialog() is None:
                    if stable_since is not None and time.monotonic() - stable_since >= 1.0:
                        return files[0]
                else:
                    stable_since = time.monotonic()
                previous = current
            else:
                previous = None
                stable_since = None
            time.sleep(.4)
        raise AutomationError("申报记录导出：等待新导出文件非空且稳定超时")

    def _export_park_cursor(self, main: Any) -> None:
        """移出侧栏，避免鼠标悬停改变菜单图像；只移动，不点击。"""
        bounds = self._wrapper_bounds(main)
        if bounds is None:
            raise AutomationError("申报记录导出：无法确认主窗口位置，不能安全移开鼠标")
        left, top, right, bottom = bounds
        x = left + int((right - left) * .55)
        y = top + int((bottom - top) * .85)
        if not self._export_visual_point_owned(main, x, y):
            raise AutomationError("申报记录导出：鼠标移出位置不属于当前客户端，停止导航")
        self.pyautogui.moveTo(x, y, duration=0.1)
        LOGGER.info("已将鼠标移出左侧菜单，等待菜单外观稳定")

    def _export_wait_navigation(self) -> tuple[Any, Any]:
        """等待同一前台主窗及导航文字，父菜单仅展开一次，不盲点未知弹窗。"""
        started = time.monotonic()
        deadline = started + min(30.0, self.settings.page_timeout)
        next_log = started + 5
        owner_handle = None
        expanded = False
        note = "尚未找到主窗口"
        while time.monotonic() < deadline:
            main = self._client_main_window(timeout=0)
            if main is not None:
                handle = int(main.handle)
                if owner_handle is not None and handle != owner_handle:
                    raise AutomationError("申报记录导出：等待期间主窗口发生变化，停止导航")
                owner_handle = handle
                if not main.is_visible() or not self._is_page_exposed(main):
                    note = "主窗口不可见或被遮挡"
                elif not main.is_enabled():
                    # 已申报提示的确定刚被点击时，Delphi 可能仍禁用主窗。
                    # 仅等原流程关闭提示；不要在这里确认未知提示或重跑申报。
                    note = "主窗口仍不可用，等待提示关闭及页面恢复"
                else:
                    entry = self._export_exact(main, "单位申报记录查询", navigation=True)
                    if entry is not None:
                        LOGGER.info("已识别左侧“单位申报记录查询”入口")
                        return main, entry
                    if not expanded:
                        menu = self._export_exact(main, "查询统计", navigation=True)
                        if menu is not None:
                            self._export_click(menu, main)
                            expanded = True
                            LOGGER.info("已点击左侧“查询统计”，等待子菜单展开")
                            self._export_park_cursor(main)
                        note = "已点击查询统计，子菜单未识别" if expanded else "查询统计菜单未识别"
                    else:
                        note = "已点击查询统计，单位申报记录查询子菜单未识别"
                    visual = getattr(self, "_export_visual_notes", {})
                    name = "单位申报记录查询" if expanded else "查询统计"
                    note += "；" + visual.get(name, getattr(self, "_export_capture_note", "原生控件未匹配"))
            now = time.monotonic()
            self._export_navigation_note = note
            if now >= next_log:
                LOGGER.info("正在等待申报记录导出导航，已等待 %d 秒；%s", int(now-started), note)
                next_log = now + 5
            time.sleep(.4)
        raise AutomationError(f"申报记录导出：导航等待超时；{note}；申报成功状态保留，不重新申报")

    def export_declaration_records(self, company: str) -> Path:
        """已确认申报成功后导出单位记录；任何识别歧义只中止导出，不重报。"""
        start_month, end_month = declaration_export_period(self.settings)
        LOGGER.info("开始导出单位申报记录（原机字形兼容 20261104），税款所属期 %s 至 %s", start_month, end_month)
        main, entry = self._export_wait_navigation()
        self._export_click(entry, main)
        deadline = time.monotonic() + self.settings.page_timeout
        query = None
        while time.monotonic() < deadline:
            query = self._export_exact(main, "查询", content=True)
            if (self._export_records_page_ready(main) and query is not None
                    and self._export_exact(main, "导出", content=True) is not None):
                break
            time.sleep(.4)
        else:
            raise AutomationError("申报记录导出：查询页面工具条未就绪")
        month_controls = self._export_month_controls(main)
        for node, month in zip(month_controls, (start_month, end_month)):
            self._export_set_month(node, main, month)
        before = self._export_query_signature(main)
        self._export_click(query, main)
        export_button = self._export_wait_query(main, before)
        if not self._export_records_page_ready(main) or [
            self._export_month_value(node) for node in self._export_month_controls(main)
        ] != [start_month, end_month]:
            raise AutomationError("申报记录导出：查询后页面或税款所属期发生变化，已停止导出")
        self._export_save_owner = main
        self._export_save_precheck = True
        try:
            if self._export_save_dialog() is not None:
                raise AutomationError("申报记录导出：点击导出前已有保存窗口，请先关闭后重试")
        finally:
            self._export_save_precheck = False
        self._export_click(export_button, main)
        deadline = time.monotonic() + self.settings.page_timeout
        dialog = None
        while dialog is None and time.monotonic() < deadline:
            dialog = self._export_save_dialog()
            time.sleep(.3)
        if dialog is None:
            raise AutomationError("申报记录导出：未出现支持的标准保存对话框")
        filename, save_button = self._export_save_controls(dialog)
        suffix = self._export_save_suffix(dialog, filename)
        stem = export_file_prefix(company, start_month, end_month) + f"{datetime.now():%Y%m%d_%H%M%S_%f}"
        folder = declaration_export_directory(self.settings)
        folder.mkdir(parents=True, exist_ok=True)
        target = folder / (stem + suffix)
        LOGGER.info("单位申报记录保存：格式 %s，目录 %s", suffix, folder)
        if target.exists() or (not suffix and any(
            path.stem == stem for path in folder.iterdir()
        )):
            raise AutomationError("申报记录导出：输出文件已存在，拒绝覆盖")
        filename.set_edit_text(str(target))
        if filename.window_text().strip() != str(target):
            raise AutomationError("申报记录导出：保存路径回读不一致")
        current_dialog = self._export_save_dialog()
        if current_dialog is None or int(current_dialog.handle) != int(dialog.handle):
            raise AutomationError("申报记录导出：保存窗口已变化，已停止保存")
        self._export_click(save_button, dialog)
        result = self._export_wait_file(folder, stem, suffix)
        record_completed_export(self.settings, company, result)
        LOGGER.info("单位申报记录已导出并确认文件稳定：%s", result)
        return result

    def capture_diagnostics(self, stage: str) -> Path | None:
        """保存当前屏幕与窗口控件清单，失败时无需再次猜测页面状态。"""

        safe_stage = re.sub(r"[^0-9A-Za-z_\-]+", "_", stage).strip("_") or "error"
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        folder = (
            self.settings.result_file.expanduser().resolve().parent
            / "电子税务局申报_debug"
            / f"{stamp}_{safe_stage}"
        )
        try:
            folder.mkdir(parents=True, exist_ok=True)
            screenshot_path = folder / "screen.png"
            frame, _, _ = _capture_screen_bgr(self.images.np)
            _write_bgr_png(screenshot_path, frame, self.images.cv2)
            # 截图一旦成功就记录诊断目录。即使后续窗口快照失败或被中断，
            # 外层也不会再次进入诊断流程并掩盖原始业务异常。
            self.last_diagnostic = folder
            LOGGER.warning("已保存失败截图：%s", screenshot_path)

            tree_path = folder / "window_tree.txt"
            # PID 查询前先落盘最小元数据；tasklist 即使异常也不会只留下截图。
            lines: list[str] = [
                f"stage={stage}",
                f"captured_at={datetime.now().isoformat(timespec='seconds')}",
                "target_process_ids=<pending>",
                "launcher_return_code=<pending>",
                "=== native_win32_snapshot ===",
            ]
            # 仅记录固定UI标签及分数/拒绝原因，不把工资表或账号值写入诊断摘要。
            export_notes = getattr(self, "_export_visual_notes", {})
            if getattr(self, "_export_navigation_note", None) or export_notes:
                lines[4:4] = [
                    f"export_navigation={getattr(self, '_export_navigation_note', '')}",
                    f"export_capture={getattr(self, '_export_capture_note', '')}",
                    "export_visual=" + json.dumps(export_notes, ensure_ascii=False),
                ]
            tree_path.write_text("\n".join(lines), encoding="utf-8")

            process_ids = self.controls._target_process_ids()
            launcher_status = (
                self.launch_process.poll() if self.launch_process is not None else None
            )
            lines[2] = f"target_process_ids={process_ids}"
            lines[3] = f"launcher_return_code={launcher_status}"
            tree_path.write_text("\n".join(lines), encoding="utf-8")
            try:
                lines.extend(
                    self.controls.native_window_snapshot(process_ids, max_items=800)
                )
            except Exception as exc:
                lines.append(f"原生窗口枚举失败：{type(exc).__name__}: {exc}")
            tree_path.write_text("\n".join(lines), encoding="utf-8")
            LOGGER.warning("已保存失败诊断：%s", folder)
            return folder
        except Exception as exc:
            LOGGER.warning("保存失败诊断时出错：%s", exc)
            return None

    def start(self) -> None:
        if not self.settings.app_path.is_file():
            raise FileNotFoundError(f"电子税务局启动程序不存在：{self.settings.app_path}")
        # 与原影刀流程保持一致：每家公司从干净客户端状态开始，避免复用
        # 上一次登录的公司或停留在主界面导致登录页永远不出现。
        self._terminate_client_processes()
        time.sleep(0.8)
        self.pyautogui.hotkey("win", "d")
        time.sleep(0.5)
        LOGGER.info("启动自然人电子税务局：%s", self.settings.app_path)
        self.launch_process = subprocess.Popen(
            [str(self.settings.app_path)],
            cwd=str(self.settings.app_path.parent),
        )
        if self.settings.startup_delay > 0:
            LOGGER.info(
                "等待客户端初始化 %.1f 秒，再开始识别登录页……",
                self.settings.startup_delay,
            )
            warmup_deadline = time.monotonic() + self.settings.startup_delay
            while time.monotonic() < warmup_deadline:
                time.sleep(min(0.5, max(warmup_deadline - time.monotonic(), 0)))
        deadline = time.monotonic() + self.settings.startup_timeout
        started_at = time.monotonic()
        next_control_check = started_at + 2
        next_progress_log = started_at + 5
        while time.monotonic() < deadline:
            # 图片检测耗时稳定，必须放在可能较慢的 Win32/UIA 枚举之前。
            if self.images.exists("申报密码登录", timeout=0):
                LOGGER.info("登录页已就绪（图像兜底）")
                return
            # 启动轮询保持图片快路径；只有模板初筛命中时才枚举目标进程
            # 主窗体并做区域/PID复核，避免每 0.5 秒扫描 Win32 控件树。
            if (
                self.images.exists("综合申报", timeout=0)
                and self._legacy_comprehensive_match(timeout=0) is not None
            ):
                diagnostic = self.capture_diagnostics("unexpected_main_page")
                suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
                raise AutomationError(
                    "客户端启动后直接进入了旧登录会话的主界面" + suffix
                )
            now = time.monotonic()
            if now >= next_control_check:
                if self.controls.resolve_fast("实名登录") is not None:
                    LOGGER.info("登录页已就绪（目标进程 Win32 控件）")
                    return
                next_control_check = now + 4
            if now >= next_progress_log:
                LOGGER.info(
                    "正在等待登录页，已等待 %d 秒……",
                    int(now - started_at),
                )
                next_progress_log = now + 5
            time.sleep(0.5)
        diagnostic = self.capture_diagnostics("startup_timeout")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        raise AutomationError(
            f"等待登录页超时（{self.settings.startup_timeout:g} 秒）{suffix}"
        )

    @staticmethod
    def _terminate_client_processes() -> None:
        try:
            subprocess.run(
                ["taskkill", "/F", "/T", "/IM", PROCESS_IMAGE],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
                timeout=10,
            )
        except subprocess.TimeoutExpired:
            LOGGER.warning("关闭自然人电子税务局进程超时，继续执行后续清理")
        except OSError as exc:
            LOGGER.warning("关闭自然人电子税务局进程失败：%s", exc)

    def stop(self) -> None:
        self._terminate_client_processes()
        if self.launch_process and self.launch_process.poll() is None:
            try:
                self.launch_process.terminate()
                self.launch_process.wait(timeout=5)
            except Exception:
                pass
        self.launch_process = None

    def login(self, credential: Credential) -> None:
        LOGGER.info("选择公司：%s", credential.company)
        # 登录页若已显示“申报密码登录”，直接点击图像，避免无意义的 UIA 全树扫描。
        if not self.images.exists("申报密码登录", timeout=0):
            wrapper = self.controls.resolve_fast("实名登录")
            if wrapper is None:
                wrapper = self.controls.resolve("实名登录", timeout=8, required=True)
            assert wrapper is not None
            wrapper.click_input()
            time.sleep(0.8)
        self.images.click("申报密码登录", timeout=20, clicks=2)
        self.controls.click("选择单位")
        if not self.controls.select_company(credential.company):
            raise CompanyNotFoundError(f"单位列表未找到：{credential.company}")

        try:
            self.images.click("请输入密码", timeout=8, clicks=2)
        except AutomationError:
            # 部分客户端首次选择后会刷新列表，按原影刀流程重试一次。
            self.controls.click("选择单位", timeout=5)
            if not self.controls.select_company(credential.company):
                raise CompanyNotFoundError(f"二次选择仍未找到：{credential.company}")
            self.images.click("请输入密码", timeout=8, clicks=2)

        _paste_text(credential.password)
        for _ in range(3):
            self.pyautogui.press("enter")
            time.sleep(0.25)
        self.controls.click("登录电子税务局", timeout=20)
        LOGGER.info("登录操作已提交，等待首页并处理登录后提示……")
        self._wait_for_home_page()

    def _dismiss_registration_reminder(self, timeout: float = 0.0) -> bool:
        """关闭“未注册个税 APP 提醒”，避免它遮挡首页操作。"""

        class_name = "TfrmAPPRegisteTips"
        dialog = self.controls.find_by_class(class_name, timeout=timeout)
        if dialog is None:
            return False
        LOGGER.info("检测到“未注册个税 APP 提醒”，正在关闭……")

        # 优先按 Esc；部分客户端版本把该窗体实现为标准模式对话框。
        try:
            dialog.set_focus()
            self.pyautogui.press("esc")
            time.sleep(0.8)
        except Exception:
            pass
        if self.controls.find_by_class(class_name, timeout=0) is None:
            LOGGER.info("“未注册个税 APP 提醒”已关闭")
            return True

        # Esc 无效时直接点击窗体右上角的可见 X，不依赖易变化的内部面板层级。
        try:
            dialog = self.controls.find_by_class(class_name, timeout=0)
            if dialog is not None:
                rectangle = dialog.rectangle()
                dialog.click_input(
                    coords=(
                        max(1, rectangle.width() - 20),
                        min(18, max(1, rectangle.height() - 1)),
                    )
                )
                time.sleep(0.8)
        except Exception:
            pass
        if self.controls.find_by_class(class_name, timeout=0) is None:
            LOGGER.info("“未注册个税 APP 提醒”已关闭")
            return True

        # 最后发送标准 WM_CLOSE；目标严格限定为提醒窗体类，不会关闭主程序。
        try:
            dialog = self.controls.find_by_class(class_name, timeout=0)
            if dialog is not None:
                dialog.close()
                time.sleep(0.8)
        except Exception:
            pass
        if self.controls.find_by_class(class_name, timeout=0) is None:
            LOGGER.info("“未注册个税 APP 提醒”已关闭")
            return True

        diagnostic = self.capture_diagnostics("registration_reminder_not_closed")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        raise AutomationError("无法关闭“未注册个税 APP 提醒”" + suffix)

    @staticmethod
    def _wrapper_bounds(wrapper: Any) -> tuple[int, int, int, int] | None:
        """读取 Win32 控件边界；无效或不可读的矩形一律不参与坐标点击。"""

        try:
            rectangle = wrapper.rectangle()
            bounds = (
                int(rectangle.left),
                int(rectangle.top),
                int(rectangle.right),
                int(rectangle.bottom),
            )
        except Exception:
            return None
        left, top, right, bottom = bounds
        if right <= left or bottom <= top:
            return None
        return bounds

    @staticmethod
    def _unique_native_wrappers(values: Iterable[Any]) -> list[Any]:
        """按原生 HWND 去重；无 HWND 的测试桩/失效对象退回对象身份。"""

        return Win32SelectorDriver._unique_wrappers(values)

    def _screen_point_belongs_to_target(self, x: int, y: int) -> bool:
        """确认屏幕点当前命中的窗口属于本次税务客户端进程。"""

        try:
            target_process_ids = set(self.controls._target_process_ids())
        except Exception:
            return False
        if not target_process_ids:
            return False
        try:
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            user32.WindowFromPoint.argtypes = [wintypes.POINT]
            user32.WindowFromPoint.restype = wintypes.HWND
            user32.GetWindowThreadProcessId.argtypes = [
                wintypes.HWND,
                ctypes.POINTER(wintypes.DWORD),
            ]
            user32.GetWindowThreadProcessId.restype = wintypes.DWORD
            hit_handle = user32.WindowFromPoint(wintypes.POINT(int(x), int(y)))
            if not hit_handle:
                return False
            process_id = wintypes.DWORD(0)
            user32.GetWindowThreadProcessId(hit_handle, ctypes.byref(process_id))
            return int(process_id.value) in target_process_ids
        except Exception:
            return False

    def _image_match_within_owner(
        self,
        image_name: str,
        owner: Any | None,
        *,
        timeout: float = 0.0,
        x_range: tuple[float, float] = (0.0, 1.0),
        y_range: tuple[float, float] = (0.0, 1.0),
    ) -> tuple[int, int, int, int, float] | None:
        """仅接受目标进程指定宿主矩形及比例区域内的图片匹配。"""

        if owner is None:
            return None
        owner_bounds = self._wrapper_bounds(owner)
        if owner_bounds is None:
            return None
        try:
            if not owner.is_visible():
                return None
        except Exception:
            return None
        match = self.images.locate(
            image_name,
            timeout=timeout,
            required=False,
        )
        if match is None:
            return None
        left, top, right, bottom = owner_bounds
        owner_width = right - left
        owner_height = bottom - top
        x, y, width, height, _score = match
        center_x = x + width // 2
        center_y = y + height // 2
        min_x = left + int(owner_width * x_range[0])
        max_x = left + int(owner_width * x_range[1])
        min_y = top + int(owner_height * y_range[0])
        max_y = top + int(owner_height * y_range[1])
        if not (min_x <= center_x <= max_x and min_y <= center_y <= max_y):
            return None
        if not self._screen_point_belongs_to_target(center_x, center_y):
            return None
        return match

    def _click_verified_image_match(
        self,
        match: tuple[int, int, int, int, float],
    ) -> None:
        """点击已经过宿主和目标进程校验的图片结果，避免二次全屏匹配。"""

        x, y, width, height, _score = match
        center_x = x + width // 2
        center_y = y + height // 2
        if not self._screen_point_belongs_to_target(center_x, center_y):
            raise AutomationError("图片匹配点在点击前已不属于目标客户端，已停止点击")
        self.images.click_match(match)

    def _click_point_within_owner(
        self,
        owner: Any | None,
        x: int,
        y: int,
    ) -> bool:
        """仅在目标进程指定宿主矩形内点击图片派生坐标。"""

        bounds = self._wrapper_bounds(owner) if owner is not None else None
        if bounds is None:
            return False
        left, top, right, bottom = bounds
        if not (left <= x < right and top <= y < bottom):
            return False
        if not self._screen_point_belongs_to_target(x, y):
            return False
        self.pyautogui.click(int(x), int(y))
        return True

    def _client_main_window(self, timeout: float = 0.0) -> Any | None:
        return self.controls.find_by_class(
            "Tfrm_MainFrame",
            timeout=timeout,
            include_children=True,
            require_enabled=False,
        )

    def _legacy_comprehensive_match(
        self,
        timeout: float = 0.0,
    ) -> tuple[int, int, int, int, float] | None:
        """定位旧版左侧菜单中的“综合申报”，禁止全屏无宿主匹配。"""

        return self._image_match_within_owner(
            "综合申报",
            self._client_main_window(timeout=0),
            timeout=timeout,
            x_range=(0.0, 0.20),
            y_range=(0.08, 0.85),
        )

    def _income_type_page(self, timeout: float = 0.0) -> Any | None:
        page = self.controls.find_by_class(
            "Tfrm_SelectSDXM",
            timeout=timeout,
            include_children=True,
        )
        if page is None or not self._is_page_exposed(page):
            return None
        return page

    def _normal_salary_match(
        self,
        timeout: float = 0.0,
    ) -> tuple[int, int, int, int, float] | None:
        return self._image_match_within_owner(
            "正常工资所得",
            self._income_type_page(timeout=0),
            timeout=timeout,
            x_range=(0.0, 0.60),
            y_range=(0.0, 0.45),
        )

    def _click_normal_salary_entry(self, timeout: float = 8.0) -> None:
        match = self._normal_salary_match(timeout=timeout)
        if match is None:
            raise AutomationError(
                "未在当前前台收入项目页内识别到“正常工资薪金所得”入口"
            )
        self._click_verified_image_match(match)

    def _legacy_tax_step_match(
        self,
        view: Any | None,
        timeout: float = 0.0,
    ) -> tuple[int, int, int, int, float] | None:
        """只在前台预扣预缴主界面顶部识别旧版“税款计算”模板。"""

        if view is None or not self._is_page_exposed(view):
            return None
        return self._image_match_within_owner(
            "税款计算",
            view,
            timeout=timeout,
            x_range=(0.18, 0.58),
            y_range=(0.0, 0.14),
        )

    def _new_home_navigation_targets(
        self,
        timeout: float = 0.0,
    ) -> tuple[Any, Any] | None:
        """返回新版首页及其六宫格功能区，并严格校验两者的空间关系。"""

        home_page = self.controls.find_by_class(
            "Tfrm_ITSHomePage",
            timeout=timeout,
            include_children=True,
        )
        if home_page is None:
            return None
        feature_grid = self.controls.find_by_class(
            "TXPFarmerGridPanel",
            timeout=0,
            include_children=True,
        )
        if feature_grid is None:
            return None

        home_bounds = self._wrapper_bounds(home_page)
        grid_bounds = self._wrapper_bounds(feature_grid)
        if home_bounds is None or grid_bounds is None:
            return None
        home_left, home_top, home_right, home_bottom = home_bounds
        grid_left, grid_top, grid_right, grid_bottom = grid_bounds
        home_width = home_right - home_left
        home_height = home_bottom - home_top
        grid_width = grid_right - grid_left
        grid_height = grid_bottom - grid_top

        # 现场新版首页把六个功能入口放在页面上半部的 3x2 网格内。只有当
        # 网格被首页完整包含且尺寸比例合理时，才允许使用相对卡片位置。
        if (
            home_width < 800
            or home_height < 400
            or grid_left < home_left - 2
            or grid_top < home_top - 2
            or grid_right > home_right + 2
            or grid_bottom > home_bottom + 2
            or grid_width < int(home_width * 0.70)
            or not int(home_height * 0.15) <= grid_height <= int(home_height * 0.50)
            or grid_top > home_top + int(home_height * 0.45)
            or grid_width // 3 < 200
            or grid_height // 2 < 60
        ):
            return None
        return home_page, feature_grid

    def _wait_for_home_page(self) -> None:
        deadline = time.monotonic() + self.settings.page_timeout
        started_at = time.monotonic()
        next_progress_log = started_at + 5
        home_stable_since: float | None = None
        stable_source: str | None = None
        while time.monotonic() < deadline:
            # 提醒窗体可能比首页晚出现，必须先处理它再判断页面可操作。
            reminder_closed = self._dismiss_registration_reminder(timeout=0)
            if reminder_closed:
                home_stable_since = None
                stable_source = None

            # 新版客户端左侧菜单已改为“个人所得税申报”，旧的“综合申报”
            # 图片不再存在。优先用目标进程内的首页窗体和功能网格作为主证据；
            # 老版本仍保留原图片识别路径。
            native_targets = self._new_home_navigation_targets(timeout=0)
            native_home = self.controls.find_by_class(
                "Tfrm_ITSHomePage",
                timeout=0,
                include_children=True,
            )
            if native_targets is not None:
                current_source = "目标进程原生首页"
            elif native_home is not None:
                # 新版首页存在但网格结构无效时不得退到旧版模板，否则可能在
                # 新页面其他位置误命中相似文字。
                current_source = None
            elif self._legacy_comprehensive_match(timeout=0) is not None:
                current_source = "旧版首页图片"
            else:
                current_source = None

            if current_source is not None:
                now = time.monotonic()
                if home_stable_since is None or stable_source != current_source:
                    home_stable_since = now
                    stable_source = current_source
                # 首页连续稳定 3 秒且没有提醒窗体，才允许后续点击。
                if now - home_stable_since >= 3:
                    LOGGER.info("电子税务局首页已就绪（%s）", current_source)
                    return
            else:
                home_stable_since = None
                stable_source = None
            now = time.monotonic()
            if now >= next_progress_log:
                LOGGER.info(
                    "正在等待电子税务局首页，已等待 %d 秒……",
                    int(now - started_at),
                )
                next_progress_log = now + 5
            time.sleep(0.5)

        diagnostic = self.capture_diagnostics("home_page_timeout")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        raise AutomationError(
            f"等待电子税务局首页超时（{self.settings.page_timeout:g} 秒）{suffix}"
        )

    def _open_comprehensive_income_declaration(self) -> None:
        """兼容新旧首页进入综合所得申报，且不使用裸屏幕固定坐标。"""

        targets = self._new_home_navigation_targets(timeout=3)
        if targets is not None:
            _, feature_grid = targets
            grid_bounds = self._wrapper_bounds(feature_grid)
            assert grid_bounds is not None
            grid_left, grid_top, grid_right, grid_bottom = grid_bounds
            grid_width = grid_right - grid_left
            grid_height = grid_bottom - grid_top

            # 新版首页功能区固定为 3 列 2 行，“综合所得申报”是第一行第三列。
            # 坐标相对已验证的目标进程 Win32 网格，不依赖分辨率或屏幕原点。
            target = (int(grid_width * 5 / 6), int(grid_height * 1 / 4))
            LOGGER.info(
                "进入综合所得申报（新版首页常用功能第 1 行第 3 列）"
            )
            try:
                feature_grid.click_input(coords=target)
            except Exception as exc:
                raise AutomationError("无法点击新版首页的“综合所得申报”卡片") from exc
            time.sleep(0.8)
            return

        native_home = self.controls.find_by_class(
            "Tfrm_ITSHomePage",
            timeout=0,
            include_children=True,
        )
        if native_home is not None:
            diagnostic = self.capture_diagnostics("home_navigation_target_missing")
            suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
            raise AutomationError(
                "新版首页已出现，但未找到结构有效的常用功能网格，已停止点击" + suffix
            )

        legacy_match = self._legacy_comprehensive_match(timeout=3)
        if legacy_match is None:
            diagnostic = self.capture_diagnostics("legacy_home_navigation_missing")
            suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
            raise AutomationError("未识别到可验证的新版或旧版申报入口" + suffix)
        LOGGER.info("进入综合所得申报（旧版首页图片入口）")
        self._click_verified_image_match(legacy_match)

    def _close_optional_dialogs(self) -> None:
        # 该提示最常见且会遮挡整页，必须优先处理。
        self._dismiss_registration_reminder(timeout=1)

        if (
            self.controls.find_by_class("TfrmMessageInfo", timeout=0) is not None
            and self.controls.exists("弹窗", timeout=1.5)
        ):
            self.controls.click(
                "弹窗", timeout=2, anchor="middle_right", offset=(-10, 0)
            )
            if self.controls.exists("弹窗1", timeout=2):
                self.controls.click("弹窗1", timeout=2)

        collection_tip = self.controls.find_by_class(
            "TfrmCollectZxfjkcTips",
            timeout=0,
            include_children=True,
        )
        if collection_tip is not None:
            confirm_match = self._image_match_within_owner(
                "图像2",
                collection_tip,
                timeout=2,
                x_range=(0.15, 0.85),
                y_range=(0.45, 1.0),
            )
            if confirm_match is not None:
                self._click_verified_image_match(confirm_match)
            elif not self._click_dialog_button(
                collection_tip,
                ("确定",),
                fallback_x_ratio=0.50,
                fallback_bottom=30,
            ):
                raise AutomationError("无法关闭专项附加扣除信息提示")
            if not self._wait_window_gone(
                "TfrmCollectZxfjkcTips",
                timeout=5,
            ):
                raise AutomationError("专项附加扣除信息提示未关闭")

        if (
            self.controls.find_by_class("Tfrm_MsgDlgRich", timeout=0) is not None
            and self.controls.exists("确定生成零工记录", timeout=1)
        ):
            self.controls.click("确定生成零工记录", timeout=3)

    def _dismiss_zero_income_tip(self, timeout: float = 0.0) -> bool:
        """在连续三个月零收入提示中选择“暂不跳转”。"""

        class_name = "Tfrm_ZeroIncomeTip"
        dialog = self.controls.find_by_class(
            class_name,
            timeout=timeout,
            include_children=True,
        )
        if dialog is None:
            return False
        LOGGER.info("检测到连续零收入提示，选择“暂不跳转”……")

        clicked = False
        # 某些版本会暴露按钮文字，优先按文字点击。
        try:
            for child in dialog.descendants():
                if _wrapper_text(child).strip() == "暂不跳转":
                    child.click_input()
                    clicked = True
                    break
        except Exception:
            pass

        # 原生 TITSSpeedButton 经常不暴露文字。按弹窗自身的相对位置点击
        # 右侧按钮，避免受分辨率、窗口位置和 DPI 缩放影响。
        if not clicked:
            try:
                rectangle = dialog.rectangle()
                dialog.click_input(
                    coords=(
                        int(rectangle.width() * 0.58),
                        max(1, rectangle.height() - 27),
                    )
                )
                clicked = True
            except Exception:
                pass
        if clicked:
            time.sleep(1)

        remaining = self.controls.find_by_class(
            class_name,
            timeout=0,
            include_children=True,
        )
        if remaining is not None:
            # 保留原影刀选择器作为最后一次兜底，但不在正常路径反复扫描。
            try:
                self.controls.click("暂不跳转", timeout=3)
            except AutomationError:
                pass
            time.sleep(0.8)
            remaining = self.controls.find_by_class(
                class_name,
                timeout=0,
                include_children=True,
            )
        if remaining is not None:
            diagnostic = self.capture_diagnostics("zero_income_tip_not_closed")
            suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
            raise AutomationError("无法点击连续零收入提示中的“暂不跳转”" + suffix)

        LOGGER.info("已选择“暂不跳转”")
        return True

    def _wait_for_income_type_ready(self) -> None:
        """等待收入项目页稳定，并处理异步出现的连续零收入提示。"""

        deadline = time.monotonic() + self.settings.page_timeout
        started_at = time.monotonic()
        next_progress_log = started_at + 5
        stable_since: float | None = None
        while time.monotonic() < deadline:
            if self._dismiss_zero_income_tip(timeout=0):
                stable_since = None
            if self._normal_salary_match(timeout=0) is not None:
                now = time.monotonic()
                if stable_since is None:
                    stable_since = now
                if now - stable_since >= 2.5:
                    # 最后再查一次，确保没有刚刚出现的晚到弹窗。
                    if self.controls.find_by_class(
                        "Tfrm_ZeroIncomeTip",
                        timeout=0,
                        include_children=True,
                    ) is None:
                        LOGGER.info("收入项目页面已就绪")
                        return
                    stable_since = None
            else:
                stable_since = None

            now = time.monotonic()
            if now >= next_progress_log:
                LOGGER.info(
                    "正在等待收入项目页面，已等待 %d 秒……",
                    int(now - started_at),
                )
                next_progress_log = now + 5
            time.sleep(0.4)

        diagnostic = self.capture_diagnostics("income_type_page_timeout")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        raise AutomationError(
            f"等待收入项目页面超时（{self.settings.page_timeout:g} 秒）{suffix}"
        )

    def _handle_already_declared(self, timeout: float = 5.0) -> bool:
        """识别并关闭“本月数据已经申报”提示，交给外层继续导出而非重报。"""

        class_name = "Tfrm_MsgDlgRich"
        deadline = time.monotonic() + max(timeout, 0)
        last_dialog: Any | None = None
        last_match: tuple[int, int, int, int, float] | None = None
        while True:
            # 影刀原流程对这个分支已有专用选择器。精确命中时立即交给
            # _confirm_salary_import_prompt 处理，避免把它当成“已申报”弹窗等待。
            try:
                if self.controls.resolve_fast("没有申报提醒") is not None:
                    return False
            except Exception:
                pass
            dialog = self.controls.find_by_class(
                class_name,
                timeout=0,
                include_children=True,
            )
            if dialog is not None:
                last_dialog = dialog
                # 自动导入确认框不是“已经申报”。模板必须落在当前提示窗内，
                # 不能用全屏命中排除或确认业务状态。
                if self._image_match_within_owner(
                    "自动导入提示",
                    dialog,
                    timeout=0,
                ) is not None:
                    return False
                compact_text = self._dialog_text(dialog)
                if (
                    "还没有生成过正常工资薪金明细数据" in compact_text
                    or "自动导入正常工资薪金数据向导" in compact_text
                ):
                    # 这是未申报月份的自动导入确认框，不是“已经申报”。
                    return False
                text_confirmed = (
                    "数据已经申报" in compact_text
                    and "不能修改明细数据" in compact_text
                )
                last_match = self._image_match_within_owner(
                    "申报过",
                    dialog,
                    timeout=0,
                )
                if text_confirmed or (
                    last_match is not None and last_match[4] >= 0.66
                ):
                    break

            if time.monotonic() >= deadline:
                # 某些客户端不向 Win32 暴露正文，但图片仍必须位于已确认的
                # 提示窗内；没有宿主窗体时不允许仅凭全屏图片跳过申报。
                last_match = self._image_match_within_owner(
                    "申报过",
                    last_dialog,
                    timeout=0,
                )
                if last_match is None or last_match[4] < 0.66:
                    return False
                break
            time.sleep(0.35)

        LOGGER.info("检测到本月数据已经申报提示，按申报成功处理")
        clicked = False
        if last_dialog is not None:
            # 优先按按钮文字点击“确定”。
            try:
                for child in last_dialog.children():
                    if re.sub(r"\s+", "", _wrapper_text(child)) == "确定":
                        child.click_input()
                        clicked = True
                        break
            except Exception:
                pass
            # TITSSpeedButton 不暴露文字时，按钮位于提示窗底部中央。
            if not clicked:
                try:
                    rectangle = last_dialog.rectangle()
                    last_dialog.click_input(
                        coords=(
                            rectangle.width() // 2,
                            max(1, rectangle.height() - 32),
                        )
                    )
                    clicked = True
                except Exception:
                    pass
        if not clicked and last_match is not None:
            # 图像模板是提示正文；“确定”按钮位于正文中央下方约 44 像素。
            x, y, width, height, _ = last_match
            # 模板只截取提示后半句，弹窗中心约在模板左侧 10% 处。
            clicked = self._click_point_within_owner(
                last_dialog,
                x + int(width * 0.10),
                y + height + 44,
            )
        if clicked:
            time.sleep(0.6)
        return True

    @staticmethod
    def _dialog_text(dialog: Any) -> str:
        values = [_wrapper_text(dialog)]
        try:
            # 仅读取直接子控件。Delphi/UIA 全后代扫描可能在失败现场阻塞数十秒；
            # 正文不可见时，各业务步骤会使用明确的图片或相对坐标兜底。
            values.extend(_wrapper_text(child) for child in dialog.children())
        except Exception:
            pass
        return re.sub(r"\s+", "", " ".join(values))

    @staticmethod
    def _dialog_content_text(text_value: str) -> str:
        """移除窗体标题和按钮文字，判断 Delphi 是否真正暴露了正文。"""

        content = text_value
        for chrome_text in (
            "确认信息",
            "提示信息",
            "结果",
            "确认",
            "提示",
            "确定",
            "取消",
            "pnl_body",
            "btn1",
            "btn2",
            "是",
            "否",
        ):
            content = content.replace(chrome_text, "")
        return content.strip()

    @staticmethod
    def _result_dialog_confirm_button(dialog: Any) -> Any | None:
        """在当前结果窗内部按原影刀层级定位唯一的确认按钮。"""

        # 现场诊断中 Tfrm_MsgDlgRich 是主窗体的顶层 owned window，而不是
        # Win32 子窗口。直接从主窗体走完整 selector 可能无法跨到该窗体，
        # 因此从已经确认的结果窗向下严格匹配：
        # TPanel(pnl_body) > TPanel > TITSSpeedButton。
        try:
            body_panels = [
                child
                for child in dialog.children()
                if _wrapper_class_name(child).casefold() == "tpanel"
                and _wrapper_text(child).strip().casefold() == "pnl_body"
            ]
        except Exception:
            return None

        candidates: list[Any] = []
        for body in body_panels:
            try:
                inner_panels = [
                    child
                    for child in body.children()
                    if _wrapper_class_name(child).casefold() == "tpanel"
                ]
            except Exception:
                continue
            for panel in inner_panels:
                try:
                    children = panel.children()
                except Exception:
                    continue
                for child in children:
                    if _wrapper_class_name(child).casefold() != "titsspeedbutton":
                        continue
                    try:
                        if not child.is_visible() or not child.is_enabled():
                            continue
                    except Exception:
                        continue
                    candidates.append(child)

        unique: list[Any] = []
        seen: set[Any] = set()
        for candidate in candidates:
            try:
                identity: Any = ("handle", int(candidate.handle))
            except Exception:
                identity = ("object", id(candidate))
            if identity not in seen:
                seen.add(identity)
                unique.append(candidate)
        return unique[0] if len(unique) == 1 else None

    @staticmethod
    def _click_dialog_button(
        dialog: Any,
        labels: Sequence[str],
        fallback_x_ratio: float,
        fallback_bottom: int,
    ) -> bool:
        expected = {re.sub(r"\s+", "", value) for value in labels}
        try:
            for child in dialog.children():
                text_value = re.sub(r"\s+", "", _wrapper_text(child))
                if text_value in expected:
                    try:
                        child.click_input()
                    except Exception as exc:
                        # Windows 自动化接口可能在鼠标消息送达后才报告异常。
                        # 目标按钮一旦尝试过便不再按坐标补点，避免双击或误点底页。
                        LOGGER.warning(
                            "点击提示按钮后的状态未知，为避免重复点击将继续验证：%s",
                            exc,
                        )
                    time.sleep(0.8)
                    return True
        except Exception:
            pass
        try:
            rectangle = dialog.rectangle()
            dialog.click_input(
                coords=(
                    max(1, min(rectangle.width() - 1, int(rectangle.width() * fallback_x_ratio))),
                    max(1, rectangle.height() - fallback_bottom),
                )
            )
            time.sleep(0.8)
            return True
        except Exception:
            return False

    def _wait_window_gone(
        self,
        class_name: str,
        timeout: float = 5.0,
        include_children: bool = True,
    ) -> bool:
        deadline = time.monotonic() + max(timeout, 0)
        while time.monotonic() < deadline:
            if self.controls.find_by_class(
                class_name,
                timeout=0,
                include_children=include_children,
            ) is None:
                return True
            time.sleep(0.3)
        return self.controls.find_by_class(
            class_name,
            timeout=0,
            include_children=include_children,
        ) is None

    def _confirm_salary_import_prompt(self, timeout: float = 8.0) -> bool:
        """确认使用正常工资薪金自动导入向导。"""

        deadline = time.monotonic() + max(timeout, 0)
        dialog: Any | None = None
        prompt_match: tuple[int, int, int, int, float] | None = None
        detection_source = ""

        while True:
            # 续跑时可能已经打开导入向导，不需要再次处理确认框。
            wizard = self.controls.find_by_class(
                "TFrm_ImportConfig",
                timeout=0,
                include_children=True,
            )
            if wizard is not None:
                LOGGER.info("自动导入向导已出现，无需重复点击确认")
                return True

            prompt_marker: Any | None = None
            try:
                prompt_marker = self.controls.resolve_fast("没有申报提醒")
            except Exception:
                pass

            dialog = self.controls.find_by_class(
                "Tfrm_MsgDlgRich",
                timeout=0,
                include_children=False,
            )
            body_marker = self.controls.find_by_text_contains(
                (
                    "还没有生成过正常工资薪金明细数据",
                    "自动导入正常工资薪金数据向导",
                ),
                timeout=0,
            )
            prompt_match = self._image_match_within_owner(
                "自动导入提示",
                dialog,
                timeout=0,
            )

            text_value = self._dialog_text(dialog) if dialog is not None else ""
            if "数据已经申报" in text_value and "不能修改明细数据" in text_value:
                return False

            if (
                prompt_marker is not None
                and dialog is not None
                and self._is_control_exposed(
                    prompt_marker,
                    owner=dialog,
                    allow_owner_surface=True,
                )
            ):
                detection_source = "影刀原始精确选择器"
            elif (
                body_marker is not None
                and dialog is not None
                and self._is_control_exposed(
                    body_marker,
                    owner=dialog,
                    allow_owner_surface=True,
                )
            ):
                detection_source = "原生正文"
            elif prompt_match is not None:
                detection_source = "现场图片模板"
            elif dialog is not None:
                content_text = self._dialog_content_text(text_value)
                expected_text = (
                    "还没有生成过正常工资薪金明细数据" in text_value
                    or "自动导入正常工资薪金数据向导" in text_value
                )
                if expected_text:
                    detection_source = "确认信息窗体"
                elif content_text:
                    raise AutomationError(
                        f"进入正常工资薪金所得后出现未知提示：{text_value[:120]}"
                    )

            if detection_source:
                break
            if time.monotonic() >= deadline:
                return False
            time.sleep(0.3)

        LOGGER.info("检测到自动导入确认框（%s）", detection_source)
        clicked = False
        click_path = ""

        # 原影刀流程的精确按钮：Tfrm_MsgDlgRich(title=确认信息) 下的
        # TITSSpeedButton(index=1)。它比通用文字或坐标更可靠。
        try:
            button = self.controls.resolve_fast("确认生成数据")
            if button is not None:
                button.click_input()
                clicked = True
                click_path = "精确按钮选择器"
        except Exception:
            pass

        if not clicked:
            button = self.controls.find_by_text(("确定", "是"), timeout=0)
            if (
                button is not None
                and dialog is not None
                and self._is_control_exposed(
                    button,
                    owner=dialog,
                    allow_owner_surface=True,
                )
            ):
                try:
                    button.click_input()
                    clicked = True
                    click_path = "按钮文字"
                except Exception:
                    pass

        if not clicked and dialog is not None:
            clicked = self._click_dialog_button(
                dialog,
                ("确定", "是"),
                fallback_x_ratio=0.43,
                fallback_bottom=30,
            )
            if clicked:
                click_path = "窗体相对坐标"

        if not clicked and prompt_match is not None:
            # 模板截取的是不含月份的第二行固定文字；确定按钮中心位于
            # 模板左侧约 46.5%、下方约 31 像素处。
            x, y, width, height, _ = prompt_match
            clicked = self._click_point_within_owner(
                dialog,
                x + int(width * 0.465),
                y + height + 31,
            )
            if clicked:
                click_path = "弹窗内图片相对坐标"

        if not clicked:
            raise AutomationError("无法点击自动导入向导提示中的“确定”")
        LOGGER.info("已点击自动导入确认框“确定”（%s）", click_path)

        # 点击后不使用固定休眠：动态等待确认框关闭并等待导入向导真正出现。
        wait_timeout = max(12.0, min(self.settings.page_timeout, 30.0))
        wait_deadline = time.monotonic() + wait_timeout
        retry_at = time.monotonic() + 2.0
        retried = False
        while time.monotonic() < wait_deadline:
            wizard = self.controls.find_by_class(
                "TFrm_ImportConfig",
                timeout=0,
                include_children=True,
            )
            generate_control: Any | None = None
            try:
                generate_control = self.controls.resolve_fast("导入零工工资记录")
            except Exception:
                pass
            record_ready = self._image_match_within_owner(
                "记录数据",
                wizard,
                timeout=0,
            ) is not None
            if wizard is not None or generate_control is not None or record_ready:
                LOGGER.info("自动导入确认框已关闭，导入向导已出现")
                return True

            if not retried and time.monotonic() >= retry_at:
                remaining_marker: Any | None = None
                try:
                    remaining_marker = self.controls.resolve_fast("没有申报提醒")
                except Exception:
                    pass
                remaining_dialog = self.controls.find_by_class(
                    "Tfrm_MsgDlgRich",
                    timeout=0,
                    include_children=False,
                )
                remaining_match = self._image_match_within_owner(
                    "自动导入提示",
                    remaining_dialog,
                    timeout=0,
                )
                # 只有专用选择器或专用图片仍确认是同一个弹窗时才重试，
                # 避免误点随后出现的其他 Tfrm_MsgDlgRich 提示。
                retry_clicked = False
                if remaining_marker is not None:
                    try:
                        retry_button = self.controls.resolve_fast("确认生成数据")
                        if retry_button is not None:
                            retry_button.click_input()
                            retry_clicked = True
                            LOGGER.warning("自动导入确认框未关闭，已按精确按钮重试一次")
                    except Exception:
                        pass
                if not retry_clicked and remaining_match is not None and remaining_dialog is not None:
                    if self._click_dialog_button(
                        remaining_dialog,
                        ("确定", "是"),
                        fallback_x_ratio=0.43,
                        fallback_bottom=30,
                    ):
                        retry_clicked = True
                        LOGGER.warning("自动导入确认框未关闭，已按相对坐标重试一次")
                retried = True
            time.sleep(0.3)

        raise AutomationError(
            f"点击自动导入确认框后，等待导入向导超时（{wait_timeout:g} 秒）"
        )

    def _generate_zero_salary_record(self, timeout: float = 15.0) -> bool:
        """选择“生成零工资记录，用户手工修改”并立即生成数据。"""

        deadline = time.monotonic() + max(timeout, 0)
        wizard: Any | None = None
        record_match: tuple[int, int, int, int, float] | None = None
        while time.monotonic() < deadline:
            wizard = self.controls.find_by_class(
                "TFrm_ImportConfig",
                timeout=0,
                include_children=True,
            )
            record_match = self._image_match_within_owner(
                "记录数据",
                wizard,
                timeout=0,
            )
            if record_match is not None:
                break
            time.sleep(0.35)
        if wizard is None or record_match is None:
            return False

        LOGGER.info("选择“生成零工资记录，用户手工修改”")
        self._click_verified_image_match(record_match)
        time.sleep(0.5)
        generate_button = self.controls.find_by_text(
            ("立即生成数据", "生成数据"),
            timeout=1.5,
        )
        if generate_button is not None and not self._is_control_exposed(
            generate_button,
            owner=wizard,
            allow_owner_surface=True,
        ):
            generate_button = None
        if generate_button is not None:
            try:
                self.salary_generation_started = True
                generate_button.click_input()
                time.sleep(0.8)
            except Exception as exc:
                # click_input 可能已经把消息送达后才抛出异常。此时不能再换一种
                # 方式点击一次，否则可能重复生成。
                raise AutomationError(
                    f"点击“立即生成数据”后状态未知：{exc}"
                ) from exc
        if generate_button is None:
            # 只有已确认的导入向导窗体才允许相对坐标兜底。旧代码在宿主
            # 不明时按模板 y+3.3h 外推按钮，可能点击到底层页面，现已禁用。
            rectangle = wizard.rectangle()
            self.salary_generation_started = True
            wizard.click_input(
                coords=(
                    int(rectangle.width() * 0.445),
                    max(1, rectangle.height() - 25),
                )
            )
            time.sleep(0.8)

        LOGGER.info("零工资生成请求已发出，正在等待生成结果提示")

        result_dialog = self.controls.find_by_class(
            "Tfrm_MsgDlgRich",
            timeout=20,
            include_children=True,
        )
        if result_dialog is None:
            raise AutomationError("点击“立即生成数据”后未出现生成结果提示")
        result_text = self._dialog_text(result_dialog)
        result_content = self._dialog_content_text(result_text)
        explicit_success = "生成" in result_text and "工资薪金数据" in result_text
        visible_failure = self.controls.find_by_text_contains(
            ("失败", "错误", "异常", "无法", "不能", "校验不通过", "未生成"),
            timeout=0,
        )
        if visible_failure is not None:
            failure_text = _wrapper_text(visible_failure).strip() or "检测到失败提示"
            raise AutomationError(f"生成零工资记录失败：{failure_text[:120]}")
        if result_content and not explicit_success:
            raise AutomationError(f"生成零工资记录出现未知提示：{result_text[:120]}")

        # 现场版本把成功正文自绘在面板上，Win32 只能读取到
        # “提示信息/pnl_body”。正文不可读时必须命中完整的原影刀结果窗
        # 选择器；不能使用“主窗体内唯一按钮”兜底，以免误点其他提示。
        strict_confirm = self._result_dialog_confirm_button(result_dialog)
        try:
            if strict_confirm is None:
                strict_confirm = self.controls.resolve_strict_fast("确定生成零工记录")
        except Exception:
            pass
        if not explicit_success and strict_confirm is None:
            raise AutomationError(
                "生成结果正文不可读取，且未命中预期的零工资生成结果窗口"
            )

        if explicit_success:
            LOGGER.info("检测到工资薪金数据生成成功提示，正在确认并核验页面")
        else:
            LOGGER.info(
                "生成结果正文未暴露给 Win32，但已命中零工资结果窗完整结构，"
                "正在确认并核验页面"
            )

        clicked = False
        if strict_confirm is not None:
            try:
                strict_confirm.click_input()
                time.sleep(0.8)
                clicked = True
            except Exception as exc:
                # 该点击可能已经送达，不能再按相同位置补点一次。
                raise AutomationError(
                    f"点击工资薪金数据生成结果“确定”后状态未知：{exc}"
                ) from exc
        # 只有已读到明确成功正文时，才允许使用相对坐标兜底。
        if not clicked and explicit_success:
            clicked = self._click_dialog_button(
                result_dialog,
                ("确定",),
                fallback_x_ratio=0.50,
                fallback_bottom=29,
            )
        if not clicked:
            raise AutomationError("无法点击工资薪金数据生成结果中的“确定”")
        if not self._wait_window_gone("Tfrm_MsgDlgRich", timeout=5):
            raise AutomationError("工资薪金数据生成结果提示未关闭")

        # 动态等待导入向导退出，并确认工资明细页面重新变为可操作状态。
        # 这一步是正文不可读时的后置验证，也避免仅凭一个通用提示窗误判成功。
        verify_started = time.monotonic()
        verify_deadline = verify_started + min(max(self.settings.page_timeout, 8.0), 20.0)
        next_verify_log = verify_started + 5
        while time.monotonic() < verify_deadline:
            wizard_remaining = self.controls.find_by_class(
                "TFrm_ImportConfig",
                timeout=0,
                include_children=True,
            )
            salary_page = self.controls.find_by_class(
                "TFrm_YKYJView_ReportFill",
                timeout=0,
                include_children=True,
            )
            record_option_visible = self._image_match_within_owner(
                "记录数据",
                wizard_remaining,
                timeout=0,
            ) is not None
            page_ready = False
            if salary_page is not None:
                try:
                    page_ready = bool(salary_page.is_visible() and salary_page.is_enabled())
                except Exception:
                    # 句柄失效或状态读取失败时不能按成功放行，等待下一轮重新定位。
                    page_ready = False
            if wizard_remaining is None and not record_option_visible and page_ready:
                self.salary_generation_verified = True
                LOGGER.info(
                    "零工资结果窗口已关闭：导入向导已退出，工资明细页恢复可操作"
                )
                return True
            now = time.monotonic()
            if now >= next_verify_log:
                LOGGER.info(
                    "正在核验零工资生成后的页面状态，已等待 %d 秒……",
                    int(now - verify_started),
                )
                next_verify_log = now + 5
            time.sleep(0.35)
        raise AutomationError("生成结果提示已关闭，但工资明细页面未恢复为可操作状态")

    def _salary_detail_return_button(self) -> tuple[Any | None, Any | None]:
        """在当前工资明细页内严格定位左上角无文字“返回”按钮。"""

        salary_page = self.controls.find_by_class(
            "TFrm_YKYJView_ReportFill",
            timeout=1,
            include_children=True,
        )
        if salary_page is None or not self._is_page_exposed(salary_page):
            return None, salary_page
        page_bounds = self._wrapper_bounds(salary_page)
        if page_bounds is None:
            return None, salary_page
        page_left, page_top, page_right, page_bottom = page_bounds
        page_width = page_right - page_left
        page_height = page_bottom - page_top

        # Delphi 自绘按钮没有文字。只在已确认位于前台的工资明细页内部做
        # 有界遍历，并把候选限制在左上工具栏区域；候选不唯一时停止点击。
        queue: list[tuple[Any, int]] = [(salary_page, 0)]
        candidates: list[Any] = []
        candidate_keys: set[tuple[str, int]] = set()
        visited = 0
        while queue and visited < 80:
            current, depth = queue.pop(0)
            visited += 1
            try:
                children = current.children()
            except Exception:
                continue
            for child in children:
                if _wrapper_class_name(child).casefold() == "titsspeedbutton":
                    bounds = self._wrapper_bounds(child)
                    if bounds is None or not self._wrapper_is_clickable(child):
                        continue
                    left, top, right, bottom = bounds
                    center_x_ratio = ((left + right) / 2 - page_left) / page_width
                    center_y_ratio = ((top + bottom) / 2 - page_top) / page_height
                    if not (
                        0.005 <= center_x_ratio <= 0.055
                        and 0.04 <= center_y_ratio <= 0.13
                        and right - left <= page_width * 0.08
                        and bottom - top <= page_height * 0.08
                    ):
                        continue
                    if self._is_control_exposed(
                        child,
                        owner=salary_page,
                        allow_owner_surface=True,
                    ):
                        # pywinauto/VCL 子控件图不是严格树结构，同一个原生
                        # 按钮可能经多个容器路径返回；按 HWND 身份只计一次。
                        try:
                            native_handle = int(child.handle)
                        except Exception:
                            native_handle = 0
                        candidate_key = (
                            ("hwnd", native_handle)
                            if native_handle > 0
                            else ("wrapper", id(child))
                        )
                        if candidate_key not in candidate_keys:
                            candidate_keys.add(candidate_key)
                            candidates.append(child)
                    continue
                if depth < 3:
                    queue.append((child, depth + 1))

        if len(candidates) > 1:
            raise AutomationError(
                "工资明细页左上返回按钮候选不唯一，已停止点击以避免误操作"
            )
        return (candidates[0] if candidates else None), salary_page

    def _income_summary_ready(self) -> bool:
        """确认预扣预缴汇总页处于前台且四个步骤按钮结构完整。"""

        tax_button, summary_page = self._tax_step_button()
        if summary_page is None or not self._is_page_exposed(summary_page):
            # 原影刀旧版的税款/报送选择器同样依赖 Tfrm_YKYJView_Main。
            # 项目没有独立的旧版报送入口模板，因此缺少主界面时必须停止，
            # 不能仅凭全屏“税款计算”图片声称主链可继续。
            return False
        if tax_button is not None:
            return True
        # 旧版步骤按钮可能不暴露为可枚举控件；只接受当前前台主界面
        # 顶部步骤区内、且属于目标进程的历史图片。
        return self._legacy_tax_step_match(summary_page, timeout=0) is not None

    def _wait_for_income_summary(self, timeout: float) -> bool:
        deadline = time.monotonic() + max(timeout, 0.0)
        while time.monotonic() < deadline:
            if self._income_summary_ready():
                return True
            time.sleep(0.35)
        return self._income_summary_ready()

    def _return_to_income_summary(self) -> None:
        """点击“返回/返回上一步”，确认回到综合所得申报汇总页。"""

        if self._income_summary_ready():
            LOGGER.info("当前已经位于综合所得申报汇总页")
            return

        LOGGER.info("点击“返回上一步”")
        return_button, salary_page = self._salary_detail_return_button()
        if return_button is None:
            text_button = self.controls.find_by_text(
                ("返回", "返回上一步"),
                timeout=2,
            )
            if text_button is not None and (
                salary_page is None
                or self._is_control_exposed(
                    text_button,
                    owner=salary_page,
                    allow_owner_surface=True,
                )
            ):
                return_button = text_button

        clicked = False
        if return_button is not None:
            try:
                return_button.click_input()
                clicked = True
                LOGGER.info("已点击工资明细页左上“返回”按钮")
            except Exception as exc:
                # 点击消息可能已经送达，不能改用另一条路径重复点击。
                raise AutomationError(
                    f"点击工资明细页“返回”后状态未知：{exc}"
                ) from exc

        wait_seconds = min(max(self.settings.page_timeout, 4.0), 12.0)
        if clicked and self._wait_for_income_summary(wait_seconds):
            LOGGER.info("已返回综合所得申报汇总页（原生页面结构确认）")
            return

        # 仅在明确命中旧版首页图片时保留历史兼容路径；新版界面不再盲点
        # “综合申报”，避免把工资明细页中的相似区域误认为菜单入口。
        legacy_match = self._legacy_comprehensive_match(timeout=0)
        if legacy_match is not None:
            LOGGER.info("使用旧版左侧“综合申报”图片入口返回汇总页")
            self._click_verified_image_match(legacy_match)
            if self._wait_for_income_summary(min(wait_seconds, 8.0)):
                LOGGER.info("已返回综合所得申报汇总页（旧版图片兼容路径）")
                return

        diagnostic = self.capture_diagnostics("income_summary_return_failed")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        if not clicked:
            raise AutomationError("未找到当前工资明细页的返回按钮" + suffix)
        raise AutomationError("点击返回后未识别到综合所得申报汇总页" + suffix)

    def _report_page(self, timeout: float = 0.0) -> Any | None:
        # 成功提示等模态窗出现时，报送页本身会被 Delphi 临时禁用；状态读取
        # 仍需取得它的矩形和背景文字，因此这里只要求可见，不要求 enabled。
        return self.controls.find_by_class(
            "Tfrm_YKYJReportDeclare",
            timeout=timeout,
            include_children=True,
            require_enabled=False,
        )

    @staticmethod
    def _is_page_exposed(page: Any) -> bool:
        """确认叠放的 Delphi 页面当前确实位于屏幕最前层。

        VCL 切换步骤后，旧页面 HWND 仍可能保持 ``visible=True``。仅检查
        类名/visible 会把被覆盖的报送页或税款页误判为当前页。这里在页面
        内容区取 5 个探针点；命中页面本身或其子控件的点达到多数才算前台。
        """

        try:
            page_handle = int(page.handle)
            rectangle = page.rectangle()
            left = int(rectangle.left)
            top = int(rectangle.top)
            width = int(rectangle.width())
            height = int(rectangle.height())
        except Exception:
            return False
        if page_handle <= 0 or width <= 0 or height <= 0:
            return False

        try:
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            user32.WindowFromPoint.argtypes = [wintypes.POINT]
            user32.WindowFromPoint.restype = wintypes.HWND
            user32.IsChild.argtypes = [wintypes.HWND, wintypes.HWND]
            user32.IsChild.restype = wintypes.BOOL
        except Exception:
            return False

        probe_ratios = (
            (0.20, 0.38),
            (0.50, 0.38),
            (0.80, 0.38),
            (0.25, 0.72),
            (0.75, 0.72),
        )
        matched = 0
        checked = 0
        for x_ratio, y_ratio in probe_ratios:
            point = wintypes.POINT(
                left + max(1, min(width - 1, int(width * x_ratio))),
                top + max(1, min(height - 1, int(height * y_ratio))),
            )
            try:
                hit_handle = int(user32.WindowFromPoint(point) or 0)
            except Exception:
                continue
            if hit_handle <= 0:
                continue
            checked += 1
            if hit_handle == page_handle or bool(
                user32.IsChild(page_handle, hit_handle)
            ):
                matched += 1
        return checked >= 3 and matched >= 2 and matched * 2 > checked

    @staticmethod
    def _is_control_exposed(
        control: Any,
        owner: Any | None = None,
        *,
        allow_owner_surface: bool = False,
    ) -> bool:
        """确认控件中心仍位于控件/父容器所在的当前页面。

        Delphi 的 ``TITSSpeedButton`` 经常是自绘控件，``WindowFromPoint``
        命中的可能是父工具栏的绘制表面，而不是按钮句柄本身。默认仍要求
        按钮与命中 HWND 互为父子；对于已经由严格层级定位到的按钮，可通过
        ``allow_owner_surface`` 允许命中同一父工具栏，但绝不放行页面外窗口。
        """

        try:
            control_handle = int(control.handle)
            rectangle = control.rectangle()
            point = wintypes.POINT(
                int(rectangle.left + rectangle.width() // 2),
                int(rectangle.top + rectangle.height() // 2),
            )
        except Exception:
            return False
        if control_handle <= 0 or rectangle.width() <= 0 or rectangle.height() <= 0:
            return False
        try:
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            user32.WindowFromPoint.argtypes = [wintypes.POINT]
            user32.WindowFromPoint.restype = wintypes.HWND
            user32.IsChild.argtypes = [wintypes.HWND, wintypes.HWND]
            user32.IsChild.restype = wintypes.BOOL
            hit_handle = int(user32.WindowFromPoint(point) or 0)
        except Exception:
            return False
        if hit_handle <= 0:
            return False
        related_to_control = bool(
            hit_handle == control_handle
            or user32.IsChild(control_handle, hit_handle)
            or user32.IsChild(hit_handle, control_handle)
        )
        if owner is None:
            return related_to_control
        try:
            owner_handle = int(owner.handle)
        except Exception:
            return False
        if owner_handle <= 0:
            return False
        control_in_owner = bool(
            control_handle == owner_handle
            or user32.IsChild(owner_handle, control_handle)
        )
        hit_in_owner = bool(
            hit_handle == owner_handle or user32.IsChild(owner_handle, hit_handle)
        )
        return control_in_owner and hit_in_owner and (
            related_to_control or allow_owner_surface
        )

    @staticmethod
    def _is_duplicate_period_feedback(text: str) -> bool:
        """仅接受税局明确返回的当前所属期重复申报反馈。"""
        normalized = re.sub(r"\s+", "", text).replace(",", "，")
        return "申报失败，当前税款所属期已申报，请勿重复申报" in normalized

    def _confirm_submission_result_dialog(self, dialog: Any) -> bool:
        """仅确认当前结果窗，并验证原窗口消失；这不是申报成功证据。"""

        if not self._is_page_exposed(dialog):
            return False
        button = self._result_dialog_confirm_button(dialog)
        dialog_text = self._dialog_text(dialog)
        if button is None and (
            "申报成功" in dialog_text
            or self._is_duplicate_period_feedback(dialog_text)
        ):
            # 部分旧版是 TfrmBase，不使用 pnl_body 层级。只在当前结果窗的
            # 有界子树内接受唯一、明确命名的按钮，不使用通用“确定”图片。
            candidates: list[Any] = []
            queue: list[tuple[Any, int]] = [(dialog, 0)]
            seen: set[int] = set()
            while queue and len(seen) < 80:
                current, depth = queue.pop(0)
                identity = int(getattr(current, "handle", 0) or id(current))
                if identity in seen:
                    continue
                seen.add(identity)
                if (
                    _wrapper_text(current).strip() == "确定"
                    and "button" in _wrapper_class_name(current).casefold()
                    and self._wrapper_is_clickable(current)
                ):
                    candidates.append(current)
                if depth < 5:
                    try:
                        queue.extend((child, depth + 1) for child in current.children())
                    except Exception:
                        pass
            if len(candidates) == 1:
                button = candidates[0]
        if button is None or not self._is_control_exposed(
            button, owner=dialog, allow_owner_surface=True
        ):
            return False

        original_handle = int(getattr(dialog, "handle", 0) or id(dialog))
        attempted = getattr(self, "_result_confirmation_attempted", set())
        self._result_confirmation_attempted = attempted
        if original_handle not in attempted:
            attempted.add(original_handle)
            try:
                button.click_input()
            except Exception as exc:
                # 点击可能已经送达；不补点坐标、更不重复发送申报。
                LOGGER.warning("点击申报结果“确定”后的状态未知，验证窗口是否关闭：%s", exc)

        deadline = time.monotonic() + min(5.0, self.settings.page_timeout)
        while time.monotonic() < deadline:
            still_open = False
            for class_name in ("Tfrm_MsgDlgRich", "TfrmBase"):
                current = self.controls.find_by_class(
                    class_name, timeout=0, include_children=True
                )
                if current is not None and int(
                    getattr(current, "handle", 0) or id(current)
                ) == original_handle:
                    still_open = True
                    break
            if not still_open:
                LOGGER.info("申报结果“确定”已确认，提示窗口已关闭；继续核验报送页成功状态")
                return True
            time.sleep(0.2)
        raise AutomationError("已尝试点击申报结果“确定”，但结果窗口未关闭；不重复发送，需核验现场")

    def _dismiss_success_dialog(self) -> bool:
        """关闭明确的成功结果提示；返回值仅表示窗口已关闭。"""

        for class_name in ("Tfrm_MsgDlgRich", "TfrmBase"):
            dialog = self.controls.find_by_class(
                class_name,
                timeout=0,
                include_children=True,
            )
            if dialog is None:
                continue
            text_value = self._dialog_text(dialog)
            if "申报成功" not in text_value:
                continue
            # 即使是启动前已存在的结果窗，也证明曾发生提交。后续核验失败
            # 不能按“本次尚未发送”重启并重新申报。
            self.submission_started = True
            LOGGER.info("检测到申报成功提示，先点击“确定”并验证提示关闭")
            return self._confirm_submission_result_dialog(dialog)
        return False

    def _report_state_image_visible(
        self,
        image_name: str,
        report_page: Any | None,
    ) -> bool:
        """在报送页左上状态区内识别状态模板。

        报送页加载后有时会暂时处于 disabled，不能再次通过 ``_report_page``
        的 enabled 门槛来决定是否允许识图；调用方传入刚确认过的页面句柄，
        图片中心再受页面左上状态区约束，避免小模板在桌面其他位置误报。
        """

        match = self.images.locate(image_name, timeout=0, required=False)
        if match is None:
            return False
        bounds: tuple[int, int, int, int] | None = None
        try:
            page_rectangle = report_page.rectangle()
            bounds = (
                int(page_rectangle.left),
                int(page_rectangle.top),
                int(page_rectangle.right),
                int(page_rectangle.bottom),
            )
        except Exception:
            bounds = getattr(self, "last_report_bounds", None)
        if bounds is None:
            return False
        left, top, right, bottom = bounds
        page_width = right - left
        page_height = bottom - top
        if page_width <= 0 or page_height <= 0:
            return False
        x, y, width, height, _score = match
        center_x = x + width // 2
        center_y = y + height // 2
        return bool(
            left <= center_x <= left + int(page_width * 0.45)
            and top <= center_y <= top + int(page_height * 0.28)
        )

    @staticmethod
    def _page_contains_text(
        page: Any,
        fragments: str | Sequence[str],
        *,
        max_nodes: int = 240,
        max_depth: int = 10,
    ) -> bool:
        """只在指定页面的可见 Win32 子树内查文字，避免后台旧页面污染状态。"""

        expected = (fragments,) if isinstance(fragments, str) else tuple(fragments)
        expected = tuple(re.sub(r"\s+", "", value) for value in expected if value)
        if not expected:
            return False
        queue: list[tuple[Any, int]] = [(page, 0)]
        seen: set[tuple[str, int]] = set()
        visited = 0
        while queue and visited < max_nodes:
            current, depth = queue.pop(0)
            visited += 1
            try:
                identity = ("handle", int(current.handle))
            except Exception:
                identity = ("object", id(current))
            if identity in seen:
                continue
            seen.add(identity)
            try:
                visible = bool(current.is_visible())
            except Exception:
                visible = False
            if visible:
                text_value = re.sub(r"\s+", "", _wrapper_text(current))
                if any(value in text_value for value in expected):
                    return True
            if depth >= max_depth:
                continue
            try:
                children = current.children()
            except Exception:
                continue
            for child in children:
                queue.append((child, depth + 1))
        return False

    def _report_success_visible(self, report_page: Any | None = None) -> bool:
        """结果提示必须先关闭，再以当前报送页状态确认成功。"""

        dismissed = self._dismiss_success_dialog()
        deadline = time.monotonic() + min(30.0, self.settings.page_timeout)
        next_log = time.monotonic() + 5
        while True:
            blocked = any(
                self.controls.find_by_class(
                    class_name, timeout=0, include_children=True
                ) is not None
                for class_name in ("Tfrm_MsgDlgRich", "TfrmBase", "Tfrm_FeedbackWaiting")
            )
            # 确认结果后 Delphi 可能重建报送页，不能使用被禁用的旧 HWND。
            confirmed_page = (
                report_page
                if report_page is not None and not dismissed
                else self._report_page(timeout=0)
            )
            if (
                not blocked
                and confirmed_page is not None
                and self._is_page_exposed(confirmed_page)
                and (
                    self._report_state_image_visible("申报成功状态", confirmed_page)
                    or self._page_contains_text(confirmed_page, "申报成功")
                )
            ):
                return True
            if not dismissed:
                return False
            # 发送前的状态检查也会调用本方法。已经看到并关闭成功结果后，
            # 不能返回 False 让调用方走待申报/发送分支，必须得到最终证据。
            now = time.monotonic()
            if now >= deadline:
                raise AutomationError(
                    "成功结果提示已确认，但报送页成功状态尚未核验；不重复发送，请检查当前结果"
                )
            if now >= next_log:
                LOGGER.info("已点击申报结果“确定”，等待报送页更新成功状态……")
                next_log = now + 5
            time.sleep(0.4)

    def _report_pending_visible(self, report_page: Any | None = None) -> bool:
        confirmed_page = (
            report_page if report_page is not None else self._report_page(timeout=0)
        )
        if self._report_state_image_visible("待申报状态", confirmed_page):
            return True
        if confirmed_page is None or not self._is_page_exposed(confirmed_page):
            return False
        return self._page_contains_text(confirmed_page, "待申报")

    def _report_interaction_blocked(self) -> bool:
        """报送页被进度窗口或非成功模态框遮挡时禁止推断/发送。"""

        if self._progress_visible():
            return True
        return any(
            self.controls.find_by_class(
                class_name,
                timeout=0,
                include_children=True,
            )
            is not None
            for class_name in ("Tfrm_MsgDlgRich", "TfrmBase")
        )

    def _wait_for_report_state(
        self,
        timeout: float | None = None,
        report_page: Any | None = None,
        allow_pending_fallback: bool = False,
        allow_send_button_pending: bool = False,
    ) -> str:
        """等待报送页给出权威状态，返回 ``success`` 或 ``pending``。"""

        wait_seconds = self.settings.page_timeout if timeout is None else timeout
        deadline = time.monotonic() + max(wait_seconds, 0)
        started_at = time.monotonic()
        next_progress_log = started_at + 5
        # 用户业务规则：只有明确出现“申报成功、无需缴款”才算成功；报送页
        # 已稳定显示而 8 秒内没有成功证据时，按未申报返回税款计算。
        pending_fallback_at = started_at + min(8.0, max(wait_seconds, 0))
        confirmed_page = (
            report_page if report_page is not None else self._report_page(timeout=0)
        )
        send_ready_identity: tuple[int, int] | None = None
        send_ready_count = 0
        while time.monotonic() < deadline:
            # 状态刷新时 VCL 可能重建报送页 HWND。每轮只接受当前实际暴露在
            # 前台的新句柄，避免继续在已失效/被覆盖的 wrapper 上累积确认次数。
            current_page = self._report_page(timeout=0)
            if current_page is not None and self._is_page_exposed(current_page):
                confirmed_page = current_page
                self.last_report_page = current_page
                try:
                    current_rectangle = current_page.rectangle()
                    self.last_report_bounds = (
                        int(current_rectangle.left),
                        int(current_rectangle.top),
                        int(current_rectangle.right),
                        int(current_rectangle.bottom),
                    )
                except Exception:
                    pass
            if self._report_success_visible(confirmed_page):
                return "success"
            interaction_blocked = self._report_interaction_blocked()
            if not interaction_blocked and self._report_pending_visible(confirmed_page):
                return "pending"

            # 部分客户端/DPI 下“待申报”是自绘文字，状态模板也可能因抗锯齿
            # 漏识别。算税完成后，前台报送页顶部恰好只有“导出申报表”和
            # “发送申报”两个按钮，且右侧按钮已启用，同样是明确的可申报证据。
            # 成功页有 4 个操作按钮，_native_report_send_button 会拒绝该结构。
            send_ready_button = None
            if (
                allow_send_button_pending
                and confirmed_page is not None
                and self._is_page_exposed(confirmed_page)
                and not interaction_blocked
            ):
                send_ready_button = self._native_report_send_button(confirmed_page)
            if send_ready_button is not None and self._wrapper_is_clickable(
                send_ready_button
            ):
                try:
                    identity = (
                        int(confirmed_page.handle),
                        int(send_ready_button.handle),
                    )
                except Exception:
                    identity = (0, 0)
                if identity[0] <= 0 or identity[1] <= 0:
                    send_ready_identity = None
                    send_ready_count = 0
                elif identity == send_ready_identity:
                    send_ready_count += 1
                else:
                    send_ready_identity = identity
                    send_ready_count = 1
                if send_ready_count >= 2:
                    LOGGER.info(
                        "状态文字未识别，但已连续确认前台报送页“发送申报”按钮启用，"
                        "按待申报处理"
                    )
                    return "pending"
            else:
                send_ready_identity = None
                send_ready_count = 0

            now = time.monotonic()
            if (
                allow_pending_fallback
                and now >= pending_fallback_at
                and confirmed_page is not None
            ):
                page_visible = self._is_page_exposed(confirmed_page)
                if page_visible and not interaction_blocked:
                    LOGGER.warning(
                        "报送页未检测到明确的“申报成功、无需缴款”状态，"
                        "按未申报处理并返回税款计算"
                    )
                    return "pending"
            if now >= next_progress_log:
                LOGGER.info(
                    "正在读取申报表报送状态，已等待 %d 秒……",
                    int(now - started_at),
                )
                next_progress_log = now + 5
            time.sleep(0.5)

        diagnostic = self.capture_diagnostics("report_state_timeout")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        raise AutomationError(
            f"等待申报表报送状态超时（{wait_seconds:g} 秒），"
            f"未识别到“待申报”或“申报成功”{suffix}"
        )

    def _guide_step_buttons(self, view: Any) -> list[Any]:
        """返回前台主界面顶部恰好四个、按 HWND 去重的步骤按钮。"""

        if not self._is_page_exposed(view):
            return []
        view_bounds = self._wrapper_bounds(view)
        if view_bounds is None:
            return []
        view_left, view_top, view_right, view_bottom = view_bounds
        view_width = view_right - view_left
        view_height = view_bottom - view_top

        queue: list[tuple[Any, int]] = [(view, 0)]
        queue_seen: set[tuple[str, int]] = set()
        candidates: list[Any] = []
        candidate_seen: set[tuple[str, int]] = set()
        visited = 0
        while queue and visited < 80:
            current, depth = queue.pop(0)
            try:
                current_key = ("handle", int(current.handle))
            except Exception:
                current_key = ("object", id(current))
            if current_key in queue_seen:
                continue
            queue_seen.add(current_key)
            visited += 1
            try:
                children = self._unique_native_wrappers(current.children())
            except Exception:
                continue
            for child in children:
                if _wrapper_class_name(child).casefold() == "tguidebutton":
                    bounds = self._wrapper_bounds(child)
                    if bounds is None or not self._wrapper_is_clickable(child):
                        continue
                    left, top, right, bottom = bounds
                    center_x_ratio = ((left + right) / 2 - view_left) / view_width
                    center_y_ratio = ((top + bottom) / 2 - view_top) / view_height
                    width_ratio = (right - left) / view_width
                    height_ratio = (bottom - top) / view_height
                    if not (
                        0.0 <= center_x_ratio <= 1.0
                        and 0.0 <= center_y_ratio <= 0.12
                        and 0.12 <= width_ratio <= 0.30
                        and 0.015 <= height_ratio <= 0.10
                    ):
                        continue
                    if not self._is_control_exposed(
                        child,
                        owner=view,
                        allow_owner_surface=True,
                    ):
                        continue
                    try:
                        candidate_key = ("handle", int(child.handle))
                    except Exception:
                        candidate_key = ("object", id(child))
                    if candidate_key not in candidate_seen:
                        candidate_seen.add(candidate_key)
                        candidates.append(child)
                    continue
                if depth < 3:
                    queue.append((child, depth + 1))

        if len(candidates) != 4:
            return []
        ordered = sorted(
            candidates,
            key=lambda wrapper: int(wrapper.rectangle().left),
        )
        expected_centers = (0.125, 0.375, 0.625, 0.875)
        for button, expected_center in zip(ordered, expected_centers):
            bounds = self._wrapper_bounds(button)
            if bounds is None:
                return []
            center_ratio = ((bounds[0] + bounds[2]) / 2 - view_left) / view_width
            if abs(center_ratio - expected_center) > 0.14:
                return []
        return ordered

    def _strict_guide_step_button(
        self,
        selector_name: str,
        view: Any,
        *,
        x_range: tuple[float, float],
    ) -> Any | None:
        """校验原影刀旧版严格选择器命中的单个步骤按钮。"""

        if not self._is_page_exposed(view):
            return None
        try:
            button = self.controls.resolve_strict_fast(selector_name)
        except Exception:
            return None
        if (
            button is None
            or _wrapper_class_name(button).casefold() != "tguidebutton"
            or not self._wrapper_is_clickable(button)
        ):
            return None
        view_bounds = self._wrapper_bounds(view)
        button_bounds = self._wrapper_bounds(button)
        if view_bounds is None or button_bounds is None:
            return None
        view_left, view_top, view_right, view_bottom = view_bounds
        view_width = view_right - view_left
        view_height = view_bottom - view_top
        center_x_ratio = (
            (button_bounds[0] + button_bounds[2]) / 2 - view_left
        ) / view_width
        center_y_ratio = (
            (button_bounds[1] + button_bounds[3]) / 2 - view_top
        ) / view_height
        if not (
            x_range[0] <= center_x_ratio <= x_range[1]
            and 0.0 <= center_y_ratio <= 0.12
        ):
            return None
        if not self._is_control_exposed(
            button,
            owner=view,
            allow_owner_surface=True,
        ):
            return None
        return button

    def _report_step_button(self) -> tuple[Any | None, Any | None]:
        """在当前预扣预缴页内定位第 4 步“申报表报送”。"""

        view = self.controls.find_by_class(
            "Tfrm_YKYJView_Main",
            timeout=1,
            include_children=True,
        )
        if view is None or not self._is_page_exposed(view):
            return None, view
        buttons = self._guide_step_buttons(view)
        if buttons:
            return buttons[3], view
        return (
            self._strict_guide_step_button(
                "申送表报送",
                view,
                x_range=(0.70, 1.0),
            ),
            view,
        )

    def _click_report_step_once(self) -> None:
        """只用目标进程 Win32 控件或页面内相对坐标点击报送步骤。"""

        button, view = self._report_step_button()
        if button is not None:
            button.click_input()
            LOGGER.info("已点击最右侧 Win32“申报表报送”步骤按钮")
            return
        if view is None:
            raise AutomationError("未找到预扣预缴主界面，无法进入申报表报送")
        if not self._is_page_exposed(view):
            raise AutomationError("预扣预缴主界面不在前台，已停止坐标点击申报表报送")

        # 现场窗口树中第4步位于 Tfrm_YKYJView_Main 顶部最右侧：
        # x≈87.2%、y≈3.9%。坐标相对于页面窗体，兼容窗口移动与缩放。
        rectangle = view.rectangle()
        view.click_input(
            coords=(
                max(1, int(rectangle.width() * 0.872)),
                max(1, int(rectangle.height() * 0.039)),
            )
        )
        LOGGER.info("Win32 步骤按钮未暴露，已按页面相对位置点击“申报表报送”")

    def _tax_step_button(self) -> tuple[Any | None, Any | None]:
        """在预扣预缴主界面定位第 2 步“税款计算”按钮。"""

        view = self.controls.find_by_class(
            "Tfrm_YKYJView_Main",
            timeout=1,
            include_children=True,
        )
        if view is None:
            return None, None

        if not self._is_page_exposed(view):
            return None, view
        buttons = self._guide_step_buttons(view)
        if buttons:
            return buttons[1], view
        return (
            self._strict_guide_step_button(
                "税款计算",
                view,
                x_range=(0.18, 0.58),
            ),
            view,
        )

    def _click_tax_step_once(self) -> None:
        """直接点击 Win32 第 2 步；控件缺失时使用页面内固定比例。"""

        button, view = self._tax_step_button()
        if button is not None:
            button.click_input()
            LOGGER.info("已直接点击 Win32“税款计算”步骤按钮")
            return
        if view is None:
            raise AutomationError("未找到预扣预缴主界面，无法点击税款计算")
        if not self._is_page_exposed(view):
            raise AutomationError("预扣预缴主界面不在前台，已停止坐标点击税款计算")

        legacy_match = self._legacy_tax_step_match(view, timeout=0)
        if legacy_match is not None:
            self._click_verified_image_match(legacy_match)
            LOGGER.info("原生步骤按钮未暴露，已点击前台主界面内旧版“税款计算”模板")
            return

        # 现场窗口树：Main=(197,122)-(1918,1005)，税款计算按钮中心
        # 约为 (842,156)，即页面内 x=37.5%、y=3.9%。
        rectangle = view.rectangle()
        view.click_input(
            coords=(
                max(1, int(rectangle.width() * 0.375)),
                max(1, int(rectangle.height() * 0.039)),
            )
        )
        LOGGER.info("Win32 税款计算按钮未暴露，已按页面相对位置直接点击")

    def _open_report_page_and_read_state(
        self,
        *,
        allow_pending_fallback: bool = False,
        allow_send_button_pending: bool = False,
    ) -> str:
        LOGGER.info("进入“申报表报送”，查询当前申报状态")

        # VCL 会让已打开过的各步骤窗体同时保持 visible。无论后台是否还留有
        # Tfrm_YKYJReportDeclare，都必须实际点击第 4 步；否则算税完成后会把
        # 被遮住的旧报送页误当成当前页，并在税款页空等发送按钮。
        self.last_report_page = None
        self.last_report_bounds = None
        try:
            self._click_report_step_once()
        except Exception as exc:
            # click_input 可能在点击已经送达后才抛错，先观察前台页面；
            # 第 4 步导航是幂等的，5 秒后仍未切换再补点一次。
            LOGGER.warning("首次点击申报表报送步骤状态未知，继续等待：%s", exc)

        wait_seconds = min(max(self.settings.page_timeout, 8.0), 30.0)
        started_at = time.monotonic()
        deadline = started_at + wait_seconds
        next_progress_log = started_at + 5
        retry_at = started_at + 5
        retried = False
        report_page = None
        while time.monotonic() < deadline:
            candidate = self._report_page(timeout=0)
            # 成功模态窗会禁用底层报送页，WindowFromPoint 此时可能跳过该
            # disabled HWND。必须先识别成功状态/提示，再检查页面是否前台。
            if self._report_success_visible(candidate):
                LOGGER.info("进入报送页时已检测到申报成功，停止后续发送")
                return "success"
            if candidate is not None and self._is_page_exposed(candidate):
                report_page = candidate
                LOGGER.info("申报表报送页面已切换到前台")
                break

            now = time.monotonic()
            if not retried and now >= retry_at:
                LOGGER.warning("第 4 步尚未切换到前台，重新点击一次申报表报送")
                try:
                    self._click_report_step_once()
                except Exception as exc:
                    LOGGER.warning("补点申报表报送步骤未成功，继续等待：%s", exc)
                retried = True
            if now >= next_progress_log:
                LOGGER.info(
                    "正在等待申报表报送页面切换到前台，已等待 %d 秒……",
                    int(now - started_at),
                )
                next_progress_log = now + 5
            time.sleep(0.4)

        if report_page is None:
            diagnostic = self.capture_diagnostics("report_step_not_opened")
            suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
            raise AutomationError(
                f"点击“申报表报送”后 {wait_seconds:g} 秒内页面未切换到前台{suffix}"
            )
        self.last_report_page = report_page
        try:
            page_rectangle = report_page.rectangle()
            self.last_report_bounds = (
                int(page_rectangle.left),
                int(page_rectangle.top),
                int(page_rectangle.right),
                int(page_rectangle.bottom),
            )
        except Exception:
            # 状态函数仍会尝试使用 wrapper；这里只是不更新旧的有效矩形。
            pass
        state = self._wait_for_report_state(
            timeout=wait_seconds,
            report_page=report_page,
            allow_pending_fallback=allow_pending_fallback,
            allow_send_button_pending=allow_send_button_pending,
        )
        LOGGER.info("申报表报送状态：%s", "申报成功" if state == "success" else "待申报")
        return state

    def _progress_visible(self) -> bool:
        if self.controls.find_by_text_contains(
            ("正在下载累计数据", "正在处理", "请稍候"),
            timeout=0,
        ) is not None:
            return True
        if self.controls.find_by_text("进度", timeout=0) is not None:
            return True
        for class_name in (
            "Tfrm_Progress",
            "TfrmProgress",
            "Tfrm_ProgressInfo",
            "TfrmProgressInfo",
        ):
            if self.controls.find_by_class(
                class_name,
                timeout=0,
                include_children=True,
            ) is not None:
                return True
        return False

    def _click_expected_result_button(
        self,
        _selector_name: str,
        label: str,
        expected_fragments: Sequence[str],
        timeout: float,
        fallback_x_ratio: float = 0.77,
        fallback_bottom: int = 21,
        button_aliases: Sequence[str] = (),
    ) -> bool:
        """点击“结果”弹窗按钮，兼容无文字的 Delphi 自绘按钮。"""

        dialog = self.controls.find_by_class(
            "TfrmBase",
            timeout=timeout,
            include_children=True,
        )
        if dialog is None:
            return False
        text_value = self._dialog_text(dialog)
        content_text = self._dialog_content_text(text_value)
        if "申报成功" in text_value:
            return False
        if any(
            value in text_value
            for value in ("进度", "正在下载累计数据", "正在处理", "请稍候")
        ):
            # 某些版本没有确认提示，会直接进入计算/报送进度；这不是未知错误。
            return False
        if content_text and expected_fragments and not any(
            value in text_value for value in expected_fragments
        ):
            raise AutomationError(
                f"等待“{label}”时出现未知提示：{text_value[:160]}"
            )

        button_labels = tuple(dict.fromkeys((label, *button_aliases)))
        button = self.controls.find_by_text(button_labels, timeout=0)
        if button is not None:
            try:
                button.click_input()
            except Exception as exc:
                # click_input 有可能在消息已经送达后才抛错。继续走坐标兜底会
                # 再点一次“继续算税/继续申报”，甚至会误点弹窗关闭后的底层页面。
                # 因此一旦对目标文字按钮发起过点击，就只观察后续状态，不补点。
                LOGGER.warning(
                    "点击“%s”后的状态未知，为避免重复点击将继续观察页面：%s",
                    label,
                    exc,
                )
            time.sleep(0.8)
            return True

        if not content_text:
            # 现场“继续算税/继续申报”提示有两个无文字 TModalSpeedButton，
            # 左侧为继续、右侧为取消。正文未暴露时必须先确认这一完整结构，
            # 不能对任意 TfrmBase 直接按 77% 坐标盲点。
            try:
                dialog_rectangle = dialog.rectangle()
            except Exception:
                dialog_rectangle = None
            queue: list[tuple[Any, int]] = [(dialog, 0)]
            choice_buttons: list[Any] = []
            seen_handles: set[tuple[str, int]] = set()
            visited = 0
            while queue and visited < 80:
                current, depth = queue.pop(0)
                visited += 1
                try:
                    children = current.children()
                except Exception:
                    continue
                for child in children:
                    class_name = _wrapper_class_name(child).casefold()
                    if class_name in {"tmodalspeedbutton", "titsspeedbutton"}:
                        try:
                            rectangle = child.rectangle()
                            in_button_row = (
                                dialog_rectangle is not None
                                and rectangle.top
                                >= dialog_rectangle.top
                                + int(dialog_rectangle.height() * 0.55)
                                and rectangle.width() >= 35
                                and rectangle.height() >= 18
                            )
                            usable = (
                                bool(child.is_visible())
                                and bool(child.is_enabled())
                                and in_button_row
                            )
                        except Exception:
                            usable = False
                        if usable:
                            try:
                                identity = ("handle", int(child.handle))
                            except Exception:
                                identity = ("object", id(child))
                            if identity not in seen_handles:
                                seen_handles.add(identity)
                                choice_buttons.append(child)
                        continue
                    if depth < 5:
                        queue.append((child, depth + 1))

            if len(choice_buttons) != 2:
                raise AutomationError(
                    f"等待“{label}”时提示正文未暴露，且未识别到预期的双按钮结构"
                )

            def left_position(wrapper: Any) -> int:
                try:
                    return int(wrapper.rectangle().left)
                except Exception:
                    return 10**9

            continue_button = min(choice_buttons, key=left_position)
            try:
                continue_button.click_input()
            except Exception as exc:
                LOGGER.warning(
                    "点击无文字“%s”按钮后的状态未知，为避免重复点击将继续观察：%s",
                    label,
                    exc,
                )
            time.sleep(0.8)
            return True

        # 正文已经明确包含当前步骤的预期提示时，才允许在该结果窗内部使用
        # 相对位置兜底；不调用跨主窗体的递归 selector/descendants。
        if self._click_dialog_button(
            dialog,
            button_labels,
            fallback_x_ratio=fallback_x_ratio,
            fallback_bottom=fallback_bottom,
        ):
            return True
        raise AutomationError(f"无法点击提示中的“{label}”")

    def _tax_view_and_table(self) -> tuple[Any | None, Any | None]:
        """定位税款计算页及其内部数据表，避免误取其他页面的表格。"""

        tax_view = self.controls.find_by_class(
            "Tfrm_YKYJCalcTax",
            timeout=0,
            include_children=True,
        )
        if tax_view is None or not self._is_page_exposed(tax_view):
            return None, None

        # 原影刀选择器中，TVirtualStringTree 位于税款页面根节点下约 7 层。
        # 这里只遍历该页面的 Win32 children，并设置深度/数量上限，不扫描 UIA。
        queue: list[tuple[Any, int]] = [(tax_view, 0)]
        seen: set[tuple[str, int]] = set()
        visited = 0
        while queue and visited < 320:
            current, depth = queue.pop(0)
            try:
                identity = ("handle", int(current.handle))
            except Exception:
                identity = ("object", id(current))
            if identity in seen:
                continue
            seen.add(identity)
            visited += 1
            try:
                children = self._unique_native_wrappers(current.children())
            except Exception:
                continue
            for child in children:
                if _wrapper_class_name(child).casefold() == "tvirtualstringtree":
                    try:
                        rectangle = child.rectangle()
                        if (
                            child.is_visible()
                            and child.is_enabled()
                            and rectangle.width() > 0
                            and rectangle.height() > 0
                        ):
                            return tax_view, child
                    except Exception:
                        continue
                if depth < 10:
                    queue.append((child, depth + 1))
        return tax_view, None

    def _wait_for_tax_calculation_ready(self) -> None:
        """动态等待进度结束，并确认税款计算数据表真正出现。"""

        deadline = time.monotonic() + self.settings.page_timeout
        started_at = time.monotonic()
        next_progress_log = started_at + 5
        progress_seen = False
        ready_since: float | None = None
        while time.monotonic() < deadline:
            progress_visible = self._progress_visible()
            if progress_visible:
                progress_seen = True
                ready_since = None

            tax_view, tax_table = self._tax_view_and_table()
            if (
                not progress_visible
                and tax_view is not None
                and tax_table is not None
            ):
                now = time.monotonic()
                if ready_since is None:
                    ready_since = now
                elif now - ready_since >= 1.0:
                    LOGGER.info(
                        "税款计算完成%s，数据表已出现",
                        "（进度窗口已消失）" if progress_seen else "",
                    )
                    return
            else:
                ready_since = None

            now = time.monotonic()
            if now >= next_progress_log:
                LOGGER.info(
                    "正在等待税款计算%s，已等待 %d 秒……",
                    "进度完成" if progress_seen else "数据出现",
                    int(now - started_at),
                )
                next_progress_log = now + 5
            time.sleep(0.5)

        diagnostic = self.capture_diagnostics("tax_calculation_timeout")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        raise AutomationError(
            f"等待税款计算数据超时（{self.settings.page_timeout:g} 秒）{suffix}"
        )

    def _calculate_tax(self) -> None:
        LOGGER.info("状态为待申报，开始税款计算")
        try:
            self._click_tax_step_once()
        except Exception as exc:
            # click_input 可能在事件已经送达后才抛异常，先观察页面状态；
            # 未切换时下面会安全补点一次。
            LOGGER.warning("首次直接点击税款计算状态未知，继续验证：%s", exc)

        # 第 2 步页面出现只代表导航成功，不代表本次算税已经启动。旧版客户端
        # 可能先显示税款页及上一次的表格，随后才弹出“继续算税”。只有点击了
        # “继续算税/立即算税”，或明确看到计算进度，才允许等待本次计算完成。
        # 5 秒后仍未进入税款页时最多补点一次；页面已出现则禁止重复点击步骤。
        started_at = time.monotonic()
        effect_timeout = min(max(self.settings.page_timeout, 12.0), 25.0)
        deadline = started_at + effect_timeout
        retry_at = started_at + 5.0
        next_progress_log = retry_at
        retried_navigation = False
        calculation_started = False
        tax_page_seen = False

        while time.monotonic() < deadline:
            clicked_continue = self._click_expected_result_button(
                "继续算税",
                "继续算税",
                ("三险一金", "是否继续", "继续算税", "立即算税"),
                timeout=0,
                button_aliases=("立即算税",),
            )
            if clicked_continue:
                LOGGER.info("已选择“继续算税/立即算税”")
                calculation_started = True
                break

            if self._progress_visible():
                LOGGER.info("税款计算进度已出现，动态等待进度完成")
                calculation_started = True
                break

            tax_view, _ = self._tax_view_and_table()
            if tax_view is not None and not tax_page_seen:
                tax_page_seen = True
                LOGGER.info(
                    "税款计算页面已切换，继续等待“继续算税/立即算税”或计算进度"
                )

            now = time.monotonic()
            if now >= retry_at and not retried_navigation and not tax_page_seen:
                retried_navigation = True
                LOGGER.warning("首次点击后税款计算步骤未切换，直接补点一次")
                try:
                    self._click_tax_step_once()
                except Exception as exc:
                    LOGGER.warning("补点税款计算步骤状态未知，继续验证：%s", exc)

            if now >= next_progress_log:
                LOGGER.info(
                    "正在确认税款计算步骤是否切换，已等待 %d 秒……",
                    int(now - started_at),
                )
                next_progress_log = now + 5.0
            time.sleep(0.4)

        if not calculation_started:
            diagnostic = self.capture_diagnostics(
                "tax_calculation_not_started" if tax_page_seen else "tax_step_not_opened"
            )
            suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
            if tax_page_seen:
                raise AutomationError(
                    f"已进入税款计算页面，但 {effect_timeout:g} 秒内未出现"
                    "“继续算税/立即算税”确认或计算进度；为避免把旧表误当成"
                    f"本次算税结果，已停止进入申报{suffix}"
                )
            raise AutomationError(
                f"直接点击税款计算后 {effect_timeout:g} 秒内页面未切换{suffix}"
            )
        self._wait_for_tax_calculation_ready()

    @staticmethod
    def _wrapper_is_clickable(wrapper: Any) -> bool:
        try:
            return bool(wrapper.is_visible()) and bool(wrapper.is_enabled())
        except Exception:
            return False

    def _blue_button_fill_ratio(self, wrapper: Any) -> float:
        """返回控件矩形内 OTS 蓝色实心按钮像素占比。

        个税客户端的 ``TITSSpeedButton`` 是 Delphi 自绘控件，少数版本会在
        按钮已经呈蓝色可用时仍向 Win32 报告 ``enabled=False``。这里只读取
        已经定位到的按钮矩形，不在全屏猜测按钮位置；灰色禁用按钮占比接近 0。
        """

        try:
            rectangle = wrapper.rectangle()
            screen, origin_x, origin_y = _capture_screen_bgr(self.images.np)
            left = max(0, int(rectangle.left) - origin_x)
            top = max(0, int(rectangle.top) - origin_y)
            right = min(screen.shape[1], int(rectangle.right) - origin_x)
            bottom = min(screen.shape[0], int(rectangle.bottom) - origin_y)
        except Exception:
            return 0.0
        if right - left < 20 or bottom - top < 12:
            return 0.0
        crop = screen[top:bottom, left:right]
        if crop.size == 0:
            return 0.0
        try:
            hsv = self.images.cv2.cvtColor(crop, self.images.cv2.COLOR_BGR2HSV)
            hue = hsv[:, :, 0]
            saturation = hsv[:, :, 1]
            value = hsv[:, :, 2]
            blue = (
                (hue >= 95)
                & (hue <= 125)
                & (saturation >= 100)
                & (value >= 150)
            )
            return float(self.images.np.count_nonzero(blue)) / float(blue.size)
        except Exception:
            return 0.0

    @staticmethod
    def _bbox_iou(
        first: tuple[int, int, int, int],
        second: tuple[int, int, int, int],
    ) -> float:
        intersection_width = max(
            0,
            min(first[2], second[2]) - max(first[0], second[0]),
        )
        intersection_height = max(
            0,
            min(first[3], second[3]) - max(first[1], second[1]),
        )
        intersection = intersection_width * intersection_height
        first_area = max(0, first[2] - first[0]) * max(0, first[3] - first[1])
        second_area = max(0, second[2] - second[0]) * max(
            0, second[3] - second[1]
        )
        union = first_area + second_area - intersection
        return float(intersection) / float(union) if union > 0 else 0.0

    @classmethod
    def _same_visual_send_target(
        cls,
        first: VisualSendTarget | None,
        second: VisualSendTarget | None,
    ) -> bool:
        if first is None or second is None:
            return False
        if first.page_handle != second.page_handle:
            return False
        first_center = (
            (first.bbox[0] + first.bbox[2]) // 2,
            (first.bbox[1] + first.bbox[3]) // 2,
        )
        second_center = (
            (second.bbox[0] + second.bbox[2]) // 2,
            (second.bbox[1] + second.bbox[3]) // 2,
        )
        return bool(
            # 蓝色连通域边缘会随远程桌面压缩/抗锯齿产生 1～2 像素抖动；
            # 成功页已由“候选必须唯一”硬性排除，因此 0.85 足以容错且不会
            # 把成功页最右侧“更正申报”单独放行。
            cls._bbox_iou(first.bbox, second.bbox) >= 0.85
            and abs(first_center[0] - second_center[0]) <= 4
            and abs(first_center[1] - second_center[1]) <= 4
        )

    def _visual_report_send_target(
        self,
        report_page: Any | None,
        *,
        explicit_pending: bool,
    ) -> VisualSendTarget | None:
        """在当前报送页右上区域识别唯一的蓝色“发送申报”按钮。

        新版客户端可能只绘制按钮而不向 Win32 暴露可用子控件。这里不使用
        固定坐标：候选必须位于已确认前台的报送页内，并且右上操作区只能有
        一个尺寸合理的蓝色实心按钮。成功页会显示反馈、作废、更正等三个蓝色
        按钮，因此会因候选不唯一而被拒绝。
        """

        self.last_visual_send_note = "前置状态未满足"
        if (
            not explicit_pending
            or report_page is None
            or not self._is_page_exposed(report_page)
        ):
            return None
        if self._report_success_visible(report_page) or self._report_interaction_blocked():
            return None
        try:
            page_handle = int(report_page.handle)
            rectangle = report_page.rectangle()
            page_left = int(rectangle.left)
            page_top = int(rectangle.top)
            page_right = int(rectangle.right)
            page_bottom = int(rectangle.bottom)
            page_width = page_right - page_left
            page_height = page_bottom - page_top
        except Exception:
            self.last_visual_send_note = "无法读取报送页窗口范围"
            return None
        if page_handle <= 0 or page_width < 500 or page_height < 250:
            self.last_visual_send_note = "报送页窗口范围异常"
            return None

        try:
            screen, origin_x, origin_y = _capture_screen_bgr(self.images.np)
        except Exception:
            self.last_visual_send_note = "GDI 截图失败"
            return None

        # ROI 必须从页面宽度 70% 开始，以完整包含成功页的三个操作按钮；
        # 先统计全部合格候选，再检查唯一候选是否位于最右 10%，不能提前裁掉
        # 左侧按钮，否则成功页可能只剩“更正申报”并被误认为发送按钮。
        roi_left = max(page_left + int(page_width * 0.70), origin_x)
        roi_top = max(page_top, origin_y)
        roi_right = min(page_right, origin_x + int(screen.shape[1]))
        roi_bottom = min(
            page_top + int(page_height * 0.20),
            page_bottom,
            origin_y + int(screen.shape[0]),
        )
        crop_left = roi_left - origin_x
        crop_top = roi_top - origin_y
        crop_right = roi_right - origin_x
        crop_bottom = roi_bottom - origin_y
        if crop_right - crop_left < 150 or crop_bottom - crop_top < 50:
            self.last_visual_send_note = "报送页右上视觉区域过小"
            return None

        crop = screen[crop_top:crop_bottom, crop_left:crop_right]
        try:
            hsv = self.images.cv2.cvtColor(crop, self.images.cv2.COLOR_BGR2HSV)
            hue = hsv[:, :, 0]
            saturation = hsv[:, :, 1]
            value = hsv[:, :, 2]
            mask = (
                (hue >= 95)
                & (hue <= 125)
                & (saturation >= 100)
                & (value >= 150)
            ).astype(self.images.np.uint8)
            component_count, _, stats, _ = (
                self.images.cv2.connectedComponentsWithStats(mask, 8)
            )
        except Exception:
            self.last_visual_send_note = "蓝色按钮连通域分析失败"
            return None

        minimum_width = max(45, int(page_width * 0.025))
        maximum_width = max(minimum_width + 1, int(page_width * 0.12))
        minimum_height = max(20, int(page_height * 0.018))
        maximum_height = max(minimum_height + 1, int(page_height * 0.09))
        candidates: list[VisualSendTarget] = []
        cv2 = self.images.cv2
        for index in range(1, int(component_count)):
            x = int(stats[index, cv2.CC_STAT_LEFT])
            y = int(stats[index, cv2.CC_STAT_TOP])
            width = int(stats[index, cv2.CC_STAT_WIDTH])
            height = int(stats[index, cv2.CC_STAT_HEIGHT])
            area = int(stats[index, cv2.CC_STAT_AREA])
            if (
                width < minimum_width
                or width > maximum_width
                or height < minimum_height
                or height > maximum_height
            ):
                continue
            aspect_ratio = float(width) / float(height)
            blue_ratio = float(area) / float(width * height)
            if not 1.7 <= aspect_ratio <= 6.0 or blue_ratio < 0.60:
                continue
            left = int(roi_left + x)
            top = int(roi_top + y)
            candidates.append(
                VisualSendTarget(
                    page_handle=page_handle,
                    bbox=(left, top, left + width, top + height),
                    blue_ratio=blue_ratio,
                )
            )

        self.last_visual_send_note = f"合格蓝色候选数={len(candidates)}"
        if len(candidates) != 1:
            if len(candidates) >= 2:
                LOGGER.debug(
                    "报送页右上区域识别到 %d 个蓝色操作按钮，拒绝视觉发送定位",
                    len(candidates),
                )
            return None

        target = candidates[0]
        center_x = (target.bbox[0] + target.bbox[2]) // 2
        center_y = (target.bbox[1] + target.bbox[3]) // 2
        if (
            center_x < page_left + int(page_width * 0.90)
            or target.bbox[2] < page_right - int(page_width * 0.08)
        ):
            self.last_visual_send_note = "唯一蓝色候选不在页面最右侧"
            return None

        # 遮挡窗口不能借用底层蓝色像素授权发送。视觉中心必须实际命中当前
        # 报送页或其子控件；多显示器负坐标直接使用 GDI 返回的绝对坐标。
        try:
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            user32.WindowFromPoint.argtypes = [wintypes.POINT]
            user32.WindowFromPoint.restype = wintypes.HWND
            user32.IsChild.argtypes = [wintypes.HWND, wintypes.HWND]
            user32.IsChild.restype = wintypes.BOOL
            hit_handle = int(
                user32.WindowFromPoint(wintypes.POINT(center_x, center_y)) or 0
            )
            hit_in_page = bool(
                hit_handle == page_handle or user32.IsChild(page_handle, hit_handle)
            )
        except Exception:
            self.last_visual_send_note = "无法验证视觉按钮中心所属窗口"
            return None
        if hit_handle <= 0 or not hit_in_page:
            self.last_visual_send_note = "视觉按钮中心被报送页之外的窗口遮挡"
            return None
        self.last_visual_send_note = (
            f"唯一蓝色候选={target.bbox}，蓝色占比={target.blue_ratio:.3f}"
        )
        return target

    def _report_send_button_ready(
        self,
        button: Any | None,
        *,
        explicit_pending: bool,
    ) -> tuple[bool, bool, float]:
        """返回 ``(可发送, 需鼠标点击, 蓝色占比)``。"""

        if button is None:
            return False, False, 0.0
        if self._wrapper_is_clickable(button):
            return True, False, 0.0
        try:
            visible = bool(button.is_visible())
        except Exception:
            visible = False
        if not explicit_pending or not visible:
            return False, False, 0.0
        blue_ratio = self._blue_button_fill_ratio(button)
        if blue_ratio >= 0.60:
            return True, True, blue_ratio
        return False, False, blue_ratio

    def _report_send_button_from_embedded_path(
        self,
        report_page: Any,
        page_rectangle: Any,
        top_limit: int,
    ) -> tuple[Any | None, int]:
        """从当前报送页沿影刀原始层级有界定位“发送申报”。

        通用选择器会在层级不匹配时扫描 descendants/UIA，可能长时间阻塞；
        此处已经拿到当前前台 ``Tfrm_YKYJReportDeclare``，只逐层读取直接
        children。返回按钮及其直接工具栏内同类按钮数，供成功页防误点校验。
        """

        spec = self.repository.selectors.get("发送申送")
        if spec is None:
            return None, 0
        anchor_index = next(
            (
                index
                for index, step in enumerate(spec.steps)
                if (step.class_name or "").casefold()
                == "tfrm_ykyjreportdeclare"
            ),
            -1,
        )
        if anchor_index < 0:
            return None, 0
        anchor = spec.steps[anchor_index]
        if not _matches_step(report_page, anchor, ignore_exact_title=True):
            return None, 0

        current = report_page
        for step in spec.steps[anchor_index + 1 : -1]:
            try:
                children = self._unique_native_wrappers(current.children())
            except Exception:
                return None, 0
            matches = [child for child in children if _matches_step(child, step)]
            if not matches and step.title and step.class_name:
                matches = [
                    child
                    for child in children
                    if _matches_step(child, step, ignore_exact_title=True)
                ]
            if not matches:
                return None, 0
            if step.index is not None:
                if step.index < 0 or step.index >= len(matches):
                    return None, 0
                current = matches[step.index]
            elif len(matches) == 1:
                current = matches[0]
            else:
                return None, 0

        final_step = spec.steps[-1]
        try:
            final_children = self._unique_native_wrappers(current.children())
        except Exception:
            return None, 0
        final_matches = self._unique_native_wrappers(
            child for child in final_children if _matches_step(child, final_step)
        )
        if not final_matches and final_step.title and final_step.class_name:
            final_matches = self._unique_native_wrappers(
                child
                for child in final_children
                if _matches_step(child, final_step, ignore_exact_title=True)
            )
        if not final_matches:
            return None, 0
        if final_step.index is not None:
            if final_step.index < 0 or final_step.index >= len(final_matches):
                return None, 0
            button = final_matches[final_step.index]
        elif len(final_matches) == 1:
            button = final_matches[0]
        else:
            return None, 0

        # 只统计按钮直接父工具栏中的同类可见按钮。旧版待申报页通常是
        # 导出+发送两个；新版可能只把“发送”暴露为 speed button。成功页
        # 通常有反馈+作废+更正三个。严格路径命中的按钮还必须是该组最右侧，
        # 避免把成功页中的“获取反馈”误当发送。
        visible_siblings: list[tuple[int, Any]] = []
        for child in final_children:
            if _wrapper_class_name(child).casefold() != "titsspeedbutton":
                continue
            try:
                rectangle = child.rectangle()
                visible = bool(child.is_visible())
                in_toolbar = (
                    rectangle.width() >= 45
                    and rectangle.height() >= 20
                    and rectangle.left >= page_rectangle.left
                    and rectangle.right <= page_rectangle.right
                    and rectangle.top >= page_rectangle.top
                    and rectangle.bottom <= top_limit
                )
            except Exception:
                visible = False
                in_toolbar = False
            if visible and in_toolbar:
                visible_siblings.append((int(rectangle.left), child))
        if not visible_siblings:
            return None, 0
        rightmost = max(visible_siblings, key=lambda item: item[0])[1]
        try:
            same_button = int(rightmost.handle) == int(button.handle)
            button_rectangle = button.rectangle()
            center_x = int(button_rectangle.left + button_rectangle.width() // 2)
            center_y = int(button_rectangle.top + button_rectangle.height() // 2)
            in_right_toolbar = bool(
                center_x >= page_rectangle.left + int(page_rectangle.width() * 0.70)
                and center_x <= page_rectangle.right
                and center_y >= page_rectangle.top
                and center_y <= top_limit
            )
        except Exception:
            return None, len(visible_siblings)
        if (
            not same_button
            or not in_right_toolbar
            or not self._is_control_exposed(
                button,
                current,
                allow_owner_surface=True,
            )
        ):
            return None, len(visible_siblings)
        return button, len(visible_siblings)

    def _native_report_send_button(
        self,
        report_page: Any | None = None,
        *,
        explicit_pending: bool = False,
    ) -> Any | None:
        """在报送页内有界查找顶部最右侧的“发送申报”按钮。"""

        if report_page is None:
            report_page = self._report_page(timeout=0)
        if report_page is None or not self._is_page_exposed(report_page):
            return None
        try:
            page_rectangle = report_page.rectangle()
            top_limit = page_rectangle.top + int(page_rectangle.height() * 0.25)
        except Exception:
            return None

        # 优先使用影刀原流程中已经验证过的精确层级。若直接父工具栏正好有
        # 两个按钮，它本身即可作为待申报结构证据；若客户端把“导出”拆成
        # 其他控件，则仅在页面已有明确待申报证据时接受该精确发送按钮。
        selector_button, sibling_count = self._report_send_button_from_embedded_path(
            report_page,
            page_rectangle,
            top_limit,
        )
        if selector_button is not None and (
            sibling_count == 2
            or (explicit_pending and sibling_count == 1)
        ):
            return selector_button
        if selector_button is not None:
            LOGGER.debug(
                "精确发送按钮已定位，但同工具栏识别到 %d 个按钮且无明确待申报证据",
                sibling_count,
            )

        queue: list[tuple[Any, int]] = [(report_page, 0)]
        candidates: list[tuple[int, Any, Any]] = []
        queue_seen: set[tuple[str, int]] = set()
        candidate_seen: set[tuple[str, int]] = set()
        visited = 0
        while queue and visited < 240:
            current, depth = queue.pop(0)
            try:
                current_identity = ("handle", int(current.handle))
            except Exception:
                current_identity = ("object", id(current))
            if current_identity in queue_seen:
                continue
            queue_seen.add(current_identity)
            visited += 1
            try:
                children = self._unique_native_wrappers(current.children())
            except Exception:
                continue
            for child in children:
                if _wrapper_class_name(child).casefold() == "titsspeedbutton":
                    try:
                        rectangle = child.rectangle()
                        visible = bool(child.is_visible())
                        in_toolbar = (
                            rectangle.width() >= 45
                            and rectangle.height() >= 20
                            and rectangle.left >= page_rectangle.left
                            and rectangle.right <= page_rectangle.right
                            and rectangle.top >= page_rectangle.top
                            and rectangle.bottom <= top_limit
                        )
                    except Exception:
                        visible = False
                        in_toolbar = False
                    if visible and in_toolbar:
                        # 不先过滤 enabled：右侧发送按钮未启用时必须继续等待，
                        # 不能退而误选左侧仍可用的“导出申报表”。
                        try:
                            candidate_identity = ("handle", int(child.handle))
                        except Exception:
                            candidate_identity = ("object", id(child))
                        if candidate_identity not in candidate_seen:
                            candidate_seen.add(candidate_identity)
                            candidates.append((int(rectangle.left), child, current))
                    continue
                if depth < 10:
                    queue.append((child, depth + 1))

        if not candidates:
            return None

        # 不同客户端会把“导出申报表”的下拉区域暴露成 TPopControl，因此
        # 同一工具栏可能只有 1 个 TITSSpeedButton（即发送按钮），也可能是
        # 导出+发送 2 个。按直接父工具栏分组，避免页面其他区域的按钮干扰。
        groups: dict[tuple[str, int], list[tuple[int, Any, Any]]] = {}
        for item in candidates:
            parent = item[2]
            try:
                parent_identity = ("handle", int(parent.handle))
            except Exception:
                parent_identity = ("object", id(parent))
            groups.setdefault(parent_identity, []).append(item)

        page_width = page_rectangle.width()
        right_threshold = page_rectangle.left + int(page_width * 0.80)
        right_groups: list[list[tuple[int, Any, Any]]] = []
        for group in groups.values():
            try:
                rightmost_rectangle = max(group, key=lambda item: item[0])[1].rectangle()
                rightmost_center = int(
                    rightmost_rectangle.left + rightmost_rectangle.width() // 2
                )
            except Exception:
                continue
            if rightmost_center >= right_threshold:
                right_groups.append(group)

        # 成功页是“获取反馈/作废申报/更正申报”3 个蓝色 speed button。
        # 即使状态模板发生误报，只要看到同组 >=3 个就必须停止，绝不把
        # 最右侧“更正申报”当作发送按钮。
        if any(len(group) >= 3 for group in right_groups):
            LOGGER.debug("报送页右上工具栏存在至少 3 个操作按钮，拒绝推断发送")
            return None

        eligible_groups = [
            group
            for group in right_groups
            if len(group) == 2 or (explicit_pending and len(group) == 1)
        ]
        if len(eligible_groups) != 1:
            LOGGER.debug(
                "报送页识别到 %d 个可用右上工具栏分组，不推断发送申报",
                len(eligible_groups),
            )
            return None

        # 使用枚举时已经读取成功的坐标，不能在不可逆操作前再次读取失效的
        # wrapper 并用 -1 继续排序，否则可能把左侧“导出申报表”当成发送按钮。
        selected_group = eligible_groups[0]
        _, button, toolbar = max(selected_group, key=lambda item: item[0])
        if not self._is_control_exposed(
            button,
            toolbar,
            allow_owner_surface=True,
        ):
            return None
        return button

    def _wait_for_send_button(self) -> Any:
        """等待报送页的“发送申报”真正启用，而不只是存在。"""

        self.last_send_page_handle = None
        self.last_send_button_handle = None
        self.last_send_requires_mouse_click = False
        self.last_send_visual_target = None
        self.last_visual_send_note = "尚未执行视觉定位"
        wait_seconds = min(max(self.settings.page_timeout, 8.0), 30.0)
        started_at = time.monotonic()
        deadline = started_at + wait_seconds
        next_progress_log = started_at + 5
        retry_at = started_at + 5
        retried_navigation = False
        confirmed_identity: tuple[int, int] | None = None
        confirmed_count = 0
        confirmed_visual: VisualSendTarget | None = None
        confirmed_visual_count = 0
        report_page = self.last_report_page
        while time.monotonic() < deadline:
            candidate = self._report_page(timeout=0)
            if candidate is not None and self._is_page_exposed(candidate):
                report_page = candidate
                self.last_report_page = candidate
            else:
                report_page = None

            if self._report_success_visible(report_page):
                return None

            # 进度条或任意非成功模态窗存在时，页面按钮即使仍报告 enabled 也
            # 不能作为发送授权；等待遮挡消失后重新连续确认两轮。
            if self._report_interaction_blocked():
                confirmed_identity = None
                confirmed_count = 0
                confirmed_visual = None
                confirmed_visual_count = 0
                time.sleep(0.5)
                continue

            # 发送属于不可逆操作。严格的右上工具栏结构和按钮启用状态只用于
            # 定位与验证；必须同时有本轮明确“待申报”文字/图片证据才允许发送。
            # 8 秒 unknown->pending 兜底只用于进入算税，不能作为发送授权。
            explicitly_pending = self._report_pending_visible(report_page)
            # 仅在当前前台报送页子树内找按钮，不使用全进程同名文字。
            button = self._native_report_send_button(
                report_page,
                explicit_pending=explicitly_pending,
            )
            toolbar_pending, requires_mouse_click, blue_ratio = (
                self._report_send_button_ready(
                    button,
                    explicit_pending=explicitly_pending,
                )
            )
            # 发送是不可逆操作：按钮结构/启用状态只证明“可以点”，不能证明
            # “应该点”。必须同时有本轮明确的待申报文字或状态图片证据。
            if explicitly_pending and toolbar_pending:
                try:
                    identity = (
                        int(report_page.handle),
                        int(button.handle),
                    )
                except Exception:
                    identity = (0, 0)
                if identity[0] <= 0 or identity[1] <= 0:
                    confirmed_identity = None
                    confirmed_count = 0
                elif identity == confirmed_identity:
                    confirmed_count += 1
                else:
                    confirmed_identity = identity
                    confirmed_count = 1
                if confirmed_count >= 2:
                    self.last_send_page_handle = identity[0]
                    self.last_send_button_handle = identity[1]
                    self.last_send_requires_mouse_click = requires_mouse_click
                    if requires_mouse_click:
                        LOGGER.info(
                            "已连续确认待申报状态，发送按钮呈蓝色可用"
                            "（Win32 enabled 状态不可靠，蓝色占比 %.3f）",
                            blue_ratio,
                        )
                    else:
                        LOGGER.info("已连续确认待申报状态，“发送申报”按钮已启用")
                    return button
            else:
                confirmed_identity = None
                confirmed_count = 0

            # 某些新版客户端完全不向 Win32 暴露蓝色发送按钮。只有本轮仍有
            # 明确待申报证据、没有成功/弹窗/进度，且报送页右上区域恰好一个
            # 蓝色实心小按钮时，才进入视觉目标连续确认。成功页的 3 个按钮
            # 会因候选不唯一被拒绝。
            visual_target = None
            if explicitly_pending and not toolbar_pending:
                visual_target = self._visual_report_send_target(
                    report_page,
                    explicit_pending=True,
                )
                if visual_target is not None:
                    # 视觉定位完成后再次读取业务状态，防止页面在两次截图之间
                    # 从待申报切换为成功或出现遮挡。
                    if self._report_success_visible(report_page):
                        return None
                    if self._report_interaction_blocked() or not self._report_pending_visible(
                        report_page
                    ):
                        visual_target = None
            if visual_target is not None:
                if self._same_visual_send_target(confirmed_visual, visual_target):
                    confirmed_visual_count += 1
                else:
                    confirmed_visual = visual_target
                    confirmed_visual_count = 1
                if confirmed_visual_count >= 3:
                    self.last_send_page_handle = visual_target.page_handle
                    self.last_send_button_handle = None
                    self.last_send_requires_mouse_click = True
                    self.last_send_visual_target = visual_target
                    LOGGER.info(
                        "已连续 3 帧确认待申报状态及右上唯一蓝色“发送申报”按钮"
                        "（蓝色占比 %.3f）",
                        visual_target.blue_ratio,
                    )
                    return visual_target
            else:
                confirmed_visual = None
                confirmed_visual_count = 0

            now = time.monotonic()
            if not retried_navigation and now >= retry_at:
                retried_navigation = True
                LOGGER.warning(
                    "发送按钮尚未可用，重新点击一次第 4 步“申报表报送”并继续验证"
                )
                try:
                    self._click_report_step_once()
                except Exception as exc:
                    LOGGER.warning("补点第 4 步状态未知，继续观察：%s", exc)
            if now >= next_progress_log:
                LOGGER.info(
                    "正在确认前台报送页及“发送申报”按钮，已等待 %d 秒；"
                    "视觉定位：%s……",
                    int(now - started_at),
                    self.last_visual_send_note,
                )
                next_progress_log = now + 5
            time.sleep(0.5)

        diagnostic = self.capture_diagnostics("send_button_timeout")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        raise AutomationError(
            f"前台报送页或“发送申报”按钮在 {wait_seconds:g} 秒内未就绪{suffix}"
        )

    def _click_immediate_feedback(self, feedback_window: Any) -> None:
        # 只在已经确认的反馈窗口内部有界查找，避免误拿到主界面或其他
        # 后台窗体里同名的“立即获取”。这里不使用 descendants/UIA 全树扫描。
        button = None
        queue: list[tuple[Any, int]] = [(feedback_window, 0)]
        seen: set[tuple[str, int]] = set()
        visited = 0
        while queue and visited < 80:
            current, depth = queue.pop(0)
            try:
                identity = ("handle", int(current.handle))
            except Exception:
                identity = ("object", id(current))
            if identity in seen:
                continue
            seen.add(identity)
            visited += 1
            try:
                children = self._unique_native_wrappers(current.children())
            except Exception:
                continue
            for child in children:
                if re.sub(r"\s+", "", _wrapper_text(child)) == "立即获取":
                    if self._wrapper_is_clickable(child):
                        button = child
                        break
                if depth < 6:
                    queue.append((child, depth + 1))
            if button is not None:
                break
        if button is not None:
            try:
                button.click_input()
            except Exception as exc:
                # click_input 可能在消息已经送达后才抛异常。此处不能再按坐标
                # 补点，否则反馈窗已关闭时会误点到底层报送页。
                LOGGER.warning(
                    "“立即获取”点击接口返回异常，按点击已尝试处理并继续观察结果：%s",
                    exc,
                )
            time.sleep(0.8)
            return
        # feedback_window 已严格限定为 Tfrm_FeedbackWaiting；无文字按钮直接
        # 在该窗口内部点击，不再运行多层 selector/descendants。
        if not self._click_dialog_button(
            feedback_window,
            ("立即获取",),
            fallback_x_ratio=0.386,
            fallback_bottom=37,
        ):
            raise AutomationError("无法点击申报反馈窗口中的“立即获取”")

    def _wait_for_submission_result(self) -> tuple[str, str]:
        """动态等待发送/反馈进度并获取最终申报结果。"""

        deadline = time.monotonic() + self.settings.page_timeout
        started_at = time.monotonic()
        next_progress_log = started_at + 5
        clicked_refresh = False
        progress_seen = False
        while time.monotonic() < deadline:
            if self._report_success_visible():
                return "申报成功", "网页已显示“申报成功，无需缴款”，已记录且不会重复发送"

            # 发送或获取反馈期间出现进度窗口时，明确暂停所有后续点击，
            # 动态等它消失后再继续识别反馈窗口和最终结果。
            if self._progress_visible():
                if not progress_seen:
                    LOGGER.info("申报处理中，等待进度窗口动态消失")
                    progress_seen = True
                time.sleep(0.5)
                continue

            feedback_window = self.controls.find_by_class(
                "Tfrm_FeedbackWaiting",
                timeout=0,
                include_children=True,
            )
            if feedback_window is not None and not clicked_refresh:
                LOGGER.info("申报已发送，立即获取申报结果")
                self._click_immediate_feedback(feedback_window)
                clicked_refresh = True
                continue

            result_dialog = self.controls.find_by_class(
                "TfrmBase", timeout=0, include_children=True
            )
            if result_dialog is None:
                result_dialog = self.controls.find_by_class(
                    "Tfrm_MsgDlgRich", timeout=0, include_children=True
                )
            if result_dialog is not None:
                text_value = self._dialog_text(result_dialog)
                if "申报成功" in text_value:
                    if self._confirm_submission_result_dialog(result_dialog):
                        continue
                if (self.submission_started
                        and self._is_duplicate_period_feedback(text_value)):
                    if not self._confirm_submission_result_dialog(result_dialog):
                        raise AutomationError("已收到当前所属期已申报反馈，但无法安全关闭提示；不重复申报")
                    LOGGER.info("收到当前所属期已申报反馈，关闭提示后导出申报记录，不重复申报")
                    return "已经申报过了", "税局反馈当前税款所属期已申报、请勿重复申报；未再次发送"
                if text_value and any(
                    value in text_value
                    for value in ("申报失败", "申报反馈信息如下", "错误", "失败原因")
                ):
                    raise AutomationError(text_value[:500])

            # 兼容原影刀反馈错误控件；只有结果窗出现时才走深层选择器，
            # 避免正常轮询反复扫描整棵控件树。
            if result_dialog is not None:
                error_text = self.controls.read_text("错误信息", timeout=0).strip()
                if error_text:
                    if (self.submission_started
                            and self._is_duplicate_period_feedback(error_text)):
                        if not self._confirm_submission_result_dialog(result_dialog):
                            raise AutomationError("已收到当前所属期已申报反馈，但无法安全关闭提示；不重复申报")
                        LOGGER.info("收到当前所属期已申报反馈，关闭提示后导出申报记录，不重复申报")
                        return "已经申报过了", "税局反馈当前税款所属期已申报、请勿重复申报；未再次发送"
                    raise AutomationError(error_text)
                if (
                    getattr(self, "submission_started", False)
                    and (clicked_refresh or progress_seen)
                    and not self._dialog_content_text(text_value)
                    and self._result_dialog_confirm_button(result_dialog) is not None
                ):
                    # 已发送且手动获取反馈/观察到处理进度后，自动获取反馈的
                    # 旧版自绘正文可能仅暴露 pnl_body。
                    # 唯一确认按钮仅用于关闭该结果窗；空正文绝不等于成功。
                    LOGGER.info("反馈结果正文未暴露，确认当前结果窗后核验报送页状态")
                    if self._confirm_submission_result_dialog(result_dialog):
                        continue

            now = time.monotonic()
            if now >= next_progress_log:
                LOGGER.info(
                    "正在等待申报结果%s，已等待 %d 秒……",
                    "（反馈已获取）" if clicked_refresh else "",
                    int(now - started_at),
                )
                next_progress_log = now + 5
            time.sleep(0.5)

        diagnostic = self.capture_diagnostics("submission_result_timeout")
        suffix = f"；诊断已保存到 {diagnostic}" if diagnostic else ""
        raise AutomationError(
            f"等待申报反馈超时（{self.settings.page_timeout:g} 秒），"
            f"未识别到成功或错误结果{suffix}"
        )

    def _continue_after_submission_click(self) -> tuple[str, str]:
        """发送按钮只点击一次，随后处理继续申报并等待最终结果。"""

        time.sleep(0.8)
        if self._click_expected_result_button(
            "继续申报",
            "继续申报",
            ("三险一金", "是否继续", "继续申报"),
            timeout=10,
        ):
            LOGGER.info("已选择“继续申报”")
        return self._wait_for_submission_result()

    def _submit_verified_visual_target(
        self,
        expected: VisualSendTarget,
        timeout: float = 5.0,
    ) -> tuple[str, str]:
        """容错复核三帧授权的视觉按钮，并在有效帧后立即点击。

        Delphi 会把已被覆盖的税款页继续标记为 visible，并且它的右上按钮
        与报送页“发送申报”几乎完全重叠。三帧已经确认待申报与唯一蓝色
        按钮后，不能再用一次性的页面/WindowFromPoint 结果立即否决；这里在
        很短的有界窗口内重试，只接受同一报送页 HWND、明确待申报、无成功
        状态/模态框/进度以及同一视觉矩形。命中后直接点击该最新矩形中心。
        """

        stored = self.last_send_visual_target
        if (
            stored is None
            or self.last_send_page_handle != expected.page_handle
            or not self._same_visual_send_target(stored, expected)
        ):
            raise AutomationError("视觉发送授权记录不一致，已停止发送")

        deadline = time.monotonic() + max(timeout, 0.5)
        last_reason = "尚未取得最终有效帧"
        while time.monotonic() < deadline:
            report_page = self._report_page(timeout=0)
            if report_page is None:
                last_reason = "暂时未取得报送页窗口"
                time.sleep(0.2)
                continue
            try:
                page_handle = int(report_page.handle)
            except Exception:
                page_handle = 0
            if page_handle != expected.page_handle:
                last_reason = "报送页句柄与三帧授权记录不一致"
                time.sleep(0.2)
                continue
            if not self._is_page_exposed(report_page):
                last_reason = "报送页前台探针发生瞬时抖动"
                time.sleep(0.2)
                continue
            if self._report_success_visible(report_page):
                return "申报成功", "最终点击前检测到网页已申报成功，未重复发送"
            if self._report_interaction_blocked():
                last_reason = "报送页存在进度窗口或模态提示"
                time.sleep(0.2)
                continue
            if not self._report_pending_visible(report_page):
                last_reason = "本帧未识别到明确的待申报状态"
                time.sleep(0.2)
                continue

            current = self._visual_report_send_target(
                report_page,
                explicit_pending=True,
            )
            if not self._same_visual_send_target(expected, current):
                last_reason = self.last_visual_send_note
                time.sleep(0.2)
                continue
            assert current is not None

            if self.settings.dry_run:
                return "演练完成", "待申报且“发送申报”已启用，--dry-run 未发送"

            coordinates = (
                (current.bbox[0] + current.bbox[2]) // 2,
                (current.bbox[1] + current.bbox[3]) // 2,
            )
            # PyAutoGUI 开启了 FAILSAFE。若鼠标恰好停在屏幕角落，直接调用
            # click(x, y) 会在移动前抛出 FailSafeException，实际没有发送，
            # 但若已设置 submission_started，外层会误认为提交状态未知并禁止
            # 重试。先只移动鼠标；移动失败时可以明确保证尚未点击。
            try:
                self.pyautogui.moveTo(*coordinates, duration=0.10)
            except Exception as exc:
                raise AutomationError(
                    "发送按钮已确认，但鼠标无法移动到按钮；尚未点击发送申报"
                ) from exc
            # 从这里开始禁止自动重试；有效帧确认后不再插入会产生单帧
            # 假阴性的额外页面查询，立即点击刚刚识别到的矩形中心。
            self.submission_started = True
            LOGGER.info(
                "点击“发送申报”（最终视觉复核通过，蓝色占比 %.3f；"
                "从此处起禁止自动重试）",
                current.blue_ratio,
            )
            # 仍携带目标坐标，避免 moveTo 与 click 之间鼠标被非角落事件轻微
            # 移动后点击到其他位置；预定位已经先完成了 FAILSAFE 检查。
            self.pyautogui.click(*coordinates)
            return self._continue_after_submission_click()

        raise AutomationError(
            f"三帧确认发送按钮后，最终视觉复核在 {timeout:g} 秒内未稳定："
            f"{last_reason}；已停止发送"
        )

    def declare(self) -> tuple[str, str]:
        self._close_optional_dialogs()
        self._dismiss_registration_reminder(timeout=2)
        self._open_comprehensive_income_declaration()

        self._wait_for_income_type_ready()
        self._dismiss_zero_income_tip(timeout=0)
        self._click_normal_salary_entry(timeout=8)
        # 页面跳转前仍可能出现一个晚到提示；关闭后重新点击一次入口。
        time.sleep(1)
        if self._dismiss_zero_income_tip(timeout=0):
            LOGGER.info("关闭晚到的连续零收入提示，重新进入正常工资薪金所得")
            self._click_normal_salary_entry(timeout=8)
        time.sleep(2)

        if self._handle_already_declared(timeout=5):
            return "申报成功", "检测到“本月数据已经申报，不能修改明细数据”提示"

        import_prompt_confirmed = self._confirm_salary_import_prompt(timeout=8)
        if not import_prompt_confirmed:
            # 续跑时零工资明细可能已由上次运行生成，因此不会再次出现导入向导。
            # 先补查一次“已经申报”提示；若没有，则保留现有明细并直接查询报送状态。
            if self._handle_already_declared(timeout=1):
                return "申报成功", "检测到“本月数据已经申报，不能修改明细数据”提示"
            LOGGER.info("未出现自动导入向导，按工资明细已存在处理并查询申报状态")
        elif not self._generate_zero_salary_record(timeout=15):
            raise AutomationError(
                "自动导入向导已打开，但未识别到“生成零工资记录”选项"
            )

        self._return_to_income_summary()
        # 零工资数据生成后先查询网页权威状态。已成功的公司立即记录并退出，
        # 只有“待申报”才允许继续算税和发送，避免重复申报。
        report_state = self._open_report_page_and_read_state(
            allow_pending_fallback=True
        )
        if report_state == "success":
            return "申报成功", "网页已显示申报成功，已记录并跳过重复申报"

        self._calculate_tax()

        # 算税完成后再次查询，兼容服务端在等待期间已经完成申报的情况。
        LOGGER.info("税款计算完成，直接点击第 4 步“申报表报送”")
        report_state = self._open_report_page_and_read_state(
            allow_pending_fallback=False,
            allow_send_button_pending=True,
        )
        if report_state == "success":
            return "申报成功", "网页已显示申报成功，已记录并跳过重复申报"

        send_button = self._wait_for_send_button()
        if send_button is None:
            return "申报成功", "发送前检测到网页已申报成功，未重复发送"
        if isinstance(send_button, VisualSendTarget):
            # 视觉等待阶段已经完成三帧业务状态与按钮唯一性确认。使用专用的
            # 有界容错复核后立即点击，避免重新走原生控件分支时被后台税款页
            # 的重叠 HWND 或单帧模板抖动错误否决。
            return self._submit_verified_visual_target(send_button)

        report_page = self._report_page(timeout=0)
        if report_page is None or not self._is_page_exposed(report_page):
            raise AutomationError("点击发送前报送页已不在前台，已停止发送")
        self.last_report_page = report_page
        if self._report_success_visible(report_page):
            return "申报成功", "点击发送前检测到网页已申报成功，未重复发送"
        if self._report_interaction_blocked():
            raise AutomationError("点击发送前检测到进度窗口或模态提示，已停止发送")
        explicit_pending = self._report_pending_visible(report_page)
        if not explicit_pending:
            raise AutomationError(
                "点击发送前未再次识别到明确的“待申报”状态，已停止发送"
            )
        try:
            current_page_handle = int(report_page.handle)
        except Exception as exc:
            raise AutomationError("点击发送前无法读取报送页句柄，已停止发送") from exc
        expected_page_handle = self.last_send_page_handle
        if (
            expected_page_handle is None
            or expected_page_handle <= 0
            or current_page_handle <= 0
            or current_page_handle != expected_page_handle
        ):
            raise AutomationError(
                "点击发送前报送页句柄发生变化，已停止发送并等待人工确认"
            )

        send_coordinates: tuple[int, int] | None = None
        requires_mouse_click = False
        blue_ratio = 0.0
        current_send_button = self._native_report_send_button(
            report_page,
            explicit_pending=True,
        )
        send_ready, requires_mouse_click, blue_ratio = (
            self._report_send_button_ready(
                current_send_button,
                explicit_pending=True,
            )
        )
        if current_send_button is None or not send_ready:
            raise AutomationError(
                "点击发送前未能再次确认前台报送页的“发送申报”按钮，已停止发送"
            )
        expected_button_handle = self.last_send_button_handle
        try:
            current_button_handle = int(current_send_button.handle)
        except Exception as exc:
            raise AutomationError(
                "点击发送前无法读取发送按钮句柄，已停止发送"
            ) from exc
        if (
            expected_button_handle is None
            or expected_button_handle <= 0
            or current_button_handle <= 0
            or current_button_handle != expected_button_handle
        ):
            raise AutomationError(
                "点击发送前按钮句柄发生变化，已停止发送并等待人工确认"
            )
        send_button = current_send_button
        if requires_mouse_click:
            try:
                send_rectangle = send_button.rectangle()
                send_coordinates = (
                    int(send_rectangle.left + send_rectangle.width() // 2),
                    int(send_rectangle.top + send_rectangle.height() // 2),
                )
            except Exception as exc:
                raise AutomationError(
                    "发送按钮蓝色状态已确认，但点击前无法读取按钮坐标；"
                    "申报状态需人工确认"
                ) from exc

        # 最终定位以后再做一次业务状态复核。视觉矩形稳定只能证明目标没移动，
        # 不能替代待申报授权；若此刻已经成功或出现遮挡，绝不继续点击。
        if self._report_success_visible(report_page):
            return "申报成功", "最终点击前检测到网页已申报成功，未重复发送"
        if self._report_interaction_blocked():
            raise AutomationError("最终点击前检测到进度窗口或模态提示，已停止发送")
        if not self._report_pending_visible(report_page):
            raise AutomationError("最终点击前待申报状态发生变化，已停止发送")
        if self.settings.dry_run:
            return "演练完成", "待申报且“发送申报”已启用，--dry-run 未发送"

        # 鼠标点击路径先完成无副作用的预定位。这样 FAILSAFE 或桌面输入异常
        # 会在 submission_started=False 时暴露，避免“实际未点却按提交后未知
        # 处理”。原生 click_input 路径不需要鼠标预定位。
        if requires_mouse_click:
            assert send_coordinates is not None
            try:
                self.pyautogui.moveTo(*send_coordinates, duration=0.10)
            except Exception as exc:
                raise AutomationError(
                    "发送按钮已确认，但鼠标无法移动到按钮；尚未点击发送申报"
                ) from exc

        # 从这里开始禁止自动重试，避免网络超时造成重复申报。
        self.submission_started = True
        if requires_mouse_click:
            LOGGER.info(
                "点击“发送申报”（蓝色按钮视觉确认 %.3f；从此处起禁止自动重试）",
                blue_ratio,
            )
            self.pyautogui.click(*send_coordinates)
        else:
            LOGGER.info("点击“发送申报”（从此处起禁止自动重试）")
            send_button.click_input()
        return self._continue_after_submission_click()


def _excel_cell_text(cell: Any) -> str:
    """读取 Excel 显示值，并尽量保留纯数字密码的前导零。"""

    value = cell.value
    if value is None:
        return ""
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, (int, float)):
        number_format = str(getattr(cell, "number_format", "") or "")
        if re.fullmatch(r"0+", number_format) and float(value).is_integer():
            return f"{int(value):0{len(number_format)}d}"
        if isinstance(value, float) and value.is_integer():
            return str(int(value))
    return str(value).strip()


def load_credentials(
    workbook: Path,
    start_row: int = 2,
    companies: Iterable[str] = (),
    max_rows: int | None = None,
) -> list[Credential]:
    try:
        from openpyxl import load_workbook
    except ImportError as exc:
        raise DependencyError("缺少 openpyxl，请执行：python -m pip install openpyxl") from exc

    workbook = workbook.expanduser().resolve()
    if not workbook.is_file():
        raise FileNotFoundError(f"账号表不存在：{workbook}")
    if max_rows is not None and max_rows <= 0:
        raise AutomationError("--max-rows 必须大于 0")
    selected = {str(value).strip().casefold() for value in companies if str(value).strip()}
    excel = load_workbook(workbook, read_only=True, data_only=True)
    try:
        sheet = excel.active
        result: list[Credential] = []
        for row_number, row in enumerate(
            sheet.iter_rows(min_row=max(start_row, 1), values_only=False),
            start=max(start_row, 1),
        ):
            company = _excel_cell_text(row[1]) if len(row) > 1 else ""
            password = _excel_cell_text(row[3]) if len(row) > 3 else ""
            if not company and not password:
                continue
            if not company or not password:
                LOGGER.warning("跳过账号表第 %d 行：公司或密码为空", row_number)
                continue
            if selected and company.casefold() not in selected:
                continue
            result.append(Credential(company, password, row_number))
            if max_rows is not None and len(result) >= max_rows:
                break
    finally:
        excel.close()
    if not result:
        suffix = "（公司筛选后）" if selected else ""
        raise AutomationError(f"账号表中没有可执行数据{suffix}")
    return result


def discover_workbook(path: Path) -> Path:
    """默认桌面文件不存在时，在桌面子目录中寻找唯一同名账号表。"""

    resolved = path.expanduser().resolve()
    if resolved.is_file():
        return resolved
    if resolved.name != DEFAULT_WORKBOOK.name:
        return resolved
    desktop = Path.home() / "Desktop"
    candidates = [candidate.resolve() for candidate in desktop.rglob(resolved.name)]
    candidates = [candidate for candidate in candidates if candidate.is_file()]
    if len(candidates) == 1:
        LOGGER.warning("默认账号表不存在，自动使用桌面子目录文件：%s", candidates[0])
        return candidates[0]
    if len(candidates) > 1:
        joined = "；".join(str(candidate) for candidate in candidates)
        raise AutomationError(f"找到多个同名账号表，请用 --workbook 指定：{joined}")
    return resolved


class ResultWorkbook:
    HEADERS = ("完成时间", "公司", "状态", "详情", "执行次数")

    def __init__(self, path: Path) -> None:
        self.path = path.expanduser().resolve()

    def append(self, result: RunResult) -> None:
        try:
            from openpyxl import Workbook, load_workbook
        except ImportError as exc:
            raise DependencyError("缺少 openpyxl，请执行：python -m pip install openpyxl") from exc

        self.path.parent.mkdir(parents=True, exist_ok=True)
        if self.path.exists():
            workbook = load_workbook(self.path)
            sheet = workbook.active
        else:
            workbook = Workbook()
            sheet = workbook.active
            sheet.title = "申报结果"
            sheet.append(self.HEADERS)
            sheet.freeze_panes = "A2"
            sheet.auto_filter.ref = "A1:E1"
            widths = {"A": 22, "B": 36, "C": 20, "D": 70, "E": 12}
            for column, width in widths.items():
                sheet.column_dimensions[column].width = width
        sheet.append(
            [
                result.finished_at,
                result.company,
                result.status,
                result.detail,
                result.attempt,
            ]
        )
        workbook.save(self.path)
        workbook.close()


def parse_year_month(value: str) -> str:
    """接受 YYYY-MM / YYYY.M，统一为可排序的 YYYY-MM。"""
    match = re.fullmatch(r"(\d{4})[-.](\d{1,2})", str(value).strip())
    if not match:
        raise ValueError("月份必须是 YYYY-MM，例如 2026-08")
    year, month = map(int, match.groups())
    if not 1 <= year <= 9999 or not 1 <= month <= 12:
        raise ValueError("月份超出有效范围")
    return f"{year:04d}-{month:02d}"


def declaration_export_period(
    settings: Settings, now: datetime | None = None,
) -> tuple[str, str]:
    now = now or datetime.now()
    start = parse_year_month(settings.export_start_month or f"{now.year}-01")
    end = parse_year_month(settings.export_end_month or now.strftime("%Y-%m"))
    if start > end:
        raise ValueError("导出开始月份不能晚于结束月份")
    return start, end


def system_desktop_directory() -> Path:
    """读取系统桌面目录，兼容重定向/OneDrive；API 不可用时退回用户桌面。"""
    if os.name == "nt":
        try:
            buffer = ctypes.create_unicode_buffer(32768)
            # CSIDL_DESKTOPDIRECTORY，而非逻辑桌面对象 CSIDL_DESKTOP。
            result = ctypes.windll.shell32.SHGetFolderPathW(None, 0x10, None, 0, buffer)
            if result == 0 and buffer.value:
                return Path(buffer.value).expanduser().resolve()
        except (AttributeError, OSError):
            pass
    return (Path.home() / "Desktop").resolve()


def declaration_archive_month(
    settings: Settings, now: datetime | None = None,
) -> str:
    """归档月份默认上月；不改变客户端申报月份或查询起止月份。"""
    if settings.declaration_month:
        return parse_year_month(settings.declaration_month)
    now = now or datetime.now()
    year, month = (now.year - 1, 12) if now.month == 1 else (now.year, now.month - 1)
    return parse_year_month(f"{year:04d}-{month:02d}")


def declaration_export_directory(
    settings: Settings, now: datetime | None = None,
) -> Path:
    """显式目录保持精确路径；缺省归档到系统桌面/财务报税/税款所属月份。"""
    if settings.export_dir is not None:
        return settings.export_dir.expanduser().resolve()
    month = declaration_archive_month(settings, now=now)
    return (system_desktop_directory() / "财务报税" / month).resolve()


def export_file_prefix(company: str, start: str, end: str) -> str:
    safe_company = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", company).strip(" .")[:100] or "公司"
    return f"申报记录_{safe_company}_{start}_{end}_"


def _export_file_digest(path: Path) -> tuple[int, str]:
    before = path.stat()
    if before.st_size <= 0:
        raise ValueError("导出文件为空")
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    after = path.stat()
    if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
        raise ValueError("导出文件校验期间仍在变化")
    return after.st_size, digest.hexdigest()


def record_completed_export(settings: Settings, company: str, path: Path) -> None:
    """仅在导出验证成功后调用；旁文件随导出目录一起复制到其他电脑。"""
    folder = declaration_export_directory(settings)
    path = path.expanduser().resolve()
    if path.parent != folder:
        raise ValueError("导出完成记录的文件必须位于指定导出目录")
    start, end = declaration_export_period(settings)
    size, digest = _export_file_digest(path)
    receipt = path.with_name(path.name + ".export-complete.json")
    temporary = receipt.with_name(f"{receipt.name}.{os.getpid()}.{os.urandom(6).hex()}.tmp")
    try:
        with temporary.open("x", encoding="utf-8") as stream:
            json.dump({
                "version": 1, "company": company,
                "start_month": start, "end_month": end,
                "filename": path.name, "size": size, "sha256": digest,
                "finished_at": datetime.now().isoformat(timespec="seconds"),
            }, stream, ensure_ascii=False)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, receipt)
    finally:
        if temporary.exists():
            temporary.unlink()


def _legacy_export_is_complete(path: Path) -> bool:
    """旧版没有完成标记，仅接受可检查结构的报表；未知类型不猜成功。"""
    try:
        if path.stat().st_size <= 0:
            return False
        if path.suffix.casefold() == ".xlsx":
            with zipfile.ZipFile(path) as archive:
                names = set(archive.namelist())
                valid_archive = bool(
                    {"[Content_Types].xml", "xl/workbook.xml"} <= names
                    and any(name.startswith("xl/worksheets/") and name.endswith(".xml") for name in names)
                    and archive.testzip() is None
                )
            if not valid_archive:
                return False
            try:
                from openpyxl import load_workbook
                # load_workbook 构造失败时没有可关闭的 book；由本层持有
                # 文件句柄，保证损坏 XML 的异常路径也能立即重命名/删除。
                with path.open("rb") as stream:
                    book = load_workbook(stream, read_only=True, data_only=True)
                    try:
                        for sheet in book.worksheets:
                            for _row in sheet.iter_rows(values_only=True):
                                pass
                        return bool(book.worksheets)
                    finally:
                        book.close()
            except Exception:
                # CRC 正确仍可能是内容损坏的 XML/无效工作簿。
                return False
        if path.suffix.casefold() == ".xls":
            # 只复用已安装的读取器，不为去重静默安装依赖。
            try:
                import xlrd
            except ImportError:
                return False
            try:
                book = xlrd.open_workbook(str(path), on_demand=False)
            except Exception:
                # 不同 xlrd 版本的格式错误异常类型不同；不能据此跳过公司。
                return False
            try:
                return book.nsheets > 0
            finally:
                book.release_resources()
        # 无完成标记的 CSV 即使能解码，也无法排除下载半途截断。
    except (OSError, ValueError, zipfile.BadZipFile, RuntimeError, zlib.error, EOFError):
        return False
    return False


def find_completed_export(settings: Settings, company: str) -> Path | None:
    """同一公司、同一范围且文件仍完整才跳过；不跨月复用完成记录。"""
    folder = declaration_export_directory(settings)
    start, end = declaration_export_period(settings)
    if not folder.is_dir():
        return None
    try:
        files = sorted(folder.iterdir(), key=lambda path: path.name, reverse=True)
    except OSError as exc:
        LOGGER.warning("无法检查导出目录，本次不跳过：%s", exc)
        return None
    for receipt in files:
        if not receipt.name.endswith(".export-complete.json"):
            continue
        try:
            if receipt.stat().st_size > 16384 or receipt.resolve().parent != folder:
                continue
            data = json.loads(receipt.read_text(encoding="utf-8"))
            if not isinstance(data, dict) or any((
                data.get("version") != 1, data.get("company") != company,
                data.get("start_month") != start, data.get("end_month") != end,
            )):
                continue
            filename = data.get("filename")
            if not isinstance(filename, str) or Path(filename).name != filename:
                continue
            if receipt.name != filename + ".export-complete.json":
                continue
            path = folder / filename
            if not path.is_file() or path.resolve().parent != folder:
                continue
            size, digest = _export_file_digest(path)
            if size == data.get("size") and digest == data.get("sha256"):
                return path
        except (OSError, ValueError, TypeError):
            continue
    # 旧文件名中的公司经过截断/替换时可能碰撞，必须有原始公司名完成标记。
    prefix = export_file_prefix(company, start, end)
    if prefix != f"申报记录_{company}_{start}_{end}_":
        return None
    for path in files:
        if not path.name.startswith(prefix) or not re.fullmatch(
            r"\d{8}_\d{6}_\d{6}\.(?:xlsx|xls|csv)", path.name[len(prefix):], re.IGNORECASE
        ):
            continue
        receipt = path.with_name(path.name + ".export-complete.json")
        # 已有标记但校验失败时绝不能再用旧文件格式检查绕过失败。
        if receipt.exists() or not path.is_file() or path.resolve().parent != folder:
            continue
        try:
            before = _export_file_digest(path)
            if _legacy_export_is_complete(path) and _export_file_digest(path) == before:
                LOGGER.info("已找到同公司同范围的完整旧版导出文件：%s", path)
                return path
        except (OSError, ValueError):
            continue
    return None


def _export_after_success(
    automation: TaxClientAutomation, company: str, detail: str,
) -> str:
    """导出是独立收尾阶段，失败绝不能触发申报重试。"""
    try:
        path = automation.export_declaration_records(company)
        return f"{detail}；申报记录导出完成：{path}"
    except Exception as exc:
        LOGGER.exception("%s 已申报成功，但申报记录导出失败；不会重新申报", company)
        try:
            automation.capture_diagnostics("record_export_failed")
        except Exception:
            LOGGER.exception("导出失败诊断采集失败；仍保留已确认的申报成功状态")
        return f"{detail}；申报记录导出失败：{type(exc).__name__}: {exc}；可使用 --export-records-only 补导出"


def _run_one_company(
    credential: Credential,
    settings: Settings,
    repository: ResourceRepository,
) -> RunResult:
    if (not settings.dry_run and not settings.force_export
            and (settings.export_records or settings.export_records_only)):
        downloaded = find_completed_export(settings, credential.company)
        if downloaded is not None:
            LOGGER.info("%s：同范围申报记录已下载，跳过本公司：%s", credential.company, downloaded)
            return RunResult(
                credential.company, "已下载跳过", f"同范围完整导出文件：{downloaded}",
                0, datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            )
    total_attempts = max(settings.retry_count, 0) + 1
    last_detail = ""
    for attempt in range(1, total_attempts + 1):
        automation = TaxClientAutomation(settings, repository)
        try:
            LOGGER.info(
                "[尝试 %d/%d] 开始处理：%s（账号表第 %d 行）",
                attempt,
                total_attempts,
                credential.company,
                credential.row_number,
            )
            automation.start()
            automation.login(credential)
            if settings.export_records_only:
                # 只登录查询/导出，不进入工资生成、算税或发送申报流程。
                try:
                    path = automation.export_declaration_records(credential.company)
                    status, detail = "导出完成", f"单位申报记录：{path}"
                except Exception as exc:
                    status, detail = "导出失败", f"{type(exc).__name__}: {exc}；未执行申报"
                    LOGGER.exception("%s 仅导出模式失败", credential.company)
                    try:
                        automation.capture_diagnostics("record_export_only_failed")
                    except Exception:
                        LOGGER.exception("仅导出失败诊断采集失败")
            else:
                status, detail = automation.declare()
                if (settings.export_records and not settings.dry_run
                        and status in {"申报成功", "已经申报过了"}):
                    detail = _export_after_success(automation, credential.company, detail)
            return RunResult(
                credential.company,
                status,
                detail,
                attempt,
                datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            )
        except DependencyError:
            # 系统环境错误与具体公司无关，继续跑 40 家只会重复失败。
            raise
        except CompanyNotFoundError as exc:
            if automation.last_diagnostic is None:
                automation.capture_diagnostics(f"company_not_found_attempt_{attempt}")
            return RunResult(
                credential.company,
                "没找到公司",
                str(exc),
                attempt,
                datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            )
        except Exception as exc:
            last_detail = f"{type(exc).__name__}: {exc}"
            # 先写出原始异常栈。诊断采集即使被系统 API 中断，也不会再吞掉
            # 真正的业务异常和后续重试信息。
            LOGGER.exception("%s 第 %d 次执行失败", credential.company, attempt)
            if automation.last_diagnostic is None:
                automation.capture_diagnostics(f"failure_attempt_{attempt}")
            if automation.submission_started:
                return RunResult(
                    credential.company,
                    "提交后状态未知",
                    last_detail + "；为避免重复申报，未自动重试",
                    attempt,
                    datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                )
            if automation.salary_generation_started:
                if automation.salary_generation_verified:
                    status = "工资明细生成后处理失败"
                    suffix = (
                        "；生成结果窗口已确认且明细页已恢复，"
                        "为避免重新生成工资明细，未自动重试"
                    )
                else:
                    status = "生成按钮状态未知"
                    suffix = (
                        "；零工资生成按钮已经尝试，是否送达或落库未知，"
                        "为避免重复生成，未自动重试"
                    )
                return RunResult(
                    credential.company,
                    status,
                    last_detail + suffix,
                    attempt,
                    datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                )
            if attempt < total_attempts:
                LOGGER.warning(
                    "%s 第 %d 次失败；关闭客户端后将进行第 %d/%d 次尝试",
                    credential.company,
                    attempt,
                    attempt + 1,
                    total_attempts,
                )
        finally:
            automation.stop()
        if attempt < total_attempts:
            # finally 已先关闭客户端，再给 Windows 留出释放进程与句柄的时间。
            time.sleep(2)

    return RunResult(
        credential.company,
        "执行失败",
        last_detail,
        total_attempts,
        datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    )


def configure_logging(log_file: Path | None = None) -> None:
    handlers: list[logging.Handler] = [logging.StreamHandler(sys.stdout)]
    if log_file:
        log_file = log_file.expanduser().resolve()
        log_file.parent.mkdir(parents=True, exist_ok=True)
        handlers.append(logging.FileHandler(log_file, encoding="utf-8"))
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
        handlers=handlers,
        force=True,
    )


def preflight_ui_environment() -> tuple[int, int]:
    """在批量循环前验证桌面截图，系统性错误只报告一次。"""

    cv2, np, _, _, _ = _load_ui_dependencies()
    frame, _, _ = _capture_screen_bgr(np)
    if frame.ndim != 3 or frame.shape[2] != 3 or frame.size == 0:
        raise DependencyError(f"Windows GDI 截图数据异常：shape={frame.shape!r}")
    ok, _ = cv2.imencode(".png", frame[: min(frame.shape[0], 64), : min(frame.shape[1], 64)])
    if not ok:
        raise DependencyError("OpenCV 无法编码 Windows GDI 截图")
    return int(frame.shape[1]), int(frame.shape[0])


def execute(
    settings: Settings,
    *,
    configure_run_logging: bool = True,
    on_progress: Callable[[int, int], None] | None = None,
) -> dict[str, Any]:
    # 在启动客户端和读取账号前校验，错误配置不能在申报完成后才暴露。
    if settings.export_records or settings.export_records_only:
        # 用同一运行时刻冻结目录和查询范围，跨月运行也不分散到其他月份。
        now = datetime.now()
        start, end = declaration_export_period(settings, now=now)
        month = declaration_archive_month(settings, now=now)
        folder = declaration_export_directory(settings, now=now)
        settings = replace(
            settings, export_start_month=start, export_end_month=end,
            declaration_month=month, export_dir=folder,
        )
    if settings.export_records_only and settings.dry_run:
        raise ValueError("--export-records-only 与 --dry-run 不能同时使用")
    if configure_run_logging:
        configure_logging(settings.log_file or settings.result_file.with_suffix(".log"))
    repository = ResourceRepository(settings.resource_root)
    if settings.check_resources:
        result = {
            "resource_root": str(repository.root),
            "image_count": len(repository.images),
            "selector_count": len(repository.selectors),
            "images": sorted(repository.images),
            "selectors": sorted(repository.selectors),
        }
        LOGGER.info(
            "资源检查通过：%d 个图像模板，%d 个控件选择器",
            len(repository.images),
            len(repository.selectors),
        )
        return result

    screen_width, screen_height = preflight_ui_environment()
    LOGGER.info(
        "桌面自动化环境检查通过：Windows GDI 截图 %dx%d（无需 Pillow/PyScreeze）",
        screen_width,
        screen_height,
    )
    workbook_path = discover_workbook(settings.workbook)
    settings = replace(settings, workbook=workbook_path)
    credentials = load_credentials(
        workbook_path,
        start_row=settings.start_row,
        companies=settings.companies,
        max_rows=settings.max_rows,
    )
    LOGGER.info("共读取 %d 家公司；密码不会写入日志或结果文件", len(credentials))
    result_book = ResultWorkbook(settings.result_file)
    results: list[RunResult] = []
    if on_progress is not None:
        on_progress(0, len(credentials))
    for credential in credentials:
        result = _run_one_company(credential, settings, repository)
        results.append(result)
        result_book.append(result)
        LOGGER.info("%s：%s - %s", result.company, result.status, result.detail)
        if on_progress is not None:
            on_progress(len(results), len(credentials))

    success_statuses = {"申报成功", "已经申报过了", "没有信息", "演练完成", "导出完成", "已下载跳过"}
    return {
        "output_file": str(settings.result_file.expanduser().resolve()),
        "total": len(results),
        "successful": sum(item.status in success_statuses for item in results),
        "failed": sum(item.status not in success_statuses for item in results),
        "skipped": sum(item.status == "已下载跳过" for item in results),
        "results": [asdict(item) for item in results],
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="自然人电子税务局（扣缴端）批量申报（影刀流程 Python 版）"
    )
    parser.add_argument("--workbook", type=Path, default=DEFAULT_WORKBOOK, help="账号表；B 列公司、D 列申报密码")
    parser.add_argument("--app-path", type=Path, default=Path(os.getenv("TAX_APP_PATH", str(DEFAULT_APP_PATH))), help="电子税务局启动程序")
    parser.add_argument("--resource-root", type=Path, default=DEFAULT_RESOURCE_ROOT, help="内置图片释放目录，默认位于脚本同目录")
    parser.add_argument("--result-file", type=Path, default=DEFAULT_RESULT_FILE, help="申报结果 Excel")
    parser.add_argument("--start-row", type=int, default=2, help="账号表起始行，默认 2")
    parser.add_argument("--company", dest="companies", action="append", default=[], help="只执行指定公司；可重复传入")
    parser.add_argument("--max-rows", type=int, default=None, help="最多执行多少家；不设置则执行全部")
    parser.add_argument("--retry-count", type=int, default=1, help="发送申报前失败的额外重试次数，默认 1")
    parser.add_argument("--startup-delay", type=float, default=8, help="启动客户端后预等待秒数，默认 8")
    parser.add_argument("--startup-timeout", type=float, default=90, help="客户端启动超时秒数")
    parser.add_argument("--page-timeout", type=float, default=120, help="页面/申报反馈超时秒数")
    parser.add_argument("--dry-run", action="store_true", help="走到发送申报按钮但不点击")
    parser.add_argument("--check-resources", action="store_true", help="仅校验影刀图片和选择器资源，不启动客户端")
    parser.add_argument("--log-file", type=Path, default=None, help="日志文件，默认与结果表同名 .log")
    parser.add_argument("--no-export-records", action="store_true", help="申报成功后不导出单位申报记录")
    parser.add_argument("--export-dir", type=Path, default=None, help="单位申报记录精确保存目录；默认系统桌面/财务报税/税款所属月份")
    parser.add_argument("--declaration-month", type=parse_year_month, default=None, help="归档月份 YYYY-MM，默认上月；仅控制默认目录，不改变客户端申报月份或查询范围")
    parser.add_argument("--export-start-month", type=parse_year_month, default=None, help="导出起始月份 YYYY-MM，默认当年 1 月")
    parser.add_argument("--export-end-month", type=parse_year_month, default=None, help="导出结束月份 YYYY-MM，默认运行当月")
    parser.add_argument("--export-records-only", action="store_true", help="仅登录、查询和导出，不生成工资、不算税、不发送申报")
    parser.add_argument("--force-export", action="store_true", help="忽略已有下载记录，强制重新查询导出（仍不重复发送已申报数据）")
    return parser


def _settings_from_namespace(namespace: argparse.Namespace) -> Settings:
    return Settings(
        workbook=namespace.workbook,
        app_path=namespace.app_path,
        resource_root=namespace.resource_root,
        result_file=namespace.result_file,
        start_row=max(namespace.start_row, 1),
        companies=tuple(namespace.companies),
        max_rows=namespace.max_rows,
        retry_count=max(namespace.retry_count, 0),
        startup_delay=max(namespace.startup_delay, 0),
        startup_timeout=max(namespace.startup_timeout, 1),
        page_timeout=max(namespace.page_timeout, 1),
        dry_run=namespace.dry_run,
        check_resources=namespace.check_resources,
        log_file=namespace.log_file,
        export_records=not namespace.no_export_records,
        export_dir=namespace.export_dir,
        declaration_month=namespace.declaration_month,
        export_start_month=namespace.export_start_month,
        export_end_month=namespace.export_end_month,
        export_records_only=namespace.export_records_only,
        force_export=namespace.force_export,
    )


def _settings_from_mapping(args: Mapping[str, Any]) -> Settings:
    def value(name: str, default: Any) -> Any:
        return args.get(name, args.get(name.replace("_", "-"), default))

    def boolean(name: str, default: bool = False) -> bool:
        raw = value(name, default)
        if isinstance(raw, str):
            return raw.strip().casefold() in {"1", "true", "yes", "y", "on", "是"}
        return bool(raw)

    raw_companies = value("companies", value("company", ()))
    if isinstance(raw_companies, str):
        companies = (raw_companies,)
    else:
        companies = tuple(raw_companies or ())
    raw_max_rows = value("max_rows", None)
    raw_log_file = value("log_file", None)
    raw_export_dir = value("export_dir", None)
    return Settings(
        workbook=Path(value("workbook", DEFAULT_WORKBOOK)),
        app_path=Path(value("app_path", os.getenv("TAX_APP_PATH", str(DEFAULT_APP_PATH)))),
        resource_root=Path(value("resource_root", DEFAULT_RESOURCE_ROOT)),
        result_file=Path(value("result_file", DEFAULT_RESULT_FILE)),
        start_row=max(int(value("start_row", 2)), 1),
        companies=companies,
        max_rows=int(raw_max_rows) if raw_max_rows not in (None, "") else None,
        retry_count=max(int(value("retry_count", 1)), 0),
        startup_delay=max(float(value("startup_delay", 8)), 0),
        startup_timeout=max(float(value("startup_timeout", 90)), 1),
        page_timeout=max(float(value("page_timeout", 120)), 1),
        dry_run=boolean("dry_run"),
        check_resources=boolean("check_resources"),
        log_file=Path(raw_log_file) if raw_log_file else None,
        export_records=boolean("export_records", True) and not boolean("no_export_records"),
        export_dir=Path(raw_export_dir) if raw_export_dir not in (None, "") else None,
        declaration_month=value("declaration_month", None),
        export_start_month=value("export_start_month", None),
        export_end_month=value("export_end_month", None),
        export_records_only=boolean("export_records_only"),
        force_export=boolean("force_export"),
    )


def main(args: Mapping[str, Any] | Sequence[str] | None = None) -> dict[str, Any]:
    """CLI 与影刀式 ``main(args)`` 共用入口。"""

    if isinstance(args, Mapping):
        settings = _settings_from_mapping(args)
        result = execute(settings)
        if isinstance(args, dict) and result.get("output_file"):
            args["output_file"] = result["output_file"]
        return result
    namespace = build_parser().parse_args(args)
    settings = _settings_from_namespace(namespace)
    result = execute(settings)
    if settings.check_resources:
        print(result)
    else:
        LOGGER.info(
            "全部完成：总计 %d，成功/正常 %d，失败 %d，结果：%s",
            result["total"],
            result["successful"],
            result["failed"],
            result["output_file"],
        )
    return result


if __name__ == "__main__":
    main()
